/* Fiches d'arrêt préchargées (jurisprudence), générées par scripts/jurisprudence/build.py — ne pas modifier ici. */
window.JURISPRUDENCE = [{"titre":"Gosset (1re civ.)","juridiction":"Cour de cassation","date":"1963-05-07","matiere":"Arbitrage","niveau":"M1-M2","faits":"Un contrat de vente de commerce international contient une clause compromissoire ; l'une des parties soutient que la nullité du contrat principal emporte celle de la clause.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"La clause compromissoire est-elle affectée par la nullité du contrat qui la contient ?","solution":"Non : en matière d'arbitrage international, l'accord compromissoire, qu'il soit conclu séparément ou inclus dans l'acte juridique auquel il a trait, présente toujours, sauf circonstances exceptionnelles, une complète autonomie juridique excluant qu'il puisse être affecté par une éventuelle invalidité de cet acte.","portee":"Consacre l'autonomie de la clause compromissoire en arbitrage international ; repris par l'article 1447 du Code de procédure civile.","tags":["autonomie de la clause compromissoire","contrat international","grand arrêt"],"id":"seed-jp-1963-05-07-gosset-1re-civ"},{"titre":"Hecht c. Buismans (1re civ.)","juridiction":"Cour de cassation","date":"1972-07-04","matiere":"Arbitrage","niveau":"M1-M2","faits":"Une société néerlandaise et un agent commercial sont liés par un contrat comportant une clause compromissoire ; l'agent la conteste en invoquant la loi française qui limitait ces clauses.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"La prohibition des clauses compromissoires du droit interne s'applique-t-elle aux contrats internationaux ?","solution":"Non : la prohibition de l'ancien article 2061 du Code civil ne s'applique pas aux contrats internationaux ; la clause compromissoire est valable dans un tel contrat.","portee":"Dissocie le régime de l'arbitrage international de celui de l'arbitrage interne.","tags":["clause compromissoire","validité","contrat international"],"id":"seed-jp-1972-07-04-hecht-c-buismans-1re-civ"},{"titre":"Dalico (1re civ.)","juridiction":"Cour de cassation","date":"1993-12-20","matiere":"Arbitrage","niveau":"M1-M2","faits":"Une société danoise et une municipalité libyenne ont conclu un contrat d'ingénierie contenant une clause d'arbitrage ; la municipalité conteste la clause en invoquant le droit libyen.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Quelle loi apprécie la validité de la clause compromissoire dans un arbitrage international ?","solution":"En vertu d'une règle matérielle du droit international de l'arbitrage, la clause compromissoire est indépendante juridiquement du contrat principal ; son existence et son efficacité s'apprécient, sous réserve des règles impératives du droit français et de l'ordre public international, d'après la commune volonté des parties, sans qu'il soit nécessaire de se référer à une loi étatique.","portee":"Règle matérielle du droit français de l'arbitrage international, qui écarte les règles de conflit.","tags":["clause compromissoire","règle matérielle","indépendance"],"attendu":"En vertu d'une règle matérielle du droit international de l'arbitrage, la clause compromissoire est indépendante juridiquement du contrat principal qui la contient directement ou par référence et son existence et son efficacité s'apprécient, sous réserve des règles impératives du droit français et de l'ordre public international, d'après la commune volonté des parties, sans qu'il soit nécessaire de se référer à une loi étatique.","id":"seed-jp-1993-12-20-dalico-1re-civ"},{"titre":"Hilmarton (1re civ.)","juridiction":"Cour de cassation","date":"1994-03-23","matiere":"Arbitrage","niveau":"M2","faits":"Une sentence rendue en Suisse, qui donne raison à une entreprise française contre un consultant parce que leur contrat serait illicite, est annulée par les juridictions suisses ; l'entreprise en demande pourtant l'exequatur en France.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation contre l'exequatur de la sentence annulée.","probleme":"Une sentence annulée dans l'État du siège peut-elle être reconnue et exécutée en France ?","solution":"Oui : la sentence internationale n'est pas intégrée dans l'ordre juridique de l'État du siège ; son annulation n'est pas, en droit français, un motif de refus de reconnaissance (art. 1502 ancien) ; elle peut être exécutée en France si elle ne contrevient pas à l'ordre public international.","portee":"Position française très libérale, confirmée par Putrabali (2007) et critiquée à l'étranger ; l'article 1525 la prolonge.","tags":["sentence annulée à l'étranger","exequatur","arbitrage international"],"id":"seed-jp-1994-03-23-hilmarton-1re-civ"},{"titre":"Eco Swiss China Time c. Benetton","juridiction":"CJUE","date":"1999-06-01","matiere":"Arbitrage","niveau":"M2","faits":"Une sentence arbitrale néerlandaise exécute un contrat de licence qui viole le droit européen de la concurrence ; la partie condamnée en demande l'annulation.","procedure":"Question préjudicielle du Hoge Raad des Pays-Bas.","probleme":"Le juge saisi d'un recours en annulation doit-il faire droit à un moyen tiré de la violation de l'article 101 TFUE ?","solution":"Oui : l'article 101 TFUE est une disposition d'ordre public européen ; le juge national doit faire droit à une demande d'annulation fondée sur sa méconnaissance, si ses règles nationales le permettent pour la violation de règles d'ordre public.","portee":"Affirme que le droit européen de la concurrence relève de l'ordre public dans l'arbitrage.","tags":["ordre public européen","concurrence","annulation de sentence"],"id":"seed-jp-1999-06-01-eco-swiss-china-time-c-benetton"},{"titre":"Putrabali (1re civ.)","juridiction":"Cour de cassation","date":"2007-06-29","matiere":"Arbitrage","niveau":"M2","faits":"Un vendeur indonésien de poivre blanc réclame le prix d'une cargaison perdue en mer ; une première sentence rendue à Londres donne raison à l'acheteur français, puis le juge anglais l'annule en partie et une seconde sentence condamne l'acheteur à payer ; l'acheteur demande l'exequatur de la première sentence en France.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"La sentence internationale est-elle rattachée à un ordre juridique étatique ?","solution":"Non : la sentence internationale, qui n'est rattachée à aucun ordre juridique étatique, est une décision de justice internationale dont la régularité est examinée au regard des règles applicables dans le pays où la reconnaissance et l'exécution sont demandées.","portee":"Consécration de la conception « autonome » de la sentence ; applicable avec l'article 1520 du Code de procédure civile.","tags":["sentence internationale","ordre juridique","reconnaissance"],"attendu":"La sentence internationale, qui n'est rattachée à aucun ordre juridique étatique, est une décision de justice internationale dont la régularité est examinée au regard des règles applicables dans le pays où sa reconnaissance et son exécution sont demandées.","id":"seed-jp-2007-06-29-putrabali-1re-civ"},{"titre":"West Tankers","juridiction":"CJUE","date":"2009-02-10","matiere":"Arbitrage","niveau":"M2","faits":"Un juge anglais interdit à un assureur italien d'agir devant un tribunal italien en raison d'une clause d'arbitrage ; l'assureur conteste.","procedure":"Question préjudicielle de la House of Lords.","probleme":"Une juridiction nationale peut-elle interdire à une partie de saisir un juge d'un autre État membre en invoquant une convention d'arbitrage ?","solution":"Non : une injonction de ne pas agir devant un juge d'un autre État membre, fondée sur une convention d'arbitrage, est incompatible avec le règlement Bruxelles I, car elle prive ce juge du pouvoir de statuer sur sa compétence.","portee":"Limite les anti-suit injunctions dans l'Union ; dernier mot au règlement Bruxelles I bis (considérant 12).","tags":["anti-suit injunction","arbitrage","règlement Bruxelles I"],"id":"seed-jp-2009-02-10-west-tankers"},{"titre":"INSERM c. Fondation Letten F. Saugstad (TC)","juridiction":"Tribunal des conflits","date":"2010-05-17","matiere":"Arbitrage","niveau":"M2","faits":"Un établissement public français (l'INSERM) conclut avec une fondation norvégienne un contrat de recherche comportant une clause d'arbitrage ; après une sentence rendue en 2007, il la conteste à la fois devant la cour d'appel de Paris et devant la cour administrative d'appel de Marseille.","procedure":"Le Conseil d'État renvoie au Tribunal des conflits la question de la juridiction compétente.","probleme":"À quelle juridiction appartient le contrôle d'une sentence rendue dans un arbitrage international qui met en jeu les intérêts du commerce international ?","solution":"Au juge judiciaire : le recours en annulation de la sentence rendue dans un arbitrage international relève de la cour d'appel, même lorsqu'une personne publique est partie.","portee":"S'inscrit dans le prolongement de l'arrêt Galakis (Cass. 1re civ., 2 mai 1966) : l'interdiction de compromettre des personnes publiques est écartée en arbitrage international.","tags":["arbitrage","personne publique","contrat international"],"id":"seed-jp-2010-05-17-inserm-c-fondation-letten-f-saugstad-tc"},{"titre":"Société Fosmax LNG (Ass.)","juridiction":"Conseil d'État","date":"2016-11-09","matiere":"Arbitrage","niveau":"M2","faits":"Une société exploitant un terminal méthanier, liée par un marché de travaux soumis aux règles de la commande publique, conteste la sentence arbitrale qui a statué sur les retards et défauts de construction en appliquant le droit privé.","procedure":"Après la décision du Tribunal des conflits du 11 avril 2016 (compétence du juge administratif), recours en annulation devant le Conseil d'État, assemblée du contentieux.","probleme":"Dans quelles conditions le juge administratif contrôle-t-il une sentence arbitrale rendue sur un contrat administratif ?","solution":"Le juge administratif contrôle la sentence au regard de l'ordre public et des règles impératives du droit public ; l'application de ces règles s'impose aux arbitres lorsqu'elles touchent à l'intérêt général.","portee":"Confirme que la sentence ne doit pas contrevenir aux règles d'ordre public de droit administratif.","tags":["arbitrage","contrat administratif","ordre public"],"id":"seed-jp-2016-11-09-societe-fosmax-lng-ass"},{"titre":"Cadot","juridiction":"Conseil d'État","date":"1889-12-13","matiere":"Droit administratif","niveau":"L2","faits":"Un fonctionnaire municipal de Marseille dont l'emploi a été supprimé demande une indemnité ; le ministre de l'Intérieur rejette sa demande.","procedure":"Le requérant saisit directement le Conseil d'État de la décision ministérielle.","probleme":"Le Conseil d'État peut-il être saisi directement d'une demande qui relevait traditionnellement du ministre, juge de droit commun de l'administration ?","solution":"Oui : le ministre n'est plus juge de droit commun du contentieux administratif ; le Conseil d'État est compétent pour connaître directement de toutes les affaires administratives.","portee":"Abandonne la théorie du « ministre-juge » : le Conseil d'État devient juge de droit commun en premier ressort de l'administration (jusqu'à la réforme de 1953).","tags":["compétence","ministre-juge","grand arrêt"],"id":"seed-jp-1889-12-13-cadot"},{"titre":"Cames (Sect.)","juridiction":"Conseil d'État","date":"1895-06-21","matiere":"Droit administratif","niveau":"L2","faits":"Un ouvrier de l'arsenal de Tarbes est blessé à la main par un éclat de métal projeté sous le choc d'un marteau-pilon, sans négligence ni imprudence de sa part ; le ministre de la Guerre fixe son indemnité et il la conteste.","procedure":"Recours devant le Conseil d'État, qui reconnaît la responsabilité de l'État.","probleme":"L'État est-il responsable d'un accident du travail subi par un agent même sans faute de l'administration ?","solution":"Oui : la responsabilité de l'État est engagée sur le fondement du risque professionnel, sans faute, en l'absence de législation sur les accidents du travail.","portee":"Première application de la responsabilité sans faute pour risque professionnel dans le droit administratif.","tags":["responsabilité sans faute","risque professionnel"],"id":"seed-jp-1895-06-21-cames-sect"},{"titre":"Casanova","juridiction":"Conseil d'État","date":"1901-03-29","matiere":"Droit administratif","niveau":"L2","faits":"Un conseil municipal décide de recruter un médecin et de l'indemniser sur le budget de la commune ; un contribuable de la commune conteste la délibération.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Un contribuable communal a-t-il intérêt à contester une délibération du conseil municipal entraînant une dépense ?","solution":"Oui : la qualité de contribuable communal confère un intérêt à agir contre une délibération qui engage les finances de la commune ; le recours est recevable.","portee":"Assouplit l'intérêt à agir en excès de pouvoir ; le contribuable local peut contester les décisions qui grèvent les finances communales.","tags":["intérêt à agir","contribuable","REP"],"id":"seed-jp-1901-03-29-casanova"},{"titre":"Terrier","juridiction":"Conseil d'État","date":"1903-02-06","matiere":"Droit administratif","niveau":"L2","faits":"Un département offre une prime pour la destruction des vipères ; un particulier réclame le paiement de la prime et se heurte à un refus.","procedure":"Recours devant le Conseil d'État contre le refus de paiement.","probleme":"Quelle est la juridiction compétente pour un litige né de l'activité du service public ?","solution":"Le litige relève de la juridiction administrative car il concerne le fonctionnement d'un service public ; les règles applicables sont celles du droit administratif.","portee":"Fait du service public le critère de compétence de la juridiction administrative, après Blanco ; critère de l'« École du service public ».","tags":["service public","compétence","contentieux"],"id":"seed-jp-1903-02-06-terrier"},{"titre":"Thérond","juridiction":"Conseil d'État","date":"1910-03-04","matiere":"Droit administratif","niveau":"L2","faits":"Un particulier s'est vu confier le ramassage et la mise en fourrière des chiens errants par une commune ; il réclame une indemnité à la suite de la fin de son contrat.","procedure":"Recours devant le Conseil d'État, qui se déclare compétent.","probleme":"Un contrat portant sur le fonctionnement d'un service public relève-t-il du droit administratif ?","solution":"Oui : le contrat concerne un service public (lutte contre la divagation des animaux) ; il est administratif et le litige relève du juge administratif.","portee":"Applique le critère du service public au contrat : critère matériel du contrat administratif (v. aussi Époux Bertin, 1956).","tags":["service public","contrat administratif","fourrière"],"id":"seed-jp-1910-03-04-therond"},{"titre":"Compagnie générale française des tramways","juridiction":"Conseil d'État","date":"1910-03-11","matiere":"Droit administratif","niveau":"L2-L3","faits":"Une collectivité modifie unilatéralement le service des tramways, sans l'accord du concessionnaire, pour répondre aux besoins du service.","procedure":"Le concessionnaire saisit le Conseil d'État.","probleme":"L'administration peut-elle imposer à son cocontractant une modification du contrat sans son accord ?","solution":"Oui : l'administration peut modifier unilatéralement le contrat pour les besoins du service public, avec l'obligation de maintenir l'équilibre financier du contrat par une indemnisation du cocontractant.","portee":"Consacre le pouvoir de modification unilatérale, avec le droit du cocontractant à compensation (équilibre financier).","tags":["contrat administratif","modification unilatérale","service public"],"id":"seed-jp-1910-03-11-compagnie-generale-francaise-des-tramway"},{"titre":"Anguet","juridiction":"Conseil d'État","date":"1911-02-03","matiere":"Droit administratif","niveau":"L2","faits":"Un usager sort d'un bureau de poste par la porte de service parce que la porte principale était fermée ; des agents le brutalisent et le blessent.","procedure":"Recours devant le Conseil d'État, qui retient une faute de service.","probleme":"Quand la faute de service coexiste avec une faute personnelle, la responsabilité de l'administration peut-elle être engagée ?","solution":"Oui : la faute de service (fermeture prématurée de la porte principale) engage la responsabilité de l'administration, alors même que les agents ont aussi commis une faute personnelle.","portee":"Illustre le cumul de fautes et prépare l'arrêt Lemonnier (1918) ; la victime peut agir contre l'administration.","tags":["faute de service","faute personnelle","cumul"],"id":"seed-jp-1911-02-03-anguet"},{"titre":"Gomel (Sect.)","juridiction":"Conseil d'État","date":"1914-04-04","matiere":"Droit administratif","niveau":"L2","faits":"Le préfet refuse un permis de construire place Beauvau en invoquant une perspective monumentale, qu'il estime menacée.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Le juge peut-il contrôler la qualification juridique des faits qui fondent une décision ?","solution":"Oui : le juge vérifie que les faits invoqués sont de nature à justifier la décision ; ici la place ne constitue pas une « perspective monumentale » et le refus est annulé.","portee":"Consacre le contrôle de la qualification juridique des faits (Gomel) ; il s'ajoute au contrôle des faits (Camino).","tags":["qualification juridique","contrôle","urbanisme"],"id":"seed-jp-1914-04-04-gomel-sect"},{"titre":"Camino","juridiction":"Conseil d'État","date":"1916-01-14","matiere":"Droit administratif","niveau":"L2","faits":"Le maire d'Hendaye, médecin, est suspendu puis révoqué pour avoir manqué à la décence d'un convoi funèbre et exercé des vexations envers une ambulance privée ; il conteste les motifs retenus.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Le juge de l'excès de pouvoir peut-il contrôler l'exactitude matérielle des faits sur lesquels repose une décision ?","solution":"Oui : le juge vérifie si les faits qui ont motivé la sanction sont matériellement exacts ; en l'espèce, les faits sont contredits par l'instruction et la sanction est annulée.","portee":"Naissance du contrôle de l'exactitude matérielle des faits, premier degré du contrôle des motifs.","tags":["contrôle des faits","exactitude matérielle","sanction"],"id":"seed-jp-1916-01-14-camino"},{"titre":"Compagnie générale d'éclairage de Bordeaux","juridiction":"Conseil d'État","date":"1916-03-30","matiere":"Droit administratif","niveau":"L2-L3","faits":"Pendant la guerre, le prix du charbon augmente brutalement, bouleversant l'économie d'un contrat de concession de l'éclairage au gaz.","procedure":"La compagnie concessionnaire demande une révision de ses tarifs ou une indemnité.","probleme":"Un événement imprévisible peut-il justifier une aide à l'exécution d'un contrat administratif ?","solution":"Oui : lorsque survient un événement imprévisible, extérieur aux parties, qui bouleverse l'économie du contrat, le cocontractant doit poursuivre le service et peut obtenir une indemnité d'imprévision.","portee":"Fonde la théorie de l'imprévision, propre au droit administratif ; le droit civil ne l'admettait pas alors (Canal de Craponne) et ne l'a admise qu'avec l'article 1195 du Code civil.","tags":["imprévision","concession","contrat administratif"],"id":"seed-jp-1916-03-30-compagnie-generale-d-eclairage-de-bordea"},{"titre":"Heyriès (Sect.)","juridiction":"Conseil d'État","date":"1918-06-28","matiere":"Droit administratif","niveau":"L2-L3","faits":"Pendant la Première Guerre mondiale, un décret du 10 septembre 1914 suspend la communication du dossier avant toute sanction disciplinaire ; un dessinateur civil du génie militaire est révoqué sans avoir pu consulter son dossier.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"L'administration peut-elle s'affranchir de la légalité normale en période de circonstances exceptionnelles ?","solution":"Oui : en cas de circonstances exceptionnelles, la légalité ordinaire peut être suspendue ; l'administration est dispensée de respecter des garanties que les circonstances ne lui permettent pas d'observer, sous contrôle du juge.","portee":"Consacre la théorie des circonstances exceptionnelles, dégagée ensuite par Dol et Laurent (1919) et complétée par l'état d'urgence.","tags":["circonstances exceptionnelles","légalité","guerre"],"id":"seed-jp-1918-06-28-heyries-sect"},{"titre":"Époux Lemonnier","juridiction":"Conseil d'État","date":"1918-07-26","matiere":"Droit administratif","niveau":"L2","faits":"Une fête communale comporte un stand de tir ; un promeneur est blessé par une balle, la sécurité du tir n'ayant pas été correctement assurée.","procedure":"Recours devant le Conseil d'État contre la commune.","probleme":"La victime peut-elle demander réparation à l'administration quand la faute personnelle d'un agent est liée au service ?","solution":"Oui : la victime peut agir contre l'administration et contre l'agent ; la faute personnelle n'exclut pas la faute de service. La commune est responsable des défauts d'organisation du service.","portee":"Fonde la règle du cumul de fautes et de responsabilités : la victime choisit son débiteur ; l'administration dispose d'actions récursoires.","tags":["cumul de fautes","responsabilité de la commune"],"id":"seed-jp-1918-07-26-epoux-lemonnier"},{"titre":"Regnault-Desroziers (Sect.)","juridiction":"Conseil d'État","date":"1919-03-28","matiere":"Droit administratif","niveau":"L2-L3","faits":"L'explosion d'un dépôt de munitions situé dans un fort, au voisinage d'habitations, cause de graves dommages aux riverains.","procedure":"Recours indemnitaire devant le Conseil d'État.","probleme":"L'administration est-elle responsable sans faute d'un dommage causé par la création d'un risque spécial pour le voisinage ?","solution":"Oui : la responsabilité sans faute est engagée en raison du risque spécial créé par le dépôt de munitions pour les riverains.","portee":"Fonde la responsabilité sans faute pour risque spécial (choses dangereuses).","tags":["risque spécial","responsabilité sans faute","dommages"],"id":"seed-jp-1919-03-28-regnault-desroziers-sect"},{"titre":"Labonne","juridiction":"Conseil d'État","date":"1919-08-08","matiere":"Droit administratif","niveau":"L2-L3","faits":"Un conducteur se voit retirer son certificat de capacité de conduite par le préfet de police, sur le fondement d'un décret du 10 mars 1899 sur la circulation des automobiles ; il conteste la compétence du chef de l'État pour édicter ce décret.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Le Président de la République a-t-il, sans habilitation législative, le pouvoir d'édicter des règlements de police applicables à l'ensemble du territoire ?","solution":"Oui : le chef de l'État tient de ses attributions constitutionnelles le pouvoir de réglementer la police à l'échelle nationale, en dehors de toute habilitation législative.","portee":"Source du pouvoir de police générale du chef de l'État ; sous la Ve République, il appartient au Premier ministre (art. 21).","tags":["pouvoir de police","Président de la République","règlement"],"id":"seed-jp-1919-08-08-labonne"},{"titre":"Dame Cachet","juridiction":"Conseil d'État","date":"1922-11-03","matiere":"Droit administratif","niveau":"L2-L3","faits":"Une propriétaire obtient du directeur de l'enregistrement une indemnité pour perte de loyer, en application de la loi du 9 mars 1918 sur l'exonération de loyers de familles modestes ; elle saisit le ministre des Finances, qui, plus tard, supprime l'indemnité déjà accordée au motif que le bien est de caractère rural.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"L'administration peut-elle retirer une décision créatrice de droits illégale, et dans quel délai ?","solution":"Une décision explicite créatrice de droits ne peut être retirée que si elle est illégale et dans le délai du recours contentieux (deux mois) ; passé ce délai, elle est définitive.","portee":"Règle fondatrice du retrait d'actes créateurs de droits ; modifiée par Ternon (2001), qui a fixé un délai de quatre mois.","tags":["retrait","acte créateur de droits","délai de recours"],"id":"seed-jp-1922-11-03-dame-cachet"},{"titre":"Couitéas","juridiction":"Conseil d'État","date":"1923-11-30","matiere":"Droit administratif","niveau":"L2","faits":"Un propriétaire obtient du juge l'expulsion d'occupants nombreux, mais l'administration refuse le concours de la force publique par crainte de troubles graves.","procedure":"Recours indemnitaire devant le Conseil d'État.","probleme":"L'État peut-il refuser de prêter son concours à l'exécution d'une décision de justice et, dans ce cas, doit-il réparer ?","solution":"L'administration peut refuser la force publique si des raisons d'ordre public le justifient ; mais ce refus ne doit pas faire peser sur l'intéressé une charge qu'il n'a pas à supporter : l'État l'indemnise sans faute (rupture d'égalité devant les charges publiques).","portee":"Fondement de la responsabilité sans faute pour rupture de l'égalité devant les charges publiques.","tags":["responsabilité sans faute","force publique","rupture d'égalité"],"id":"seed-jp-1923-11-30-couiteas"},{"titre":"Action française (TC)","juridiction":"Tribunal des conflits","date":"1935-04-08","matiere":"Droit administratif","niveau":"L3","faits":"L'administration fait saisir des exemplaires du journal L'Action française dans des conditions irrégulières.","procedure":"Le Tribunal des conflits tranche la compétence entre les juridictions administrative et judiciaire.","probleme":"Qu'est-ce que la voie de fait, et quel juge est compétent pour la réprimer ?","solution":"Il y a voie de fait lorsque l'administration procède à l'exécution forcée, dans des conditions irrégulières, d'une décision manifestement insusceptible de se rattacher à un pouvoir lui appartenant ; le juge judiciaire est compétent pour en connaître.","portee":"Définition classique de la voie de fait, restreinte par la décision Bergoend (TC, 12 mai 1997) puis par la loi du 30 juin 2000.","tags":["voie de fait","compétence judiciaire","liberté individuelle"],"id":"seed-jp-1935-04-08-action-francaise-tc"},{"titre":"Jamart","juridiction":"Conseil d'État","date":"1936-02-07","matiere":"Droit administratif","niveau":"L2-L3","faits":"Un médecin se voit interdire par le ministre des Pensions l'accès à des centres de réforme où il soignait d'anciens militaires ; il conteste la mesure, prise sans texte l'autorisant expressément.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Le chef de service a-t-il le pouvoir de prendre les mesures nécessaires au bon fonctionnement de son service en l'absence de texte ?","solution":"Oui : même en l'absence de texte, il appartient à tout chef de service de prendre les mesures nécessaires au bon fonctionnement de l'administration placée sous son autorité.","portee":"Consacre le pouvoir réglementaire inhérent aux chefs de service (pouvoir d'organisation du service).","tags":["pouvoir réglementaire","chef de service","organisation du service"],"id":"seed-jp-1936-02-07-jamart"},{"titre":"La Fleurette","juridiction":"Conseil d'État","date":"1938-01-14","matiere":"Droit administratif","niveau":"L2-L3","faits":"Une loi interdit la fabrication d'un produit de substitution de la crème, ce qui ruine l'activité de la société qui le fabriquait.","procedure":"La société demande réparation devant le Conseil d'État.","probleme":"L'État peut-il être responsable du fait d'une loi, sans faute du législateur ?","solution":"Oui, en l'absence de volonté contraire du législateur : la loi ne fait pas obstacle à l'indemnisation de la charge anormale et spéciale subie par un administré, qui ne doit pas la supporter seul.","portee":"Première reconnaissance de la responsabilité de l'État du fait des lois ; complété par Gardedieu (2007) pour les lois contraires aux engagements internationaux.","tags":["responsabilité du fait des lois","égalité devant les charges publiques"],"id":"seed-jp-1938-01-14-la-fleurette"},{"titre":"Monpeurt (Ass.)","juridiction":"Conseil d'État","date":"1942-07-31","matiere":"Droit administratif","niveau":"L3","faits":"Un comité d'organisation des industries du verre, organisme créé par la loi du 16 août 1940 pour organiser provisoirement la production industrielle, impose la fermeture d'une usine ; un copropriétaire d'entreprises conteste cette décision.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Un organisme de droit privé chargé d'un service public peut-il prendre des actes administratifs ?","solution":"Oui : lorsque le législateur a voulu confier à des organismes privés des prérogatives de puissance publique pour l'exécution d'un service public, leurs décisions sont des actes administratifs, contrôlables par le juge administratif.","portee":"Reconnaît que des personnes privées peuvent exercer un service public et prendre des actes administratifs ; v. APREI (2007).","tags":["service public","personne privée","acte administratif"],"id":"seed-jp-1942-07-31-monpeurt-ass"},{"titre":"Dame veuve Trompier-Gravier (Sect.)","juridiction":"Conseil d'État","date":"1944-05-05","matiere":"Droit administratif","niveau":"L2","faits":"Le préfet de la Seine retire à une veuve l'autorisation de vendre des journaux dans un kiosque du boulevard Saint-Denis, à raison d'une faute qu'il lui impute, sans qu'elle ait été invitée à présenter sa défense.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"L'administration doit-elle respecter les droits de la défense avant une sanction, même en l'absence de texte ?","solution":"Oui : une sanction grave ne peut être prononcée sans que l'intéressé ait été mis à même de discuter les griefs ; le respect des droits de la défense est un principe général du droit.","portee":"Illustre les principes généraux du droit applicables même sans texte ; la décision est annulée.","tags":["droits de la défense","sanction","PGD"],"id":"seed-jp-1944-05-05-dame-veuve-trompier-gravier-sect"},{"titre":"Dame Lamotte (Ass.)","juridiction":"Conseil d'État","date":"1950-02-17","matiere":"Droit administratif","niveau":"L2","faits":"Une loi de 1940 permet aux préfets de concéder à des tiers l'exploitation de terres incultes ; une propriétaire conteste l'attribution de ses terres, alors qu'un texte de 1943 semble interdire tout recours.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Un acte administratif peut-il échapper au recours pour excès de pouvoir par une loi qui exclut tout recours ?","solution":"Non : le recours pour excès de pouvoir est ouvert même sans texte contre tout acte administratif et a pour effet d'assurer le respect de la légalité ; il ne peut être exclu que par une disposition législative expresse, que le juge interprète strictement.","portee":"Le REP devient un principe général du droit ; la loi ne peut priver le justiciable de ce recours que dans des conditions très strictes.","tags":["recours pour excès de pouvoir","PGD","légalité"],"id":"seed-jp-1950-02-17-dame-lamotte-ass"},{"titre":"Dehaene (Ass.)","juridiction":"Conseil d'État","date":"1950-07-07","matiere":"Droit administratif","niveau":"L2","faits":"Un chef de bureau de préfecture est suspendu et blâmé pour avoir participé à une grève des préfectures que le ministre de l'Intérieur avait interdite aux agents d'autorité.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Les fonctionnaires ont-ils le droit de faire grève, et le gouvernement peut-il l'encadrer ?","solution":"Le droit de grève, reconnu par le Préambule de 1946, a des limites : en l'absence de loi, il appartient au gouvernement, responsable du bon fonctionnement des services, de fixer les limites nécessaires pour concilier ce droit avec les nécessités du service public.","portee":"Reconnaît l'existence du droit de grève dans la fonction publique, sous réserve de son encadrement ; la sanction est jugée légale.","tags":["grève","fonctionnaires","service public"],"id":"seed-jp-1950-07-07-dehaene-ass"},{"titre":"Barel (Ass.)","juridiction":"Conseil d'État","date":"1954-05-28","matiere":"Droit administratif","niveau":"L2","faits":"En 1953, cinq candidats au concours d'entrée à l'ENA sont écartés, en raison des opinions communistes qu'on leur prête.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"L'administration peut-elle refuser l'accès à un concours en raison des opinions politiques d'un candidat ?","solution":"Non : le principe d'égalité d'accès aux emplois publics interdit d'écarter un candidat en raison de ses opinions politiques ; la décision est annulée.","portee":"Fonde le principe d'égalité d'accès aux emplois publics et la neutralité de l'administration vis-à-vis des opinions.","tags":["égalité","accès à la fonction publique","opinions politiques"],"id":"seed-jp-1954-05-28-barel-ass"},{"titre":"Société des films Lutétia (Sect.)","juridiction":"Conseil d'État","date":"1959-12-18","matiere":"Droit administratif","niveau":"L2-L3","faits":"Par arrêté du 3 décembre 1954, le maire de Nice interdit la projection du film « Le feu dans la peau », qui a pourtant reçu le visa ministériel d'exploitation, en invoquant son caractère immoral et les troubles que sa projection provoquerait.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Un maire peut-il interdire un film visé au niveau national en raison des circonstances locales ?","solution":"Oui, en vertu de ses pouvoirs de police et sous réserve de circonstances locales exceptionnelles : le maire peut interdire un film même autorisé par le visa national lorsque sa projection est susceptible d'entraîner des troubles sérieux ou d'être préjudiciable à l'ordre public en raison de son caractère immoral.","portee":"Ouvre la voie de la police administrative spéciale du cinéma ; cadre repris dans la jurisprudence sur l'ordre public local.","tags":["police administrative","liberté d'expression","maire"],"id":"seed-jp-1959-12-18-societe-des-films-lutetia-sect"},{"titre":"Rubin de Servens (Ass.)","juridiction":"Conseil d'État","date":"1962-03-02","matiere":"Droit administratif","niveau":"L2-L3","faits":"Des requérants contestent les mesures prises par le Président de la République après la mise en oeuvre de l'article 16 lors du putsch d'Alger en 1961.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Le juge administratif peut-il contrôler les décisions du chef de l'État prises sur le fondement de l'article 16 ?","solution":"Non : la décision de mettre en oeuvre l'article 16 est un acte de gouvernement non susceptible de contrôle ; les mesures qui relèvent du domaine de la loi (non réglementaire) ne peuvent être contestées devant le Conseil d'État.","portee":"Position conservatrice sur les actes de l'article 16 ; la distinction entre actes réglementaires et législatifs pris sur ce fondement demeure.","tags":["article 16","acte de gouvernement","pleins pouvoirs"],"id":"seed-jp-1962-03-02-rubin-de-servens-ass"},{"titre":"Canal, Robin et Godot (Ass.)","juridiction":"Conseil d'État","date":"1962-10-19","matiere":"Droit administratif","niveau":"L2-L3","faits":"Trois personnes condamnées à mort par la Cour militaire de justice, créée par l'ordonnance du 1er juin 1962 prise sur le fondement de la loi référendaire du 13 avril 1962, contestent la légalité de cette ordonnance.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"Le juge administratif peut-il contrôler une ordonnance prise sur le fondement d'une loi référendaire ?","solution":"Oui : l'ordonnance, qui n'a pas valeur législative, est un acte administratif susceptible de contrôle ; elle est annulée comme contraire aux principes généraux du droit pénal (absence de garanties et de recours).","portee":"Étend le contrôle du juge aux actes pris sur le fondement de l'article 11 (loi référendaire) ; sanctionne une juridiction d'exception.","tags":["ordonnance","art. 11","juridiction d'exception","PGD"],"id":"seed-jp-1962-10-19-canal-robin-et-godot-ass"},{"titre":"Société Air France c. Époux Barbier (TC)","juridiction":"Tribunal des conflits","date":"1968-01-15","matiere":"Droit administratif","niveau":"L3","faits":"Un agent d'Air France, société chargée d'un service public à caractère industriel et commercial, conteste son licenciement.","procedure":"Le Tribunal des conflits est saisi pour déterminer la juridiction compétente.","probleme":"Les agents d'un SPIC sont-ils soumis au droit privé ou au droit public ?","solution":"Les personnels des SPIC sont liés par des contrats de droit privé, sauf pour le directeur et le chef de la comptabilité, si ce dernier a la qualité de comptable public.","portee":"Règle de répartition entre droit privé (en principe) et droit public (exceptions) pour les agents des SPIC.","tags":["service public industriel et commercial","agents","contrat de travail"],"id":"seed-jp-1968-01-15-societe-air-france-c-epoux-barbier-tc"},{"titre":"GISTI, CFDT et CGT (Ass.)","juridiction":"Conseil d'État","date":"1978-12-08","matiere":"Droit administratif","niveau":"L2-L3","faits":"Un décret suspend la délivrance des titres de séjour pour regroupement familial des étrangers ; des associations et syndicats l'attaquent.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"Les étrangers ont-ils un droit à une vie familiale normale opposable à l'administration ?","solution":"Oui : les étrangers résidant régulièrement en France ont, comme les nationaux, le droit de mener une vie familiale normale ; ce droit est un principe général du droit tiré du Préambule de 1946. Le décret est annulé.","portee":"Illustre le rôle des PGD dans la protection des libertés ; il inspire aussi l'article 8 de la CEDH.","tags":["PGD","étrangers","vie familiale","regroupement"],"id":"seed-jp-1978-12-08-gisti-cfdt-et-cgt-ass"},{"titre":"Époux V. (Ass.)","juridiction":"Conseil d'État","date":"1992-04-10","matiere":"Droit administratif","niveau":"L2-L3","faits":"Une femme, quelques jours avant son terme, subit une césarienne sous anesthésie péridurale dans un hôpital public ; elle fait de fortes chutes de tension puis un arrêt cardiaque, dont elle garde de graves séquelles.","procedure":"Recours indemnitaire devant le Conseil d'État.","probleme":"La responsabilité d'un hôpital pour un acte médical suppose-t-elle une faute lourde ?","solution":"Non : la responsabilité d'un service hospitalier est engagée pour toute faute médicale, même simple, sans exiger de faute lourde.","portee":"Abandonne la faute lourde pour les actes médicaux (v. aussi Bianchi pour l'aléa thérapeutique) ; la loi du 4 mars 2002 a ensuite fixé le régime général.","tags":["responsabilité hospitalière","faute médicale","acte médical"],"id":"seed-jp-1992-04-10-epoux-v-ass"},{"titre":"Bianchi (Ass.)","juridiction":"Conseil d'État","date":"1993-04-09","matiere":"Droit administratif","niveau":"L2-L3","faits":"Un patient subit une artériographie vertébrale nécessaire à son diagnostic ; l'examen provoque une tétraplégie, sans faute des praticiens.","procedure":"Recours indemnitaire devant le Conseil d'État.","probleme":"L'hôpital répond-il d'un accident médical grave sans faute lorsque l'acte était nécessaire ?","solution":"Oui : lorsqu'un acte médical nécessaire au diagnostic ou au traitement présente un risque dont l'existence est connue mais dont la réalisation est exceptionnelle, et que cet acte est la cause directe de dommages graves sans rapport avec l'état initial, la responsabilité du service est engagée même sans faute.","portee":"Fonde la réparation de l'aléa thérapeutique ; la loi du 4 mars 2002 a ensuite créé la solidarité nationale (ONIAM).","tags":["aléa thérapeutique","responsabilité sans faute","hôpital"],"id":"seed-jp-1993-04-09-bianchi-ass"},{"titre":"Hardouin et Marie (Ass.)","juridiction":"Conseil d'État","date":"1995-02-17","matiere":"Droit administratif","niveau":"L3-M1","faits":"Un marin et un détenu contestent devant le juge administratif des sanctions disciplinaires qui leur ont été infligées.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Les mesures d'ordre intérieur sont-elles susceptibles de recours ?","solution":"Les mesures d'ordre intérieur, qui ne portent pas atteinte aux droits et libertés des intéressés, ne sont pas susceptibles de recours pour excès de pouvoir ; en revanche, les sanctions plus lourdes, dont le placement en cellule disciplinaire d'un détenu, constituent des décisions faisant grief.","portee":"Restreint la catégorie des mesures d'ordre intérieur ; élargie par Boussouar (2007), qui ouvre le recours contre des transferts de détenus.","tags":["mesures d'ordre intérieur","détenus","acte administratif"],"id":"seed-jp-1995-02-17-hardouin-et-marie-ass"},{"titre":"Berkani (TC)","juridiction":"Tribunal des conflits","date":"1996-03-25","matiere":"Droit administratif","niveau":"L3","faits":"Une salariée employée sous contrat par une caisse d'assurance maladie, chargée d'un service public administratif, conteste la rupture de son contrat.","procedure":"Le Tribunal des conflits est saisi pour déterminer la juridiction compétente.","probleme":"Les agents non statutaires des services publics administratifs sont-ils liés par un contrat de droit public ?","solution":"Oui : les personnels non statutaires travaillant pour le compte d'un service public à caractère administratif sont des agents contractuels de droit public, quel que soit leur emploi ; le litige relève du juge administratif.","portee":"Pose la règle inverse de Barbier pour les services publics administratifs.","tags":["agents publics","service public administratif","contrat"],"id":"seed-jp-1996-03-25-berkani-tc"},{"titre":"Aquarone (Ass.)","juridiction":"Conseil d'État","date":"1997-06-06","matiere":"Droit administratif","niveau":"L2-L3","faits":"Un requérant invoque une coutume internationale à l'encontre d'une décision fondée sur la loi française.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Une coutume internationale peut-elle l'emporter sur la loi interne ?","solution":"Non : ni l'article 55 de la Constitution ni aucune autre disposition de valeur constitutionnelle ne prescrit ni n'implique que le juge administratif fasse prévaloir la coutume internationale sur la loi en cas de conflit.","portee":"Exclut la primauté de la coutume sur la loi dans l'ordre interne ; elle ne vaut que pour les traités (art. 55).","tags":["coutume internationale","hiérarchie des normes","loi"],"id":"seed-jp-1997-06-06-aquarone-ass"},{"titre":"Ternon (Ass.)","juridiction":"Conseil d'État","date":"2001-10-26","matiere":"Droit administratif","niveau":"L2-L3","faits":"Un agent est titularisé comme attaché régional par un arrêté illégal du 30 décembre 1983 ; le président du conseil régional retire cet arrêté le 25 mars 1988, plus de quatre ans après.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État.","probleme":"Dans quel délai l'administration peut-elle retirer une décision individuelle explicite créatrice de droits illégale ?","solution":"Sous réserve de dispositions législatives ou réglementaires contraires, l'administration ne peut retirer une décision individuelle explicite créatrice de droits, si elle est illégale, que dans le délai de quatre mois suivant son édiction.","portee":"Remplace la règle des deux mois de Dame Cachet ; repris par le Code des relations entre le public et l'administration (art. L. 242-1).","tags":["retrait","acte créateur de droits","délai"],"id":"seed-jp-2001-10-26-ternon-ass"},{"titre":"Magiera (Ass.)","juridiction":"Conseil d'État","date":"2002-06-28","matiere":"Droit administratif","niveau":"M1","faits":"Une partie à un litige administratif dont la durée est excessive demande à l'État de réparer le préjudice résultant de la lenteur de la procédure.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"L'État est-il responsable de la durée excessive d'une procédure juridictionnelle ?","solution":"Oui : la responsabilité de l'État est engagée pour toute faute commise dans le fonctionnement du service public de la justice, dont la méconnaissance du délai raisonnable ; le préjudice est indemnisé.","portee":"Applique l'article 6 § 1 de la Convention en ordre interne ; articulée avec Kudla c. Pologne (CEDH, 2000).","tags":["responsabilité de l'État","justice","délai raisonnable"],"id":"seed-jp-2002-06-28-magiera-ass"},{"titre":"Gardedieu (Ass.)","juridiction":"Conseil d'État","date":"2007-02-08","matiere":"Droit administratif","niveau":"M1","faits":"Un particulier réclame réparation du préjudice causé par l'application d'une loi contraire à la Convention européenne des droits de l'homme.","procedure":"Recours indemnitaire devant le Conseil d'État.","probleme":"L'État est-il responsable du fait de l'application d'une loi contraire à un engagement international ?","solution":"Oui : la responsabilité de l'État peut être engagée pour les dommages causés par une loi méconnaissant les engagements internationaux de la France ; l'illicéité de la loi est constitutive d'une faute.","portee":"Complète La Fleurette : responsabilité pour faute du fait d'une loi inconventionnelle.","tags":["responsabilité du fait des lois","conventionnalité","CEDH"],"id":"seed-jp-2007-02-08-gardedieu-ass"},{"titre":"Tropic Travaux Signalisation (Ass.)","juridiction":"Conseil d'État","date":"2007-07-16","matiere":"Droit administratif","niveau":"M1","faits":"Une société, évincée d'un contrat, conteste ce contrat et demande l'annulation de la décision de signature.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Un concurrent évincé peut-il contester la validité du contrat signé ?","solution":"Oui : tout concurrent évincé peut former un recours de plein contentieux contre le contrat, assorti éventuellement d'une demande de suspension, et invoquer les vices de la procédure de passation.","portee":"Ouvre aux concurrents évincés une action directe contre le contrat ; complétée par Tarn-et-Garonne (2014).","tags":["contrats","référé précontractuel","concurrent évincé"],"id":"seed-jp-2007-07-16-tropic-travaux-signalisation-ass"},{"titre":"Garde des Sceaux c. Boussouar (Ass.)","juridiction":"Conseil d'État","date":"2007-12-14","matiere":"Droit administratif","niveau":"M1","faits":"Un détenu est transféré d'un établissement à un autre, ce qui modifie ses conditions de détention ; il conteste le changement de régime.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Peut-on contester une décision de changement d'affectation d'un détenu ?","solution":"Oui, selon les effets : le juge administratif contrôle les décisions qui portent atteinte aux droits et libertés fondamentaux du détenu ; la qualification de mesure d'ordre intérieur dépend de la nature et de la gravité de ses effets.","portee":"Réduit encore la catégorie des mesures d'ordre intérieur ; il alimente la protection des droits des détenus.","tags":["détenus","mesures d'ordre intérieur","transfert","recours"],"id":"seed-jp-2007-12-14-garde-des-sceaux-c-boussouar-ass"},{"titre":"Danthony (Ass.)","juridiction":"Conseil d'État","date":"2011-12-23","matiere":"Droit administratif","niveau":"L3-M1","faits":"Une décision administrative est adoptée au terme d'une procédure comportant une irrégularité dans la consultation d'un organisme.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"Toute irrégularité de procédure entraîne-t-elle l'annulation de la décision administrative ?","solution":"Non : un vice de procédure n'est de nature à entraîner l'annulation de la décision que s'il a pu exercer une influence sur le sens de la décision prise ou s'il a privé les intéressés d'une garantie.","portee":"Nouvelle théorie des vices de procédure : relativise l'annulation et évite les annulations purement formelles.","tags":["vice de procédure","légalité externe","garantie"],"id":"seed-jp-2011-12-23-danthony-ass"},{"titre":"Dieudonné (ord. référé-liberté)","juridiction":"Conseil d'État","date":"2014-01-09","matiere":"Droit administratif","niveau":"M1","faits":"Le ministre de l'Intérieur invite les préfets à interdire les spectacles d'un humoriste condamné pour propos antisémites ; le tribunal administratif suspend l'interdiction.","procedure":"Appel du ministre devant le juge des référés du Conseil d'État, statuant en référé-liberté.","probleme":"Une autorité de police peut-elle interdire un spectacle avant qu'il ait lieu, au nom de la dignité de la personne humaine ?","solution":"Oui : le respect de la dignité de la personne humaine est une composante de l'ordre public ; le risque que le spectacle porte atteinte à la dignité et à la sécurité justifie l'interdiction, sans méconnaître la liberté d'expression.","portee":"Confirme le rôle de la dignité dans la police administrative (Commune de Morsang-sur-Orge, 1995) ; décision très commentée.","tags":["police administrative","dignité","référé-liberté"],"id":"seed-jp-2014-01-09-dieudonne-ord-refere-liberte"},{"titre":"Département de Tarn-et-Garonne (Ass.)","juridiction":"Conseil d'État","date":"2014-04-04","matiere":"Droit administratif","niveau":"M1","faits":"Un département conclut un contrat ; un tiers susceptible d'être lésé dans ses intérêts conteste le contrat devant le juge administratif.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Un tiers peut-il contester la validité d'un contrat administratif devant le juge ?","solution":"Oui : tout tiers à un contrat administratif susceptible d'être lésé dans ses intérêts de façon suffisamment directe et certaine par sa passation ou ses clauses peut former un recours de plein contentieux, dans un délai de deux mois suivant les mesures de publicité appropriées.","portee":"Généralise le recours des tiers contre les contrats administratifs ; il renouvelle le contentieux contractuel (Tropic, 2007).","tags":["contrats","recours des tiers","validité"],"id":"seed-jp-2014-04-04-departement-de-tarn-et-garonne-ass"},{"titre":"Fairvesta International et Numericable (Ass.)","juridiction":"Conseil d'État","date":"2016-03-21","matiere":"Droit administratif","niveau":"M2","faits":"Des sociétés contestent un avis et un communiqué de l'Autorité des marchés financiers et de l'Autorité de la concurrence, dépourvus de caractère contraignant.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"Un acte de « droit souple » peut-il faire l'objet d'un recours pour excès de pouvoir ?","solution":"Oui : les avis, recommandations, mises en garde et prises de position des autorités de régulation peuvent être déférés au juge lorsqu'ils sont de nature à produire des effets notables, notamment économiques, ou lorsqu'ils ont pour objet d'influer de manière significative sur les comportements.","portee":"Ouvre le contrôle du droit souple ; confirmé par Gisti (Sect., 12 juin 2020) pour les lignes directrices.","tags":["droit souple","recours pour excès de pouvoir","actes"],"id":"seed-jp-2016-03-21-fairvesta-international-et-numericable-a"},{"titre":"Czabaj (Ass.)","juridiction":"Conseil d'État","date":"2016-07-13","matiere":"Droit administratif","niveau":"L3-M1","faits":"Un particulier conteste une décision individuelle plus d'un an après en avoir eu connaissance ; la notification ne mentionnait pas les voies et délais de recours.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"Le destinataire d'une décision qui ne lui a pas été notifiée selon les règles peut-il la contester sans limite de temps ?","solution":"Non : le principe de sécurité juridique fait obstacle à ce que la décision puisse être contestée indéfiniment ; le recours doit être exercé dans un délai raisonnable, en principe un an à compter de la connaissance de la décision.","portee":"Instaure un délai raisonnable d'un an pour les recours contre des décisions sans mention des voies de recours ; la CEDH a jugé que l'application immédiate de cette règle aux instances en cours violait le droit à un procès équitable (Legros et autres c. France, 9 novembre 2023).","tags":["délai de recours","sécurité juridique","notification"],"id":"seed-jp-2016-07-13-czabaj-ass"},{"titre":"Loi référendaire de 1962 (n° 62-20 DC)","juridiction":"Conseil constitutionnel","date":"1962-11-06","matiere":"Droit constitutionnel","niveau":"L1","faits":"Une loi relative à l'élection du Président de la République au suffrage universel direct a été adoptée par référendum, sur le fondement de l'article 11, le 28 octobre 1962.","procedure":"Le président du Sénat saisit le Conseil constitutionnel pour qu'il contrôle la loi adoptée par le peuple.","probleme":"Le Conseil constitutionnel peut-il contrôler la constitutionnalité d'une loi adoptée par référendum ?","solution":"Non : la compétence du Conseil est strictement délimitée par la Constitution ; les lois que vise l'article 61 sont celles votées par le Parlement, non celles adoptées par le peuple, expression directe de la souveraineté nationale.","portee":"Les lois référendaires échappent au contrôle ; la décision est confirmée par la décision n° 92-313 DC du 23 septembre 1992 (Maastricht III).","tags":["référendum","souveraineté","compétence"],"id":"seed-jp-1962-11-06-loi-referendaire-de-1962-n-62-20-dc"},{"titre":"Syndicat général des fabricants de semoules (Ass.)","juridiction":"Conseil d'État","date":"1968-03-01","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Des fabricants de semoules contestent un règlement qui applique une loi postérieure au traité de Rome.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Le juge administratif peut-il écarter une loi postérieure à un traité, pour contrariété avec le traité ?","solution":"Non : la loi postérieure fait écran entre le règlement et le traité ; le juge administratif ne contrôle pas la conformité de la loi au traité.","portee":"Cette position est abandonnée par l'arrêt Nicolo (1989) ; elle sert de repère historique.","tags":["conventionnalité","écran législatif","traité"],"id":"seed-jp-1968-03-01-syndicat-general-des-fabricants-de-semou"},{"titre":"Liberté d'association (n° 71-44 DC)","juridiction":"Conseil constitutionnel","date":"1971-07-16","matiere":"Droit constitutionnel","niveau":"L1","faits":"Une loi complétant celle du 1er juillet 1901 soumettait la création de certaines associations à un contrôle préalable de l'autorité judiciaire saisie par le préfet.","procedure":"Le président du Sénat saisit le Conseil constitutionnel avant la promulgation de la loi (contrôle a priori, art. 61 de la Constitution).","probleme":"La liberté d'association, que la Constitution de 1958 ne mentionne pas, a-t-elle une valeur constitutionnelle opposable au législateur ?","solution":"Oui : la liberté d'association est un principe fondamental reconnu par les lois de la République, réaffirmé par le Préambule de la Constitution de 1958. Le contrôle préalable instauré est censuré.","portee":"Décision fondatrice : le Préambule (Déclaration de 1789, Préambule de 1946, PFRLR) entre dans le « bloc de constitutionnalité » et le Conseil devient protecteur des libertés contre le législateur.","tags":["bloc de constitutionnalité","libertés","grand arrêt"],"id":"seed-jp-1971-07-16-liberte-d-association-n-71-44-dc"},{"titre":"Taxation d'office (n° 73-51 DC)","juridiction":"Conseil constitutionnel","date":"1973-12-27","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Une disposition de la loi de finances pour 1974 autorise l'administration fiscale à taxer d'office un contribuable sans qu'il puisse contester utilement l'imposition devant le juge.","procedure":"Saisine de parlementaires avant promulgation de la loi de finances.","probleme":"Une disposition fiscale peut-elle écarter les garanties des contribuables sans méconnaître le principe d'égalité devant la loi et les droits de la défense ?","solution":"Non : la disposition est censurée, car elle rompt l'égalité devant la loi fiscale et porte atteinte aux droits de la défense.","portee":"Première référence du Conseil au principe d'égalité devant la loi (art. 6 de la Déclaration de 1789) pour censurer une loi fiscale, dans une matière jusque-là peu contrôlée.","tags":["égalité","droits de la défense","fiscal"],"id":"seed-jp-1973-12-27-taxation-d-office-n-73-51-dc"},{"titre":"Interruption volontaire de grossesse (n° 74-54 DC)","juridiction":"Conseil constitutionnel","date":"1975-01-15","matiere":"Droit constitutionnel","niveau":"L1","faits":"La loi relative à l'interruption volontaire de la grossesse est contestée comme contraire à l'article 2 de la Convention européenne des droits de l'homme.","procedure":"Saisine de soixante députés avant promulgation.","probleme":"Le Conseil constitutionnel est-il compétent, au titre de l'article 61, pour contrôler la conformité d'une loi à un traité ?","solution":"Non : la supériorité des traités sur les lois (art. 55) a un caractère relatif et contingent, car elle dépend de la réciprocité ; ce contrôle diffère du contrôle de constitutionnalité. Le Conseil se déclare incompétent.","portee":"Le contrôle de conventionnalité appartient aux juges ordinaires : Cass. ch. mixte, 24 mai 1975 (Jacques Vabre), puis CE, Ass., 20 oct. 1989 (Nicolo).","tags":["contrôle de conventionnalité","traités","grand arrêt"],"id":"seed-jp-1975-01-15-interruption-volontaire-de-grossesse-n-7"},{"titre":"Société des cafés Jacques Vabre (ch. mixte)","juridiction":"Cour de cassation","date":"1975-05-24","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Un importateur de café conteste une taxe française perçue au mépris, selon lui, du traité de Rome, la taxe ayant été instituée par une loi postérieure.","procedure":"Pourvoi devant la chambre mixte de la Cour de cassation.","probleme":"Le juge judiciaire peut-il écarter une loi, même postérieure, contraire à un traité ?","solution":"Oui : le traité, régulièrement ratifié, a une autorité supérieure à celle de la loi, même postérieure ; le juge doit écarter l'application de la loi contraire, sans attendre la décision du Conseil constitutionnel.","portee":"Consacre le contrôle de conventionnalité par les juges judiciaires ; le Conseil d'État le reconnaît en 1989 (Nicolo).","tags":["conventionnalité","traité","loi postérieure"],"id":"seed-jp-1975-05-24-societe-des-cafes-jacques-vabre-ch-mixte"},{"titre":"Liberté de l'enseignement (n° 77-87 DC)","juridiction":"Conseil constitutionnel","date":"1977-11-23","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi relative à la liberté de l'enseignement (loi Guermeur) règle la situation des maîtres de l'enseignement privé sous contrat.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"La liberté de l'enseignement a-t-elle une valeur constitutionnelle ?","solution":"Oui : la liberté de l'enseignement est l'un des principes fondamentaux reconnus par les lois de la République, réaffirmés par le Préambule de 1946 ; la loi la respecte en conciliant caractère propre des établissements privés et liberté de conscience des maîtres.","portee":"Un des premiers PFRLR identifiés après la décision de 1971 ; il a pour corollaire le financement de l'enseignement privé sous contrat.","tags":["PFRLR","liberté de l'enseignement","enseignement privé"],"id":"seed-jp-1977-11-23-liberte-de-l-enseignement-n-77-87-dc"},{"titre":"Cohn-Bendit (Ass.)","juridiction":"Conseil d'État","date":"1978-12-22","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Un ressortissant allemand, M. Cohn-Bendit, conteste son interdiction de séjour en s'appuyant sur une directive de 1964.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Un particulier peut-il invoquer une directive à l'appui d'un recours contre une décision administrative individuelle ?","solution":"Non : les directives ne peuvent être invoquées à l'appui d'un recours dirigé contre un acte individuel, car elles lient les États quant au résultat à atteindre, en leur laissant le choix de la forme et des moyens.","portee":"Cette position, contraire à la jurisprudence de la CJUE, est abandonnée par CE, Ass., 30 oct. 2009, Mme Perreux.","tags":["directive","effet direct","droit de l'Union"],"id":"seed-jp-1978-12-22-cohn-bendit-ass"},{"titre":"Droit de grève à la radio et à la télévision (n° 79-105 DC)","juridiction":"Conseil constitutionnel","date":"1979-07-25","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Une loi impose la continuité du service public de la radio et de la télévision, en limitant les cessations concertées de travail dans les sociétés de programme.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le législateur peut-il limiter le droit de grève pour assurer la continuité du service public ?","solution":"Oui : le droit de grève (alinéa 7 du Préambule de 1946) a des limites ; le législateur doit concilier ce droit avec la continuité du service public, principe de valeur constitutionnelle. Il ne peut l'interdire mais doit en régler l'exercice, sous contrôle de l'erreur manifeste.","portee":"Reconnaît la valeur constitutionnelle de la continuité du service public et illustre la technique de conciliation entre exigences constitutionnelles.","tags":["grève","continuité du service public","conciliation"],"id":"seed-jp-1979-07-25-droit-de-greve-a-la-radio-et-a-la-televi"},{"titre":"Nationalisations (n° 81-132 DC)","juridiction":"Conseil constitutionnel","date":"1982-01-16","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Une loi du nouveau gouvernement nationalise plusieurs groupes industriels et banques, avec indemnisation des actionnaires selon des règles qu'elle fixe.","procedure":"Saisine de parlementaires de l'opposition avant promulgation.","probleme":"Le législateur peut-il nationaliser des entreprises, et à quelles conditions, au regard du droit de propriété et de l'indemnisation « juste et préalable » ?","solution":"Oui : la loi peut nationaliser en cas de nécessité publique constatée ; mais les règles d'indemnisation doivent assurer une indemnité « juste », ce qui conduit à censurer l'évaluation de certains éléments, tout en validant l'essentiel du texte.","portee":"Le droit de propriété et la liberté d'entreprendre ont valeur constitutionnelle ; le Conseil se reconnaît un contrôle de l'erreur manifeste d'appréciation sur les choix du législateur.","tags":["propriété","indemnisation","nationalisation"],"id":"seed-jp-1982-01-16-nationalisations-n-81-132-dc"},{"titre":"Quotas par sexe dans les listes municipales (n° 82-146 DC)","juridiction":"Conseil constitutionnel","date":"1982-11-18","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi sur les élections municipales prévoit que les listes de candidats ne peuvent comporter plus de 75 % de personnes du même sexe.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le législateur peut-il imposer des quotas par sexe aux listes de candidats ?","solution":"Non : la qualité de citoyen ouvre le droit de vote et l'éligibilité dans des conditions identiques à tous ceux qui n'en sont pas exclus ; tout principe de distinction entre les électeurs ou éligibles par catégories est contraire à l'article 3 de la Constitution et à l'article 6 de la Déclaration.","portee":"Obstacle constitutionnel à la parité jusqu'à la révision de 1999 (article 3, alinéa 5) ; la jurisprudence de 1982 a été dépassée par la révision.","tags":["égalité","citoyenneté","indivisibilité du corps électoral"],"id":"seed-jp-1982-11-18-quotas-par-sexe-dans-les-listes-municipa"},{"titre":"Franchises universitaires (n° 83-165 DC)","juridiction":"Conseil constitutionnel","date":"1984-01-20","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi sur l'enseignement supérieur (loi Savary) organise la composition des conseils des universités et la représentation des enseignants-chercheurs.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"L'indépendance des professeurs d'université a-t-elle valeur constitutionnelle ?","solution":"Oui : l'indépendance des professeurs d'université est un principe fondamental reconnu par les lois de la République ; elle exige que les professeurs aient une représentation propre et majoritaire dans les organes qui se prononcent sur les questions relevant de leur compétence.","portee":"Consacre les « franchises universitaires » comme PFRLR et fonde le contrôle de la composition des conseils universitaires.","tags":["PFRLR","indépendance des professeurs","enseignement supérieur"],"id":"seed-jp-1984-01-20-franchises-universitaires-n-83-165-dc"},{"titre":"Loi relative aux entreprises de presse (n° 84-181 DC)","juridiction":"Conseil constitutionnel","date":"1984-10-11","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"La loi limite la concentration des entreprises de presse en vue de préserver le pluralisme.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le pluralisme des quotidiens est-il une exigence constitutionnelle justifiant des limites à la liberté d'entreprendre ?","solution":"Oui : le pluralisme des quotidiens d'information politique et générale est en lui-même un objectif de valeur constitutionnelle ; le législateur peut limiter la concentration, sans que soit portée une atteinte disproportionnée à la liberté.","portee":"Reconnaissance du pluralisme comme objectif de valeur constitutionnelle ; confirmée en 1986 pour l'audiovisuel.","tags":["liberté de la presse","pluralisme","concentration"],"id":"seed-jp-1984-10-11-loi-relative-aux-entreprises-de-presse-n"},{"titre":"Nouvelle-Calédonie (n° 85-197 DC)","juridiction":"Conseil constitutionnel","date":"1985-08-23","matiere":"Droit constitutionnel","niveau":"L1","faits":"Une loi sur l'évolution de la Nouvelle-Calédonie, votée dans le cadre d'un état d'urgence récemment déclaré, est contestée sur la procédure et le fond.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"La loi exprime-t-elle la volonté générale sans condition, comme semble le dire l'article 6 de la Déclaration de 1789 ?","solution":"Non : la loi votée n'exprime la volonté générale que dans le respect de la Constitution. La loi est contrôlée même si elle a été adoptée par la majorité.","portee":"Rompt avec la conception de la loi souveraine de la tradition républicaine : la loi est subordonnée à la Constitution, ce qui fonde le contrôle de constitutionnalité.","tags":["loi","volonté générale","souveraineté"],"id":"seed-jp-1985-08-23-nouvelle-caledonie-n-85-197-dc"},{"titre":"Conseil de la concurrence (n° 86-224 DC)","juridiction":"Conseil constitutionnel","date":"1987-01-23","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Une loi transfère à la cour d'appel de Paris le contentieux des décisions du Conseil de la concurrence, qui relevait du juge administratif.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"La compétence du juge administratif pour annuler ou réformer les décisions prises par des autorités administratives a-t-elle une valeur constitutionnelle ?","solution":"Oui : les lois de la République ont consacré le principe selon lequel, à l'exception des matières réservées par nature à l'autorité judiciaire, relève en dernier ressort de la compétence de la juridiction administrative l'annulation ou la réformation des décisions prises, dans l'exercice des prérogatives de puissance publique, par les autorités exerçant le pouvoir exécutif ; le Conseil admet toutefois le transfert au juge judiciaire pour une bonne administration de la justice.","portee":"Crée un PFRLR de la compétence de la juridiction administrative ; atténué par la possibilité de « blocs de compétences » transférés au juge judiciaire.","tags":["PFRLR","juridiction administrative","séparation des pouvoirs"],"id":"seed-jp-1987-01-23-conseil-de-la-concurrence-n-86-224-dc"},{"titre":"Nicolo (Ass.)","juridiction":"Conseil d'État","date":"1989-10-20","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Un citoyen demande l'annulation de l'élection des représentants français au Parlement européen au motif que les électeurs d'outre-mer y ont participé, contrairement au traité de Rome.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Le juge administratif peut-il écarter une loi postérieure à un traité qui lui est contraire ?","solution":"Oui : l'article 55 de la Constitution donne au traité une autorité supérieure à celle des lois, même postérieures ; le juge administratif contrôle la compatibilité de la loi avec le traité (en l'espèce, la loi est jugée compatible).","portee":"Abandonne la jurisprudence des Semoules (1968) : le Conseil d'État contrôle désormais la conventionnalité des lois.","tags":["conventionnalité","traité","loi postérieure"],"id":"seed-jp-1989-10-20-nicolo-ass"},{"titre":"Statut de la Corse — peuple corse (n° 91-290 DC)","juridiction":"Conseil constitutionnel","date":"1991-05-09","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi portant statut de la collectivité territoriale de Corse mentionne dans son article 1er « le peuple corse, composante du peuple français ».","procedure":"Saisine de parlementaires avant promulgation.","probleme":"La Constitution permet-elle de reconnaître légalement un « peuple corse » ?","solution":"Non : la Constitution ne connaît que le peuple français, composé de tous les citoyens français sans distinction d'origine, de race ou de religion ; la notion de « peuple corse, composante du peuple français » est contraire à la Constitution.","portee":"Rappelle l'unicité du peuple français ; le Conseil réitère cette position dans la décision n° 99-412 DC (langues régionales).","tags":["peuple français","indivisibilité","Corse"],"id":"seed-jp-1991-05-09-statut-de-la-corse-peuple-corse-n-91-290"},{"titre":"Traité sur l'Union européenne — Maastricht I (n° 92-308 DC)","juridiction":"Conseil constitutionnel","date":"1992-04-09","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Le traité de Maastricht prévoit la monnaie unique, une politique commune des visas et le droit de vote des citoyens de l'Union aux élections municipales.","procedure":"Le Président de la République saisit le Conseil constitutionnel avant la ratification, sur le fondement de l'article 54.","probleme":"Le traité comporte-t-il des clauses contraires à la Constitution ?","solution":"Oui : trois clauses sont contraires, car elles portent atteinte aux conditions essentielles d'exercice de la souveraineté nationale (union économique et monétaire, visas, droit de vote aux élections locales). L'autorisation de ratifier ne peut intervenir qu'après révision.","portee":"Conduit à la loi constitutionnelle du 25 juin 1992 (titre XIV, « Des Communautés européennes et de l'Union européenne ») ; le Conseil dégage la notion de « conditions essentielles d'exercice de la souveraineté nationale ».","tags":["traité","souveraineté","révision constitutionnelle"],"id":"seed-jp-1992-04-09-traite-sur-l-union-europeenne-maastricht"},{"titre":"Maastricht II (n° 92-312 DC)","juridiction":"Conseil constitutionnel","date":"1992-09-02","matiere":"Droit constitutionnel","niveau":"L3","faits":"Après la révision constitutionnelle de juin 1992, le traité de Maastricht est de nouveau soumis au Conseil constitutionnel.","procedure":"Saisine, avant ratification, par des parlementaires, sur le fondement de l'article 54.","probleme":"Le traité, désormais, est-il compatible avec la Constitution révisée ?","solution":"Oui : le traité est conforme à la Constitution révisée ; le Conseil écarte les griefs de souveraineté tirés des règles de transfert de compétences, désormais couvertes par les nouveaux articles.","portee":"Rappelle que la révision constitutionnelle peut lever les obstacles tenant à la souveraineté ; la ratification est ensuite autorisée, puis le traité est adopté par référendum (20 septembre 1992).","tags":["traité","souveraineté","Union européenne"],"id":"seed-jp-1992-09-02-maastricht-ii-n-92-312-dc"},{"titre":"Loi relative à la maîtrise de l'immigration et aux conditions d'entrée (n° 93-325 DC)","juridiction":"Conseil constitutionnel","date":"1993-08-13","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"La loi restreint les conditions d'entrée et de séjour des étrangers, y compris le regroupement familial et l'accès aux soins.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Les étrangers bénéficient-ils de droits constitutionnels, et quelles limites s'imposent au législateur ?","solution":"Oui : les étrangers jouissent de droits fondamentaux de valeur constitutionnelle (droit de mener une vie familiale normale, droit d'asile) ; le législateur peut les encadrer mais doit concilier ses choix avec les exigences constitutionnelles ; plusieurs dispositions sont censurées.","portee":"Constitutionnalise le droit d'asile et la vie familiale normale ; la révision de 1993 a ajouté l'article 53-1.","tags":["étrangers","asile","vie familiale","droit d'asile"],"id":"seed-jp-1993-08-13-loi-relative-a-la-maitrise-de-l-immigrat"},{"titre":"Bioéthique (n° 94-343/344 DC)","juridiction":"Conseil constitutionnel","date":"1994-07-27","matiere":"Droit constitutionnel","niveau":"L1","faits":"Deux lois de 1994 encadrent le don et l'utilisation des éléments du corps humain, l'assistance médicale à la procréation et le diagnostic prénatal.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"La dignité de la personne humaine a-t-elle une valeur constitutionnelle ?","solution":"Oui : le Préambule de 1946 consacre la sauvegarde de la dignité de la personne humaine contre toute forme d'asservissement et de dégradation ; ce principe de valeur constitutionnelle justifie les restrictions apportées à la disposition du corps humain.","portee":"Fonde la place de la dignité en droit constitutionnel ; elle sert ensuite d'appui à des solutions de droit civil et de droit pénal.","tags":["dignité","bioéthique","corps humain"],"id":"seed-jp-1994-07-27-bioethique-n-94-343-344-dc"},{"titre":"Diversité de l'habitat — droit au logement (n° 94-359 DC)","juridiction":"Conseil constitutionnel","date":"1995-01-19","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi relative à la diversité de l'habitat prévoit des mesures de mixité sociale, contestées comme atteintes à la propriété et à la liberté contractuelle.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le droit à un logement décent est-il un droit à valeur constitutionnelle ?","solution":"La possibilité pour toute personne de disposer d'un logement décent est un objectif de valeur constitutionnelle, qui découle du principe de sauvegarde de la dignité de la personne humaine ; ce n'est pas un droit-créance directement invocable.","portee":"Notion d'objectif de valeur constitutionnelle ; le logement est ensuite mis en balance avec le droit de propriété.","tags":["logement","objectif constitutionnel","dignité"],"id":"seed-jp-1995-01-19-diversite-de-l-habitat-droit-au-logement"},{"titre":"Koné (Ass.)","juridiction":"Conseil d'État","date":"1996-07-03","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Un ressortissant malien conteste le décret accordant son extradition au Mali ; il invoque le caractère politique de la demande.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"L'État peut-il extrader dans un but politique, au regard d'un principe fondamental reconnu par les lois de la République ?","solution":"Non : le principe selon lequel l'État doit refuser l'extradition quand elle est demandée dans un but politique est un principe fondamental reconnu par les lois de la République ; le décret est annulé.","portee":"Le juge administratif reconnaît un PFRLR et en fait un fondement d'annulation d'actes administratifs.","tags":["PFRLR","extradition","asile"],"id":"seed-jp-1996-07-03-kone-ass"},{"titre":"Sarran, Levacher et autres (Ass.)","juridiction":"Conseil d'État","date":"1998-10-30","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Des électeurs de Nouvelle-Calédonie contestent l'organisation du référendum de 1998 en invoquant l'article 55 et des normes internationales.","procedure":"Recours devant le Conseil d'État, qui réunit son assemblée du contentieux.","probleme":"Un traité l'emporte-t-il sur la Constitution dans l'ordre juridique interne ?","solution":"Non : la suprématie conférée aux engagements internationaux par l'article 55 ne s'applique pas, dans l'ordre interne, aux dispositions de nature constitutionnelle. La Constitution est au sommet.","portee":"Le Conseil d'État aligne sa position sur celle du Conseil constitutionnel ; la Cour de cassation suit : Ass. plén., 2 juin 2000, Mlle Fraisse.","tags":["hiérarchie des normes","Constitution","traité"],"id":"seed-jp-1998-10-30-sarran-levacher-et-autres-ass"},{"titre":"Charte européenne des langues régionales ou minoritaires (n° 99-412 DC)","juridiction":"Conseil constitutionnel","date":"1999-06-15","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La France a signé la Charte européenne des langues régionales ou minoritaires et envisage de la ratifier.","procedure":"Le Président de la République saisit le Conseil avant la ratification.","probleme":"La Charte, en reconnaissant un droit de pratiquer une langue régionale dans la vie publique, est-elle conforme à la Constitution ?","solution":"Non, plusieurs dispositions sont contraires aux articles 1er (indivisibilité de la République, égalité) et 2 (le français est la langue de la République) : la Charte reconnaît des droits à des groupes de locuteurs à l'intérieur du « peuple français ».","portee":"La France n'a pas ratifié la Charte ; l'article 75-1 (2008) a ensuite reconnu les langues régionales comme patrimoine de la France, sans effet sur ce raisonnement.","tags":["langue","indivisibilité","égalité"],"id":"seed-jp-1999-06-15-charte-europeenne-des-langues-regionales"},{"titre":"Pacte civil de solidarité (n° 99-419 DC)","juridiction":"Conseil constitutionnel","date":"1999-11-09","matiere":"Droit constitutionnel","niveau":"L2","faits":"La loi relative au pacte civil de solidarité crée un contrat entre deux personnes majeures pour organiser leur vie commune.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le PACS respecte-t-il la liberté, l'ordre public et le principe de l'égalité ?","solution":"Oui : le législateur a pu instituer un contrat distinct du mariage et du concubinage, entre personnes de même sexe ou de sexes différents, sans méconnaître les exigences constitutionnelles ; le Conseil définit le concubinage.","portee":"Valide le PACS et définit le concubinage comme une situation de fait ; ce régime est ensuite ancré dans le Code civil.","tags":["PACS","concubinage","vie privée"],"id":"seed-jp-1999-11-09-pacte-civil-de-solidarite-n-99-419-dc"},{"titre":"Accessibilité et intelligibilité de la loi (n° 99-421 DC)","juridiction":"Conseil constitutionnel","date":"1999-12-16","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Une loi habilite le Gouvernement à codifier par ordonnances ; elle est contestée pour atteinte à la compétence du Parlement.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"L'accessibilité et l'intelligibilité de la loi sont-elles des exigences constitutionnelles ?","solution":"Oui : l'égalité devant la loi et la garantie des droits impliquent que les citoyens disposent d'une connaissance suffisante des règles qui leur sont applicables ; l'objectif de valeur constitutionnelle d'accessibilité et d'intelligibilité de la loi est consacré.","portee":"Objectif de valeur constitutionnelle souvent invoqué pour contrôler les lois trop complexes ou bavardes.","tags":["intelligibilité","codification","objectif constitutionnel"],"id":"seed-jp-1999-12-16-accessibilite-et-intelligibilite-de-la-l"},{"titre":"Mlle Fraisse (Ass. plén.)","juridiction":"Cour de cassation","date":"2000-06-02","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Une personne conteste son exclusion des listes électorales en Nouvelle-Calédonie, en invoquant le Pacte international relatif aux droits civils et politiques.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation.","probleme":"Les traités l'emportent-ils sur la Constitution dans l'ordre interne ?","solution":"Non : la suprématie conférée aux engagements internationaux ne s'applique pas dans l'ordre interne aux dispositions de valeur constitutionnelle.","portee":"La Cour de cassation s'aligne sur le Conseil d'État (Sarran) : le constituant l'emporte, mais le contrôle de conventionnalité reste du ressort du juge ordinaire.","tags":["hiérarchie des normes","Constitution","traité"],"id":"seed-jp-2000-06-02-mlle-fraisse-ass-plen"},{"titre":"Interruption volontaire de grossesse (n° 2001-446 DC)","juridiction":"Conseil constitutionnel","date":"2001-06-27","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi relative à l'interruption volontaire de grossesse et à la contraception allonge le délai de recours à l'IVG de dix à douze semaines.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"L'allongement du délai respecte-t-il le principe de sauvegarde de la dignité de la personne humaine ?","solution":"Oui : le législateur n'a pas rompu l'équilibre entre le respect de l'être humain dès le commencement de la vie et la liberté de la femme, issue de l'article 2 de la Déclaration de 1789.","portee":"Le Conseil rattache la liberté de la femme à l'article 2 de la Déclaration ; ce raisonnement est repris en 2023 lors de la constitutionnalisation de la liberté de recourir à l'IVG.","tags":["IVG","liberté","dignité"],"id":"seed-jp-2001-06-27-interruption-volontaire-de-grossesse-n-2"},{"titre":"Loi de modernisation sociale (n° 2001-455 DC)","juridiction":"Conseil constitutionnel","date":"2002-01-12","matiere":"Droit constitutionnel","niveau":"L3","faits":"La loi de modernisation sociale redéfinit strictement le licenciement économique, ce que contestent des parlementaires comme atteinte à la liberté d'entreprendre.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le législateur peut-il restreindre la notion de licenciement économique au regard de la liberté d'entreprendre ?","solution":"Non, en partie : la définition retenue méconnaît la liberté d'entreprendre car elle conduit à priver le chef d'entreprise de la possibilité de prendre les mesures nécessaires à la sauvegarde de la compétitivité ; elle est censurée.","portee":"Illustre la conciliation entre le droit à l'emploi et la liberté d'entreprendre, constitutionnellement garantie.","tags":["liberté d'entreprendre","licenciement économique","droit au travail"],"id":"seed-jp-2002-01-12-loi-de-modernisation-sociale-n-2001-455-"},{"titre":"Transposition des directives — LCEN (n° 2004-496 DC)","juridiction":"Conseil constitutionnel","date":"2004-06-10","matiere":"Droit constitutionnel","niveau":"L3","faits":"La loi pour la confiance dans l'économie numérique transpose la directive sur le commerce électronique ; elle est déférée pour méconnaissance de la compétence du législateur.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le Conseil constitutionnel peut-il contrôler la loi de transposition d'une directive au regard de la directive elle-même ?","solution":"La transposition d'une directive résulte d'une exigence constitutionnelle (art. 88-1) ; le Conseil ne peut contrôler une loi de transposition que si elle méconnaît une disposition expresse et inconditionnelle de la directive ; il ne se prononce pas sur la compatibilité directe de la loi avec la directive.","portee":"Pose le cadre du contrôle des lois de transposition ; complété par la décision n° 2006-540 DC (identité constitutionnelle) et le renvoi préjudiciel à la CJUE.","tags":["directive","article 88-1","transposition"],"id":"seed-jp-2004-06-10-transposition-des-directives-lcen-n-2004"},{"titre":"Traité établissant une Constitution pour l'Europe (n° 2004-505 DC)","juridiction":"Conseil constitutionnel","date":"2004-11-19","matiere":"Droit constitutionnel","niveau":"L3","faits":"Le traité signé à Rome en octobre 2004 institue une « Constitution » européenne, avec la reconnaissance du principe de primauté du droit de l'Union.","procedure":"Saisine du Président de la République avant la ratification.","probleme":"La primauté du droit de l'Union, inscrite dans le traité, s'impose-t-elle à la Constitution française ?","solution":"La primauté ne joue pas à l'égard de la Constitution française, qui reste au sommet de l'ordre interne ; le traité n'en nécessite pas moins une révision, notamment pour l'exercice de compétences nouvelles et le contrôle parlementaire.","portee":"Le traité est finalement rejeté par référendum en 2005 ; la décision a clarifié la place de la Constitution et du droit de l'Union.","tags":["traité","primauté","révision"],"id":"seed-jp-2004-11-19-traite-etablissant-une-constitution-pour"},{"titre":"Normativité de la loi — loi d'orientation sur l'école (n° 2005-512 DC)","juridiction":"Conseil constitutionnel","date":"2005-04-21","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi d'orientation et de programme pour l'avenir de l'école comporte des dispositions programmatiques (objectifs, voeux).","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le législateur peut-il inscrire dans la loi des dispositions sans portée normative ?","solution":"Non : sous l'empire de la Constitution de 1958, la loi a pour vocation d'énoncer des règles et doit par suite être revêtue d'une portée normative ; les dispositions programmatiques sont censurées.","portee":"Précisent le rôle de la loi ; la décision limite les « lois bavardes ».","tags":["normativité","loi","article 34"],"id":"seed-jp-2005-04-21-normativite-de-la-loi-loi-d-orientation-"},{"titre":"Droit d'auteur et droits voisins — DADVSI (n° 2006-540 DC)","juridiction":"Conseil constitutionnel","date":"2006-07-27","matiere":"Droit constitutionnel","niveau":"L3-M1","faits":"La loi sur le droit d'auteur dans la société de l'information transpose une directive de 2001 et crée un régime de sanctions et de mesures techniques de protection.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Jusqu'où va l'exigence constitutionnelle de transposition des directives, et quelles limites la Constitution lui oppose-t-elle ?","solution":"La transposition d'une directive ne saurait aller à l'encontre d'une règle ou d'un principe inhérent à l'identité constitutionnelle de la France, sauf consentement du constituant. Le Conseil censure plusieurs dispositions sur d'autres fondements (égalité, légalité des délits).","portee":"Première apparition de l'« identité constitutionnelle » comme limite à la primauté ; reprise ensuite dans le dialogue avec la CJUE (décision n° 2013-314P QPC, première question préjudicielle).","tags":["identité constitutionnelle","directive","propriété intellectuelle"],"id":"seed-jp-2006-07-27-droit-d-auteur-et-droits-voisins-dadvsi-"},{"titre":"Société Arcelor Atlantique et Lorraine (Ass.)","juridiction":"Conseil d'État","date":"2007-02-08","matiere":"Droit constitutionnel","niveau":"M1","faits":"Des sociétés sidérurgiques contestent un décret transposant une directive sur les quotas d'émission de gaz à effet de serre.","procedure":"Recours pour excès de pouvoir devant le Conseil d'État, assemblée du contentieux.","probleme":"Comment le juge administratif contrôle-t-il un acte réglementaire de transposition d'une directive, au regard de la Constitution ?","solution":"Il contrôle d'abord si le principe constitutionnel invoqué a un équivalent dans l'ordre juridique de l'Union ; si oui, il vérifie la directive au regard du principe de l'Union, et saisit si besoin la CJUE ; sinon, il contrôle le décret au regard de la Constitution.","portee":"Établit la méthode du juge administratif pour articuler Constitution et droit de l'Union (« contrôle de l'équivalence » des protections).","tags":["primauté","droit de l'Union","constitutionnalité","directive"],"id":"seed-jp-2007-02-08-societe-arcelor-atlantique-et-lorraine-a"},{"titre":"Maîtrise de l'immigration — statistiques ethniques (n° 2007-557 DC)","juridiction":"Conseil constitutionnel","date":"2007-11-15","matiere":"Droit constitutionnel","niveau":"L3-M1","faits":"La loi relative à la maîtrise de l'immigration prévoit un test ADN pour le regroupement familial et autorise les études sur la diversité des origines.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Les statistiques fondées sur l'origine ethnique et le test ADN sont-ils conformes à la Constitution ?","solution":"Les traitements de données mesurant la diversité des origines, du fait des principes d'égalité et d'indivisibilité de la République, ne peuvent reposer sur la race ou l'origine ethnique ; la disposition est censurée ; le test ADN, encadré, est validé.","portee":"Pose l'interdiction des statistiques ethniques, fondée sur l'article 1er de la Constitution.","tags":["immigration","égalité","statistiques ethniques"],"id":"seed-jp-2007-11-15-maitrise-de-l-immigration-statistiques-e"},{"titre":"Rétention de sûreté (n° 2008-562 DC)","juridiction":"Conseil constitutionnel","date":"2008-02-21","matiere":"Droit constitutionnel","niveau":"L3","faits":"La loi instaure une rétention de sûreté permettant de maintenir enfermés, après leur peine, des condamnés jugés particulièrement dangereux.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"La rétention de sûreté est-elle une peine, soumise à la non-rétroactivité des peines plus sévères ?","solution":"La rétention de sûreté n'est ni une peine ni une sanction ; mais elle est privative de liberté, et il serait contraire à la Constitution de l'appliquer à des personnes condamnées pour des faits commis avant la loi : cette application rétroactive est censurée.","portee":"Ouvre le débat sur la distinction entre peine et mesure de sûreté, reprise par la CEDH ; le Conseil évite de qualifier la rétention de peine.","tags":["rétention de sûreté","peine","rétroactivité"],"id":"seed-jp-2008-02-21-retention-de-surete-n-2008-562-dc"},{"titre":"Charte de l'environnement — OGM (n° 2008-564 DC)","juridiction":"Conseil constitutionnel","date":"2008-06-19","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"La loi relative aux organismes génétiquement modifiés encadre les cultures et la coexistence avec les filières traditionnelles.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Les droits et devoirs de la Charte de l'environnement ont-ils valeur constitutionnelle et peuvent-ils fonder un contrôle de la loi ?","solution":"Oui : tous les droits et devoirs définis dans la Charte ont valeur constitutionnelle ; ils s'imposent aux pouvoirs publics. Le Conseil censure l'article qui ne définit pas suffisamment les informations accessibles au public.","portee":"La Charte de l'environnement (2004) fait partie du bloc de constitutionnalité.","tags":["environnement","Charte","information"],"id":"seed-jp-2008-06-19-charte-de-l-environnement-ogm-n-2008-564"},{"titre":"Commune d'Annecy (Ass.)","juridiction":"Conseil d'État","date":"2008-10-03","matiere":"Droit constitutionnel","niveau":"M1","faits":"Une association conteste une décision d'une commune en invoquant la Charte de l'environnement de 2004.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Les dispositions de la Charte de l'environnement de 2004 peuvent-elles être invoquées devant le juge administratif ?","solution":"Oui : l'ensemble des droits et devoirs définis dans la Charte de l'environnement ont valeur constitutionnelle ; ils s'imposent aux pouvoirs publics et aux autorités administratives dans leurs domaines de compétence respectifs, et leur méconnaissance peut être invoquée.","portee":"Consacre la valeur constitutionnelle de la Charte devant le juge administratif ; l'article 7 est invocable (Sté Arcelor, Association Eaux et rivières de Bretagne).","tags":["Charte de l'environnement","valeur constitutionnelle","légalité"],"id":"seed-jp-2008-10-03-commune-d-annecy-ass"},{"titre":"Hadopi (n° 2009-580 DC)","juridiction":"Conseil constitutionnel","date":"2009-06-10","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"La loi favorisant la diffusion et la protection de la création sur internet confie à une autorité administrative le pouvoir de suspendre l'accès à internet des abonnés.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Une autorité administrative peut-elle restreindre l'accès à internet en l'absence de décision du juge ?","solution":"Non : la liberté de communiquer et de s'exprimer librement, qui inclut l'accès à internet, ne peut être restreinte que par le juge ; le pouvoir de sanction de l'autorité administrative est censuré, ainsi que le renversement de la charge de la preuve.","portee":"Reconnaît l'accès à internet comme composante de la liberté d'expression ; la loi est ensuite modifiée pour confier la sanction au juge.","tags":["liberté de communication","internet","présomption d'innocence"],"id":"seed-jp-2009-06-10-hadopi-n-2009-580-dc"},{"titre":"Mme Perreux (Ass.)","juridiction":"Conseil d'État","date":"2009-10-30","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Une magistrate conteste une décision de nomination qu'elle estime discriminatoire au regard d'une directive.","procedure":"Recours devant le Conseil d'État, assemblée du contentieux.","probleme":"Un justiciable peut-il invoquer une directive à l'appui d'un recours contre un acte individuel ?","solution":"Oui : tout justiciable peut se prévaloir, à l'appui d'un recours dirigé contre un acte administratif non réglementaire, des dispositions précises et inconditionnelles d'une directive lorsque l'État n'a pas pris les mesures de transposition dans les délais.","portee":"Abandonne la jurisprudence Cohn-Bendit, en alignant la juridiction administrative sur la CJUE.","tags":["directive","effet direct","droit de l'Union"],"id":"seed-jp-2009-10-30-mme-perreux-ass"},{"titre":"Consorts L. — pensions (n° 2010-1 QPC)","juridiction":"Conseil constitutionnel","date":"2010-05-28","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Des anciens militaires étrangers, ressortissants de pays autrefois sous souveraineté française, perçoivent des pensions « cristallisées », inférieures à celles des Français.","procedure":"Le Conseil d'État renvoie la question au Conseil constitutionnel ; c'est l'une des premières QPC (en vigueur depuis le 1er mars 2010).","probleme":"La différence de traitement des pensions selon la nationalité méconnaît-elle le principe d'égalité ?","solution":"Oui : la différence de traitement fondée sur la nationalité ne se justifie pas au regard de l'objet de la loi ; les dispositions sont déclarées contraires à la Constitution et abrogées.","portee":"Première QPC aboutissant à une censure ; le Conseil définit sa méthode d'abrogation différée.","tags":["QPC","égalité","pensions"],"id":"seed-jp-2010-05-28-consorts-l-pensions-n-2010-1-qpc"},{"titre":"Hospitalisation sans consentement — Danielle S. (n° 2010-71 QPC)","juridiction":"Conseil constitutionnel","date":"2010-11-26","matiere":"Droit constitutionnel","niveau":"L3-M1","faits":"Une personne hospitalisée d'office pour troubles mentaux conteste le maintien de la mesure sans contrôle systématique d'un juge.","procedure":"Le Conseil d'État renvoie la QPC au Conseil constitutionnel.","probleme":"Une hospitalisation sans consentement peut-elle durer plus d'une quinzaine de jours sans intervention d'un juge ?","solution":"Non : l'article 66 de la Constitution exige l'intervention de l'autorité judiciaire dans le plus court délai pour toute privation de liberté ; le maintien de l'hospitalisation au-delà de quinze jours sans contrôle d'un juge est contraire à la Constitution.","portee":"Conduit à la loi du 5 juillet 2011 qui impose le contrôle du juge des libertés et de la détention.","tags":["liberté individuelle","hospitalisation d'office","contrôle du juge"],"id":"seed-jp-2010-11-26-hospitalisation-sans-consentement-daniel"},{"titre":"Mariage homosexuel — Corinne C. (n° 2010-92 QPC)","juridiction":"Conseil constitutionnel","date":"2011-01-28","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"Deux femmes se voient refuser la célébration de leur mariage par un officier d'état civil ; elles contestent les articles du Code civil qui réservent le mariage aux couples de sexe différent.","procedure":"La Cour de cassation renvoie la QPC au Conseil constitutionnel.","probleme":"L'interdiction du mariage entre personnes de même sexe est-elle contraire à la Constitution ?","solution":"Non : le principe d'égalité ne s'oppose ni à ce que le législateur règle de façon différente des situations différentes ni à ce qu'il déroge à l'égalité pour des raisons d'intérêt général ; il n'appartient pas au Conseil de substituer son appréciation à celle du législateur sur la différence de situation entre couples de même sexe et de sexes différents.","portee":"Renvoie la question au législateur ; la loi du 17 mai 2013 ouvrira le mariage (décision n° 2013-669 DC).","tags":["mariage","égalité","QPC"],"id":"seed-jp-2011-01-28-mariage-homosexuel-corinne-c-n-2010-92-q"},{"titre":"Pénalisation de la négation des génocides (n° 2012-647 DC)","juridiction":"Conseil constitutionnel","date":"2012-02-28","matiere":"Droit constitutionnel","niveau":"L3-M1","faits":"Une loi punit la contestation ou la minimisation de génocides reconnus par la loi, en visant notamment le génocide arménien.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le législateur peut-il réprimer la contestation de l'existence de génocides qu'il a reconnus lui-même ?","solution":"Non : en réprimant la contestation de l'existence et de la qualification juridique de crimes qu'il aurait lui-même reconnus et qualifiés, le législateur a porté une atteinte inconstitutionnelle à l'exercice de la liberté d'expression.","portee":"Distingue la loi pénale de la loi mémorielle ; à rapprocher de Perinçek c. Suisse (CEDH, GC, 2015).","tags":["liberté d'expression","légalité","négationnisme"],"id":"seed-jp-2012-02-28-penalisation-de-la-negation-des-genocide"},{"titre":"Harcèlement sexuel — Gérard D. (n° 2012-240 QPC)","juridiction":"Conseil constitutionnel","date":"2012-05-04","matiere":"Droit constitutionnel","niveau":"L3","faits":"Une personne poursuivie pour harcèlement sexuel conteste l'article 222-33 du Code pénal, qui punissait « le fait de harceler autrui dans le but d'obtenir des faveurs de nature sexuelle ».","procedure":"La Cour de cassation renvoie la QPC au Conseil constitutionnel.","probleme":"La définition légale du délit de harcèlement sexuel est-elle suffisamment précise pour respecter le principe de légalité des délits ?","solution":"Non : en ne définissant pas précisément les éléments constitutifs du délit, le législateur a méconnu le principe de légalité ; l'article est abrogé avec effet immédiat.","portee":"Conduit à la loi du 6 août 2012 qui réécrit le délit ; le Conseil écarte ici le report d'effet pour éviter un vide juridique.","tags":["légalité des délits","harcèlement sexuel","abrogation"],"id":"seed-jp-2012-05-04-harcelement-sexuel-gerard-d-n-2012-240-q"},{"titre":"Traité sur la stabilité, la coordination et la gouvernance (n° 2012-653 DC)","juridiction":"Conseil constitutionnel","date":"2012-08-09","matiere":"Droit constitutionnel","niveau":"M1","faits":"Le traité budgétaire européen impose des règles d'équilibre des finances publiques et un mécanisme de correction.","procedure":"Saisine du Président de la République avant la ratification.","probleme":"Le traité sur la stabilité (TSCG) exige-t-il une révision de la Constitution ?","solution":"Non : le traité n'implique pas de transfert de souveraineté non couvert par la Constitution ; la règle d'équilibre sera mise en oeuvre par une loi organique, sans révision.","portee":"Illustre le contrôle de constitutionnalité des traités (art. 54) et le rôle de la loi organique.","tags":["traité budgétaire","souveraineté","loi organique"],"id":"seed-jp-2012-08-09-traite-sur-la-stabilite-la-coordination-"},{"titre":"Mariage des personnes de même sexe (n° 2013-669 DC)","juridiction":"Conseil constitutionnel","date":"2013-05-17","matiere":"Droit constitutionnel","niveau":"L1-L2","faits":"La loi ouvre le mariage et l'adoption aux couples de personnes de même sexe.","procedure":"Saisine de parlementaires de l'opposition avant promulgation.","probleme":"Le mariage est-il constitutionnellement réservé aux couples de sexe différent, ou le législateur peut-il l'ouvrir aux couples de même sexe ?","solution":"Il n'existe pas de principe fondamental reconnu par les lois de la République qui définirait le mariage comme l'union d'un homme et d'une femme ; l'ouverture relève de la compétence du législateur, qui peut modifier le droit de la famille. La loi est jugée conforme, sous réserves.","portee":"Précise la notion de PFRLR et la limite du contrôle du juge, qui ne substitue pas son appréciation à celle du législateur sur des questions de société.","tags":["mariage","égalité","PFRLR"],"id":"seed-jp-2013-05-17-mariage-des-personnes-de-meme-sexe-n-201"},{"titre":"Loi relative au renseignement (n° 2015-713 DC)","juridiction":"Conseil constitutionnel","date":"2015-07-23","matiere":"Droit constitutionnel","niveau":"M1","faits":"La loi sur le renseignement autorise de nouvelles techniques de surveillance (balises, algorithmes de détection, interceptions) sous le contrôle d'une commission administrative.","procedure":"Saisine du Président de la République, du Premier ministre et de parlementaires avant promulgation.","probleme":"Les techniques de recueil de renseignement respectent-elles le droit à la vie privée et au secret des correspondances ?","solution":"En grande partie : le Conseil valide le régime général, qui poursuit des objectifs de sauvegarde des intérêts fondamentaux de la Nation, avec des garanties (commission, recours devant le Conseil d'État), mais censure les dispositions sur la surveillance internationale, qui n'étaient pas encadrées.","portee":"Précise l'équilibre entre sécurité et vie privée ; complété par la décision n° 2015-722 DC sur la loi relative à la surveillance internationale.","tags":["renseignement","vie privée","surveillance"],"id":"seed-jp-2015-07-23-loi-relative-au-renseignement-n-2015-713"},{"titre":"Délit de solidarité (n° 2018-717/718 QPC)","juridiction":"Conseil constitutionnel","date":"2018-07-06","matiere":"Droit constitutionnel","niveau":"L2-L3","faits":"Un agriculteur est poursuivi pour avoir aidé des étrangers en situation irrégulière à franchir la frontière et à circuler en France.","procedure":"La Cour de cassation renvoie les QPC au Conseil constitutionnel.","probleme":"Le principe de fraternité a-t-il une valeur constitutionnelle, et le délit d'aide à l'entrée, à la circulation et au séjour irrégulier le respecte-t-il ?","solution":"Le principe de fraternité est un principe à valeur constitutionnelle (art. 2 de la Constitution, devise de la République) ; il en découle la liberté d'aider autrui dans un but humanitaire. Les dispositions sont censurées en ce qu'elles ne couvraient pas l'aide à la circulation et au séjour.","portee":"Consécration du principe de fraternité, jusque-là simple devise ; le législateur a révisé le texte en 2018.","tags":["fraternité","séjour irrégulier","QPC"],"id":"seed-jp-2018-07-06-delit-de-solidarite-n-2018-717-718-qpc"},{"titre":"Loi visant à renforcer et garantir le maintien de l'ordre public lors des manifestations (n° 2019-780 DC)","juridiction":"Conseil constitutionnel","date":"2019-04-04","matiere":"Droit constitutionnel","niveau":"M1","faits":"La loi dite « anti-casseurs » permet au préfet d'interdire à des personnes de manifester et crée un délit de dissimulation du visage.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Une interdiction administrative individuelle de manifester est-elle conforme à la liberté d'expression collective des idées et des opinions ?","solution":"Non : l'interdiction administrative de manifester, par le préfet, porte atteinte au droit d'expression collective des idées et des opinions ; elle est censurée ; les autres dispositions sont validées sous réserve.","portee":"Rappelle que le droit de manifester est une composante de la liberté d'expression collective.","tags":["manifestation","liberté","interdiction administrative"],"id":"seed-jp-2019-04-04-loi-visant-a-renforcer-et-garantir-le-ma"},{"titre":"Loi relative à la lutte contre les contenus haineux sur internet (n° 2020-801 DC)","juridiction":"Conseil constitutionnel","date":"2020-06-18","matiere":"Droit constitutionnel","niveau":"M1","faits":"La loi impose aux plateformes de retirer en 24 heures les contenus haineux signalés, sous peine de lourdes sanctions pénales.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Le législateur peut-il imposer aux opérateurs de retirer rapidement des contenus illicites sans atteinte disproportionnée à la liberté d'expression ?","solution":"Non : l'obligation de retrait en 24 heures, pour des contenus dont le caractère illicite n'est pas manifeste, sans intervention préalable du juge, porte une atteinte non nécessaire, adaptée et proportionnée à la liberté d'expression ; les dispositions sont censurées.","portee":"Illustre le contrôle de proportionnalité de la liberté d'expression en ligne ; l'essentiel de la loi tombe.","tags":["liberté d'expression","internet","proportionnalité"],"id":"seed-jp-2020-06-18-loi-relative-a-la-lutte-contre-les-conte"},{"titre":"Loi pour une sécurité globale préservant les libertés (n° 2021-817 DC)","juridiction":"Conseil constitutionnel","date":"2021-05-20","matiere":"Droit constitutionnel","niveau":"M1","faits":"La loi renforce les pouvoirs de la police municipale, encadre l'usage des drones et érige en délit la diffusion de l'image des policiers (article 24).","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Les dispositions sur la diffusion d'images de policiers et la surveillance par drones sont-elles conformes aux droits fondamentaux ?","solution":"En partie non : l'article 24, imprécis et disproportionné au regard de la liberté d'expression, est censuré ; l'usage de drones par la police municipale est aussi censuré, faute de garanties suffisantes pour le droit au respect de la vie privée.","portee":"Illustre le contrôle de proportionnalité des mesures de sécurité ; le législateur reprendra certaines mesures dans des lois ultérieures.","tags":["sécurité","vidéosurveillance","droit à l'image","légalité"],"id":"seed-jp-2021-05-20-loi-pour-une-securite-globale-preservant"},{"titre":"Passe sanitaire (n° 2021-824 DC)","juridiction":"Conseil constitutionnel","date":"2021-08-05","matiere":"Droit constitutionnel","niveau":"M1","faits":"La loi relative à la gestion de la crise sanitaire institue un passe sanitaire, une obligation vaccinale pour certaines professions et un régime de sanctions.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Les restrictions aux libertés dues à l'épidémie, et notamment le passe sanitaire, sont-elles conformes à la Constitution ?","solution":"En grande partie oui : le Conseil juge proportionnées les mesures de passe sanitaire et d'obligation vaccinale, en tenant compte de l'objectif de protection de la santé ; il censure l'isolement obligatoire sans contrôle du juge et la rupture anticipée des contrats courts.","portee":"Illustre l'office du Conseil face à l'état d'urgence sanitaire : conciliation entre santé publique et libertés.","tags":["crise sanitaire","liberté d'aller et venir","proportionnalité"],"id":"seed-jp-2021-08-05-passe-sanitaire-n-2021-824-dc"},{"titre":"Loi confortant le respect des principes de la République (n° 2021-823 DC)","juridiction":"Conseil constitutionnel","date":"2021-08-13","matiere":"Droit constitutionnel","niveau":"M1","faits":"La loi renforce la laïcité, la neutralité des services publics, le contrôle des associations et encadre l'instruction en famille.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"Les mesures de la loi sur les associations, l'instruction en famille et la neutralité sont-elles conformes aux libertés constitutionnelles ?","solution":"En grande partie oui : le Conseil valide l'essentiel du texte, y compris le contrat d'engagement républicain et le régime d'autorisation de l'instruction en famille, mais censure certaines dispositions (articles étrangers au texte ou disproportionnés).","portee":"Valide pour la première fois que la liberté d'enseignement n'impose pas de laisser libre l'instruction en famille ; reconnaît la liberté de conscience comme limite.","tags":["laïcité","liberté d'association","instruction en famille"],"id":"seed-jp-2021-08-13-loi-confortant-le-respect-des-principes-"},{"titre":"Réforme des retraites (n° 2023-849 DC)","juridiction":"Conseil constitutionnel","date":"2023-04-14","matiere":"Droit constitutionnel","niveau":"M1","faits":"La loi de financement rectificative de la sécurité sociale pour 2023 repousse l'âge légal de départ à la retraite ; elle est adoptée par la procédure de l'article 49, alinéa 3 de la Constitution.","procedure":"Saisine de parlementaires avant promulgation.","probleme":"La procédure et le contenu de la loi sont-ils conformes à la Constitution ?","solution":"La procédure (article 47-1, engagement de responsabilité du Gouvernement) est conforme ; l'essentiel de la réforme est validé ; le Conseil censure toutefois six dispositions comme « cavaliers sociaux » étrangers au domaine des lois de financement.","portee":"Le même jour, la décision n° 2023-4 RIP rejette la demande de référendum d'initiative partagée.","tags":["procédure législative","loi de financement","article 47-1"],"id":"seed-jp-2023-04-14-reforme-des-retraites-n-2023-849-dc"},{"titre":"Van Gend en Loos","juridiction":"CJUE","date":"1963-02-05","matiere":"Droit de l'Union européenne","niveau":"L2-L3","faits":"Une société néerlandaise conteste un droit de douane relevé sur un produit importé d'Allemagne, qu'elle estime contraire à l'article 12 du traité CEE (interdiction de nouveaux droits).","procedure":"Une juridiction néerlandaise saisit la Cour de justice d'une question préjudicielle.","probleme":"Les particuliers peuvent-ils invoquer devant leur juge national les dispositions du traité CEE ?","solution":"Oui : la Communauté constitue un nouvel ordre juridique de droit international au profit duquel les États ont limité leurs droits souverains ; son droit crée des droits et obligations pour les particuliers, que les juridictions nationales doivent sauvegarder (effet direct).","portee":"Pose le principe de l'effet direct du droit de l'Union, aux conditions d'une disposition claire, précise et inconditionnelle.","tags":["effet direct","ordre juridique","grand arrêt"],"id":"seed-jp-1963-02-05-van-gend-en-loos"},{"titre":"Plaumann","juridiction":"CJUE","date":"1963-07-15","matiere":"Droit de l'Union européenne","niveau":"M1","faits":"Un importateur allemand de clémentines conteste une décision de la Commission adressée à l'Allemagne, qui lui refuse une suspension de droits de douane.","procedure":"Recours en annulation devant la Cour de justice.","probleme":"Un particulier peut-il former un recours en annulation contre une décision adressée à un État ?","solution":"Il doit être concerné directement et individuellement : les personnes autres que les destinataires ne sont individuellement concernées que si la décision les atteint en raison de qualités qui leur sont particulières ou d'une situation de fait qui les caractérise par rapport à tous autres ; le recours est rejeté.","portee":"Formule Plaumann, interprétation restrictive de l'intérêt à agir des particuliers ; assouplie par le traité de Lisbonne pour les actes réglementaires (art. 263, al. 4).","tags":["recours en annulation","intérêt à agir","particuliers"],"id":"seed-jp-1963-07-15-plaumann"},{"titre":"Costa c. ENEL","juridiction":"CJUE","date":"1964-07-15","matiere":"Droit de l'Union européenne","niveau":"L2-L3","faits":"Un actionnaire d'une société d'électricité conteste la nationalisation italienne de la production d'électricité, en invoquant des dispositions du traité.","procedure":"Le juge italien saisit la Cour de justice d'une question préjudicielle.","probleme":"Le droit communautaire prime-t-il sur une loi nationale postérieure ?","solution":"Oui : issu d'une source autonome, le droit du traité ne peut se voir judiciairement opposer un texte interne quel qu'il soit sans perdre son caractère communautaire ; le transfert de compétences des États entraîne une limitation définitive de leurs droits souverains.","portee":"Consacre la primauté du droit de l'Union, sans distinction entre norme nationale antérieure ou postérieure.","tags":["primauté","ordre juridique","grand arrêt"],"id":"seed-jp-1964-07-15-costa-c-enel"},{"titre":"Commission c. Luxembourg et Belgique","juridiction":"CJUE","date":"1964-11-13","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Le Luxembourg et la Belgique maintiennent des droits de douane sur des produits laitiers, en réponse à des manquements d'autres États, que la Commission leur reproche.","procedure":"Recours en manquement de la Commission devant la Cour de justice.","probleme":"Un État membre peut-il suspendre l'exécution du droit communautaire parce qu'un autre État l'a violé ?","solution":"Non : le traité ne se borne pas à créer des obligations réciproques entre États ; il crée un ordre juridique propre, avec des voies de recours : un État ne peut se faire justice lui-même (rejet de l'exception d'inexécution).","portee":"Rend inopposable l'exception d'inexécution, propre au droit international général ; il fonde l'autonomie de l'ordre juridique communautaire.","tags":["exception d'inexécution","ordre juridique","manquement"],"id":"seed-jp-1964-11-13-commission-c-luxembourg-et-belgique"},{"titre":"Consten et Grundig","juridiction":"CJUE","date":"1966-07-13","matiere":"Droit de l'Union européenne","niveau":"M1-M2","faits":"Un distributeur exclusif français et un fabricant allemand d'appareils électriques organisent une protection territoriale absolue de la marque.","procedure":"Recours en annulation d'une décision de la Commission.","probleme":"Un accord de distribution exclusive qui cloisonne les marchés est-il une entente prohibée ?","solution":"Oui : un accord qui tend à isoler le marché national et à isoler les produits de la marque porte atteinte à la concurrence et au commerce entre États membres ; il est restrictif par son objet.","portee":"Fondation du droit de la concurrence de l'Union, avec la notion de restriction par objet.","tags":["ententes","distribution exclusive","restriction de concurrence"],"id":"seed-jp-1966-07-13-consten-et-grundig"},{"titre":"Stauder","juridiction":"CJUE","date":"1969-11-12","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Un bénéficiaire de la vente de beurre à prix réduit doit mentionner son nom sur le coupon, ce qu'il estime attentatoire à sa dignité.","procedure":"Question préjudicielle du tribunal administratif de Stuttgart.","probleme":"Les droits fondamentaux sont-ils protégés par l'ordre juridique communautaire ?","solution":"Oui : interprétée de façon raisonnable, la décision n'exige pas la révélation de l'identité ; elle ne porte pas atteinte aux droits fondamentaux de la personne, compris dans les principes généraux du droit communautaire dont la Cour assure le respect.","portee":"Première reconnaissance par la Cour des droits fondamentaux comme principes généraux du droit communautaire.","tags":["principes généraux","droits fondamentaux","interprétation"],"id":"seed-jp-1969-11-12-stauder"},{"titre":"Internationale Handelsgesellschaft","juridiction":"CJUE","date":"1970-12-17","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Un exportateur allemand invoque la violation de principes constitutionnels allemands par un règlement communautaire imposant une caution.","procedure":"Le tribunal administratif de Francfort pose une question préjudicielle.","probleme":"Une règle de droit national, même constitutionnelle, peut-elle faire échec à un règlement communautaire ?","solution":"Non : la validité d'un acte communautaire ne peut être affectée par des règles ou notions de droit national, fussent-elles constitutionnelles ; mais le respect des droits fondamentaux fait partie intégrante des principes généraux du droit protégés par la Cour.","portee":"Primauté absolue du droit de l'Union, avec l'engagement de protéger les droits fondamentaux au sein de l'ordre communautaire.","tags":["primauté","droits fondamentaux","constitution nationale"],"id":"seed-jp-1970-12-17-internationale-handelsgesellschaft"},{"titre":"Nold","juridiction":"CJUE","date":"1974-05-14","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Une entreprise allemande de commerce de charbon conteste une décision de la Commission sur les conditions de vente aux grossistes, au nom du droit de propriété et de la liberté d'entreprendre.","procedure":"Recours en annulation devant la Cour de justice.","probleme":"Sur quelles sources la Cour s'appuie-t-elle pour garantir les droits fondamentaux ?","solution":"La Cour s'inspire des traditions constitutionnelles communes aux États membres et des instruments internationaux auxquels les États ont coopéré ou adhéré (notamment la CEDH) ; le droit de propriété n'est pas absolu.","portee":"Précise les sources des droits fondamentaux de l'Union, à l'origine de l'article 6 TUE.","tags":["droits fondamentaux","propriété","traditions constitutionnelles"],"id":"seed-jp-1974-05-14-nold"},{"titre":"Dassonville","juridiction":"CJUE","date":"1974-07-11","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Des importateurs de whisky écossais en Belgique sont poursuivis pour ne pas avoir présenté un certificat d'origine exigé par la loi belge.","procedure":"Le tribunal de Bruxelles pose une question préjudicielle.","probleme":"Quelles mesures nationales constituent des mesures d'effet équivalent à des restrictions quantitatives interdites par l'article 34 TFUE ?","solution":"Toute réglementation commerciale des États membres susceptible d'entraver directement ou indirectement, actuellement ou potentiellement, le commerce intracommunautaire est une mesure d'effet équivalent.","portee":"Définition très large (formule Dassonville) ; tempérée par Keck et Mithouard.","tags":["mesure d'effet équivalent","restriction quantitative","marchandises"],"id":"seed-jp-1974-07-11-dassonville"},{"titre":"Van Duyn","juridiction":"CJUE","date":"1974-12-04","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Une ressortissante néerlandaise se voit refuser l'entrée au Royaume-Uni parce qu'elle travaille pour l'Église de scientologie.","procedure":"La High Court britannique pose une question préjudicielle sur l'invocabilité de la directive 64/221.","probleme":"Les directives peuvent-elles avoir un effet direct ?","solution":"Oui : l'effet utile de la directive serait affaibli si les particuliers ne pouvaient pas l'invoquer devant les juridictions nationales ; elles ont un effet direct si leurs dispositions sont inconditionnelles et suffisamment précises.","portee":"Fonde l'effet direct (vertical) des directives ; confirmé par Ratti (1979).","tags":["directive","effet direct","ordre public"],"id":"seed-jp-1974-12-04-van-duyn"},{"titre":"Defrenne II","juridiction":"CJUE","date":"1976-04-08","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Une hôtesse de l'air, Mme Defrenne, demande à son employeur (Sabena) une indemnité pour avoir été moins payée que ses collègues masculins.","procedure":"La cour du travail de Bruxelles saisit la Cour de justice d'une question préjudicielle.","probleme":"L'article 119 du traité sur l'égalité des rémunérations est-il d'effet direct et invocable entre particuliers ?","solution":"Oui : le principe de l'égalité des rémunérations entre hommes et femmes, pour un même travail, est d'effet direct et s'impose aux particuliers dans les conventions de travail, ce qui permet l'effet horizontal.","portee":"Première reconnaissance de l'effet direct horizontal d'une disposition du traité ; les effets sont toutefois limités dans le temps.","tags":["effet direct horizontal","égalité des rémunérations","article 119"],"id":"seed-jp-1976-04-08-defrenne-ii"},{"titre":"United Brands (bananes Chiquita)","juridiction":"CJUE","date":"1978-02-14","matiere":"Droit de l'Union européenne","niveau":"M1-M2","faits":"Un producteur de bananes refuse de livrer un distributeur danois et pratique des prix discriminatoires et excessifs.","procedure":"Recours contre une décision de la Commission.","probleme":"Quand une entreprise abuse-t-elle de sa position dominante en pratiquant des prix et des refus de vente ?","solution":"L'entreprise détient une position dominante sur le marché pertinent de la banane de marque ; le refus de livrer un client fidèle, la discrimination et les prix non raisonnables sont abusifs.","portee":"Précise la méthode : marché de produits, marché géographique, position dominante, abus.","tags":["position dominante","marché pertinent","prix abusifs"],"id":"seed-jp-1978-02-14-united-brands-bananes-chiquita"},{"titre":"Simmenthal","juridiction":"CJUE","date":"1978-03-09","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Un importateur de viande conteste des redevances sanitaires imposées par une loi italienne contraire au droit communautaire.","procedure":"Le pretore de Susa pose une question préjudicielle sur le pouvoir du juge de laisser inappliquée la loi interne.","probleme":"Le juge national doit-il écarter lui-même une loi nationale contraire au droit communautaire, sans attendre l'intervention de la Cour constitutionnelle ?","solution":"Oui : le juge national chargé d'appliquer le droit communautaire est tenu d'assurer le plein effet de ces normes en laissant au besoin inappliquée toute disposition contraire de la législation nationale, même postérieure, sans demander ni attendre son élimination préalable.","portee":"Confie à tout juge national le contrôle de conventionnalité au regard du droit de l'Union, ce qui a nourri l'évolution française (Nicolo, 1989).","tags":["primauté","juge national","loi postérieure"],"id":"seed-jp-1978-03-09-simmenthal"},{"titre":"Hoffmann-La Roche","juridiction":"CJUE","date":"1979-02-13","matiere":"Droit de l'Union européenne","niveau":"M1-M2","faits":"Un laboratoire suisse de vitamines accorde des remises de fidélité à ses clients pour les fidéliser.","procedure":"Recours contre une décision de la Commission.","probleme":"Comment définir la position dominante et l'abus d'une telle position ?","solution":"La position dominante est une position de puissance économique qui permet de faire obstacle au maintien d'une concurrence effective en donnant le pouvoir de comportements indépendants ; l'abus est une notion objective qui vise des comportements de nature à influencer la structure du marché.","portee":"Définition de l'abus de position dominante reprise dans toutes les décisions ultérieures.","tags":["position dominante","abus","définition"],"id":"seed-jp-1979-02-13-hoffmann-la-roche"},{"titre":"Cassis de Dijon (Rewe-Zentral)","juridiction":"CJUE","date":"1979-02-20","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Un importateur allemand d'une liqueur de cassis française se voit refuser l'autorisation de commercialiser en Allemagne un produit titrant moins d'alcool que le minimum légal allemand.","procedure":"Le tribunal des finances de Hesse pose une question préjudicielle.","probleme":"Un État peut-il interdire un produit légalement fabriqué dans un autre État membre en invoquant ses règles techniques ?","solution":"Non : sauf exigences impératives (protection de la santé, loyauté des transactions commerciales, protection du consommateur) proportionnées, un produit légalement fabriqué et commercialisé dans un État membre doit pouvoir circuler dans les autres ; il s'agit du principe de reconnaissance mutuelle.","portee":"Fondement du marché intérieur par la reconnaissance mutuelle plutôt que l'harmonisation.","tags":["libre circulation des marchandises","reconnaissance mutuelle"],"id":"seed-jp-1979-02-20-cassis-de-dijon-rewe-zentral"},{"titre":"Ratti","juridiction":"CJUE","date":"1979-04-05","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Un fabricant de solvants est poursuivi en Italie pour étiquetage non conforme à la législation interne, alors que celle-ci n'a pas encore transposé les directives applicables.","procedure":"Le juge italien saisit la Cour de justice d'une question préjudicielle.","probleme":"Un particulier peut-il invoquer une directive non transposée contre l'État après l'expiration du délai ?","solution":"Oui : après l'expiration du délai de transposition, l'État défaillant ne peut opposer aux particuliers sa propre carence ; les dispositions précises et inconditionnelles d'une directive peuvent être invoquées contre lui (effet vertical).","portee":"Complète Van Duyn ; fonde l'estoppel de l'État qui n'a pas transposé.","tags":["directive","effet direct vertical","délai de transposition"],"id":"seed-jp-1979-04-05-ratti"},{"titre":"Hauer","juridiction":"CJUE","date":"1979-12-13","matiere":"Droit de l'Union européenne","niveau":"M1","faits":"Une viticultrice allemande se voit refuser l'autorisation de planter des vignes en raison d'un règlement communautaire interdisant de nouvelles plantations.","procedure":"Question préjudicielle du tribunal administratif de Neustadt.","probleme":"Le règlement communautaire est-il valide au regard du droit de propriété protégé par les droits fondamentaux ?","solution":"Oui : le droit de propriété est protégé dans l'ordre juridique communautaire mais peut être restreint dans l'intérêt général, sans atteinte à sa substance ; l'interdiction de plantation est justifiée par l'objectif d'organisation du marché viticole.","portee":"Confirme que les restrictions à la propriété sont valables si elles répondent à l'intérêt général et ne portent pas atteinte à la substance du droit.","tags":["droit de propriété","viticulture","droits fondamentaux"],"id":"seed-jp-1979-12-13-hauer"},{"titre":"Cilfit","juridiction":"CJUE","date":"1982-10-06","matiere":"Droit de l'Union européenne","niveau":"M1","faits":"Des importateurs de laines contestent une taxe sanitaire italienne ; la Cour de cassation italienne s'interroge sur son obligation de saisir la Cour de justice.","procedure":"Question préjudicielle de la Cour de cassation italienne.","probleme":"Une juridiction de dernier ressort doit-elle toujours poser une question préjudicielle ?","solution":"Non : elle en est dispensée lorsque la question n'est pas pertinente, lorsque la disposition a déjà été interprétée par la Cour (acte éclairé) ou lorsque l'application correcte du droit est évidente (acte clair), dans des conditions strictes.","portee":"Précise l'étendue de l'obligation de renvoi de l'article 267, alinéa 3 TFUE.","tags":["renvoi préjudiciel","acte clair","juridiction de dernier ressort"],"id":"seed-jp-1982-10-06-cilfit"},{"titre":"Von Colson et Kamann","juridiction":"CJUE","date":"1984-04-10","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Des candidates à des postes de travailleuses sociales dans une prison allemande sont écartées en raison de leur sexe et ne reçoivent que le remboursement de leurs frais.","procedure":"Question préjudicielle d'un tribunal du travail allemand.","probleme":"Les sanctions des discriminations doivent-elles être effectives et dissuasives, et le juge doit-il interpréter son droit national en ce sens ?","solution":"Oui : la directive impose des sanctions garantissant une protection juridictionnelle effective, avec un effet dissuasif ; les juridictions doivent interpréter leur droit national à la lumière de la directive, pour atteindre le résultat visé.","portee":"Origine de l'interprétation conforme, outil d'effectivité des directives.","tags":["interprétation conforme","sanction","directive"],"id":"seed-jp-1984-04-10-von-colson-et-kamann"},{"titre":"Marshall (n° 1)","juridiction":"CJUE","date":"1986-02-26","matiere":"Droit de l'Union européenne","niveau":"L3","faits":"Une diététicienne d'un hôpital public est licenciée à 62 ans, alors que l'âge de la retraite était fixé à 60 ans pour les femmes et à 65 ans pour les hommes ; elle invoque une discrimination en raison du sexe.","procedure":"Le Court of Appeal britannique pose une question préjudicielle.","probleme":"Une directive non transposée peut-elle être invoquée contre un particulier ?","solution":"Non : une directive ne peut pas, par elle-même, créer d'obligations dans le chef d'un particulier ; elle peut être invoquée contre l'État, y compris en sa qualité d'employeur.","portee":"Écarte l'effet direct horizontal des directives ; position confirmée par Faccini Dori (1994).","tags":["directive","effet horizontal","État employeur"],"id":"seed-jp-1986-02-26-marshall-n-1"},{"titre":"Les Verts c. Parlement","juridiction":"CJUE","date":"1986-04-23","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Un parti écologiste conteste des décisions du Parlement européen sur l'utilisation des crédits de campagne.","procedure":"Recours en annulation devant la Cour de justice.","probleme":"Les actes du Parlement européen peuvent-ils faire l'objet d'un recours en annulation alors que le traité ne les mentionnait pas ?","solution":"Oui : la Communauté économique européenne est une communauté de droit ; ni ses États membres ni ses institutions n'échappent au contrôle de la conformité de leurs actes à la charte constitutionnelle de base qu'est le traité.","portee":"Qualifie le traité de « charte constitutionnelle de base » ; a étendu le contrôle de légalité à tous les actes destinés à produire des effets de droit.","tags":["Communauté de droit","recours en annulation","Parlement européen"],"id":"seed-jp-1986-04-23-les-verts-c-parlement"},{"titre":"Lawrie-Blum","juridiction":"CJUE","date":"1986-07-03","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Une ressortissante britannique est refusée comme enseignante stagiaire (Referendar) dans un lycée du Bade-Wurtemberg, faute d'avoir la nationalité allemande, et soutient qu'elle est une travailleuse.","procedure":"Question préjudicielle du Bundesverwaltungsgericht.","probleme":"Qu'est-ce qu'un « travailleur » au sens de la libre circulation ?","solution":"Est travailleur celui qui accomplit, pendant un certain temps, en faveur d'une autre personne et sous la direction de celle-ci, des prestations en contrepartie desquelles il touche une rémunération ; la notion est communautaire, non nationale.","portee":"Définition européenne autonome du travailleur, très utilisée pour les stagiaires, les sportifs, les travailleurs de plateforme.","tags":["libre circulation des travailleurs","notion de travailleur","stage"],"id":"seed-jp-1986-07-03-lawrie-blum"},{"titre":"Foto-Frost","juridiction":"CJUE","date":"1987-10-22","matiere":"Droit de l'Union européenne","niveau":"M1","faits":"Une société allemande conteste une décision de la Commission rendant applicable des droits de douane ; le tribunal national doute de la validité de la décision.","procedure":"Le tribunal des finances de Hambourg saisit la Cour de justice d'une question préjudicielle.","probleme":"Un juge national peut-il déclarer invalide un acte des institutions ?","solution":"Non : les juridictions nationales peuvent examiner la validité d'un acte et le juger valable ; mais seule la Cour de justice peut le déclarer invalide.","portee":"Compétence exclusive de la Cour de justice pour constater l'invalidité des actes de l'Union.","tags":["invalidité","renvoi préjudiciel","monopole de la Cour"],"id":"seed-jp-1987-10-22-foto-frost"},{"titre":"Marleasing","juridiction":"CJUE","date":"1990-11-13","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Une société espagnole invoque la nullité de la constitution d'une autre société comme simulée, en application du Code civil espagnol ; la directive sur les sociétés ne prévoit pas ce motif de nullité.","procedure":"Question préjudicielle d'un tribunal de Barcelone.","probleme":"Le juge national doit-il interpréter le droit interne à la lumière des directives, y compris entre particuliers ?","solution":"Oui : le juge national doit interpréter le droit national, autant que possible, à la lumière du texte et de la finalité de la directive pour atteindre le résultat qu'elle poursuit, même si elle n'a pas d'effet direct entre particuliers.","portee":"Étend l'obligation d'interprétation conforme (Von Colson, 1984) aux droits antérieurs à la directive.","tags":["interprétation conforme","directive","effet horizontal"],"id":"seed-jp-1990-11-13-marleasing"},{"titre":"Francovich et Bonifaci","juridiction":"CJUE","date":"1991-11-19","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Des salariés italiens victimes de l'insolvabilité de leur employeur n'obtiennent pas la garantie de leurs créances salariales parce que l'Italie n'a pas transposé une directive.","procedure":"Le juge italien saisit la Cour de justice d'une question préjudicielle.","probleme":"Un État est-il responsable envers les particuliers de la violation du droit de l'Union, notamment de la non-transposition d'une directive ?","solution":"Oui : le principe de la responsabilité de l'État pour les dommages causés aux particuliers par les violations du droit communautaire qui lui sont imputables est inhérent au système du traité ; la directive doit conférer des droits identifiables et il doit exister un lien de causalité.","portee":"Fonde la responsabilité de l'État du fait de la violation du droit de l'Union ; précisée par Brasserie du Pêcheur.","tags":["responsabilité de l'État","violation du droit de l'Union","directive"],"id":"seed-jp-1991-11-19-francovich-et-bonifaci"},{"titre":"Keck et Mithouard","juridiction":"CJUE","date":"1993-11-24","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Des commerçants français sont poursuivis pour revente à perte, interdite par le droit français.","procedure":"Le tribunal de grande instance de Strasbourg pose une question préjudicielle.","probleme":"L'interdiction de la revente à perte est-elle une mesure d'effet équivalent ?","solution":"Non : l'application à des produits d'autres États de dispositions nationales limitant ou interdisant certaines modalités de vente n'est pas de nature à entraver le commerce entre États membres, pourvu qu'elles s'appliquent à tous les opérateurs et affectent de la même manière la commercialisation des produits nationaux et ceux des autres États.","portee":"Distingue les règles relatives aux produits (Cassis de Dijon) des modalités de vente (Keck).","tags":["modalités de vente","mesures d'effet équivalent","revente à perte"],"id":"seed-jp-1993-11-24-keck-et-mithouard"},{"titre":"Faccini Dori","juridiction":"CJUE","date":"1994-07-14","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Une consommatrice souhaite invoquer une directive sur les contrats négociés hors établissement contre un professionnel, avec lequel elle avait contracté.","procedure":"Le juge italien pose une question préjudicielle.","probleme":"Une directive peut-elle être invoquée contre un particulier ?","solution":"Non : l'effet direct horizontal d'une directive est exclu ; mais le juge national doit interpréter son droit national à la lumière de la directive, et les particuliers lésés peuvent engager la responsabilité de l'État.","portee":"Confirme Marshall ; les substituts sont l'interprétation conforme et la responsabilité de l'État (Francovich).","tags":["directive","effet horizontal","interprétation conforme"],"id":"seed-jp-1994-07-14-faccini-dori"},{"titre":"Gebhard","juridiction":"CJUE","date":"1995-11-30","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un avocat allemand installé à Milan utilise le titre d'« avvocato » sans être inscrit au barreau italien ; il est sanctionné par l'ordre.","procedure":"Question préjudicielle du Consiglio nazionale forense.","probleme":"Dans quelles conditions une réglementation nationale peut-elle restreindre la liberté d'établissement ?","solution":"Les mesures nationales susceptibles de gêner ou de rendre moins attrayant l'exercice des libertés fondamentales doivent remplir quatre conditions : application non discriminatoire, justification par des raisons impérieuses d'intérêt général, aptitude à garantir l'objectif, et ne pas aller au-delà de ce qui est nécessaire.","portee":"Formule « Gebhard » : test de proportionnalité applicable à toutes les libertés de circulation.","tags":["liberté d'établissement","avocat","mesures nationales"],"id":"seed-jp-1995-11-30-gebhard"},{"titre":"Bosman","juridiction":"CJUE","date":"1995-12-15","matiere":"Droit de l'Union européenne","niveau":"L3-M1","faits":"Un footballeur professionnel belge ne peut pas être transféré à un club français parce que son club d'origine exige une indemnité de transfert que le second club refuse de payer.","procedure":"Question préjudicielle de la cour d'appel de Liège.","probleme":"Les règles des fédérations sportives imposant des indemnités de transfert et limitant le nombre de joueurs étrangers sont-elles conformes à la libre circulation des travailleurs ?","solution":"Non : elles constituent des entraves à la libre circulation des travailleurs (art. 45 TFUE), sans justification suffisante ; l'activité sportive professionnelle est une activité économique.","portee":"Bouleverse le marché des transferts ; applique le droit de l'Union aux règles des organisations privées.","tags":["libre circulation des travailleurs","sport","transfert"],"id":"seed-jp-1995-12-15-bosman"},{"titre":"Brasserie du Pêcheur et Factortame III","juridiction":"CJUE","date":"1996-03-05","matiere":"Droit de l'Union européenne","niveau":"M1","faits":"Un brasseur français et des armateurs de pêche subissent des dommages résultant de lois allemande et britannique contraires au droit communautaire.","procedure":"Les juges allemand et britannique posent des questions préjudicielles.","probleme":"À quelles conditions l'État est-il responsable d'une violation du droit de l'Union imputable au législateur ?","solution":"Trois conditions : la règle violée a pour objet de conférer des droits aux particuliers, la violation est suffisamment caractérisée, il existe un lien de causalité direct ; la responsabilité vaut quel que soit l'organe responsable, y compris le législateur.","portee":"Généralise la responsabilité de l'État ; voir Köbler (2003) pour les juridictions suprêmes.","tags":["responsabilité de l'État","violation suffisamment caractérisée"],"id":"seed-jp-1996-03-05-brasserie-du-pecheur-et-factortame-iii"},{"titre":"Centros","juridiction":"CJUE","date":"1999-03-09","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Deux Danois créent une société au Royaume-Uni (sans activité) pour exercer au Danemark par une succursale, afin d'échapper à l'exigence danoise de capital minimum.","procedure":"Question préjudicielle de la Cour suprême danoise.","probleme":"Un État peut-il refuser d'immatriculer la succursale d'une société constituée ailleurs pour éviter ses règles ?","solution":"Non : le fait de constituer une société dans l'État dont les règles sont les moins contraignantes pour exercer ses activités dans un autre État n'est pas en soi un abus ; le refus d'immatriculation est une entrave injustifiée.","portee":"Ouvre la voie à la concurrence entre droits des sociétés (Überseering, Inspire Art).","tags":["liberté d'établissement","société","abus"],"id":"seed-jp-1999-03-09-centros"},{"titre":"Grzelczyk","juridiction":"CJUE","date":"2001-09-20","matiere":"Droit de l'Union européenne","niveau":"M1","faits":"Un étudiant français en Belgique se voit refuser le minimum de moyens d'existence parce qu'il n'est pas belge.","procedure":"Question préjudicielle du tribunal du travail de Nivelles.","probleme":"Un citoyen de l'Union peut-il invoquer la non-discrimination pour obtenir une prestation sociale dans un autre État membre ?","solution":"Oui : le statut de citoyen de l'Union a vocation à être le statut fondamental des ressortissants des États membres, permettant à ceux qui se trouvent dans la même situation d'obtenir le même traitement juridique.","portee":"Formule célèbre sur le statut de citoyen ; limites introduites ensuite (Dano, 2014).","tags":["citoyenneté de l'Union","égalité de traitement","minimex"],"id":"seed-jp-2001-09-20-grzelczyk"},{"titre":"Courage c. Crehan","juridiction":"CJUE","date":"2001-09-20","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un exploitant de pub, lié à une brasserie par une clause d'approvisionnement exclusif, demande des dommages-intérêts à la brasserie.","procedure":"Question préjudicielle de la Court of Appeal anglaise.","probleme":"Une partie à un contrat contraire à l'article 101 TFUE peut-elle demander la réparation du préjudice causé par ce contrat ?","solution":"Oui : toute personne peut demander réparation du préjudice que lui a causé un contrat ou un comportement susceptible de restreindre ou de fausser la concurrence ; l'effet utile de l'interdiction l'exige.","portee":"Fonde l'action privée en réparation (private enforcement) ; directive 2014/104.","tags":["réparation","concurrence","action privée"],"id":"seed-jp-2001-09-20-courage-c-crehan"},{"titre":"Wouters","juridiction":"CJUE","date":"2002-02-19","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Des avocats néerlandais contestent une règle de l'ordre interdisant les associations pluridisciplinaires avec des experts-comptables.","procedure":"Question préjudicielle du Raad van State.","probleme":"Une règle déontologique d'une profession réglementée peut-elle constituer une entente interdite ?","solution":"L'ordre est une association d'entreprises et la règle, un accord restrictif ; mais elle n'est pas contraire à l'article 101 TFUE lorsqu'elle est nécessaire à la bonne pratique de la profession (indépendance, secret).","portee":"Pose la théorie de l'« ancillary restraint » (nécessité de la restriction pour un objectif légitime).","tags":["concurrence","ordre professionnel","règle déontologique"],"id":"seed-jp-2002-02-19-wouters"},{"titre":"Unión de Pequeños Agricultores (UPA)","juridiction":"CJUE","date":"2002-07-25","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une organisation de petits agriculteurs espagnols conteste un règlement de l'organisation commune du marché de l'huile d'olive, mais ne répond pas aux critères de Plaumann.","procedure":"Pourvoi devant la Cour de justice.","probleme":"Faut-il assouplir l'intérêt à agir des particuliers pour garantir une protection juridictionnelle effective ?","solution":"Non : un système complet de voies de recours existe (recours préjudiciel et recours devant les juridictions nationales) ; il appartient aux États membres de réformer le traité, non à la Cour d'élargir l'article 230.","portee":"Confirme Plaumann ; la réforme intervient avec le traité de Lisbonne (art. 263, al. 4).","tags":["recours en annulation","protection juridictionnelle","Plaumann"],"id":"seed-jp-2002-07-25-union-de-pequenos-agricultores-upa"},{"titre":"Köbler","juridiction":"CJUE","date":"2003-09-30","matiere":"Droit de l'Union européenne","niveau":"M1-M2","faits":"Un professeur autrichien se voit refuser une prime d'ancienneté par une décision du Verwaltungsgerichtshof, rendue en méconnaissance du droit communautaire.","procedure":"Le tribunal régional de Vienne pose une question préjudicielle.","probleme":"L'État peut-il être responsable pour une décision d'une juridiction suprême contraire au droit de l'Union ?","solution":"Oui : le principe selon lequel les États sont tenus de réparer les dommages causés aux particuliers par des violations du droit communautaire vaut aussi lorsque la violation découle d'une décision d'une juridiction statuant en dernier ressort, si la violation est manifeste.","portee":"Consacre la responsabilité de l'État du fait des juridictions suprêmes ; complétée par Commission c. Italie (2011) et Traghetti (2006).","tags":["responsabilité de l'État","juge suprême","violation manifeste"],"id":"seed-jp-2003-09-30-kobler"},{"titre":"Pupino","juridiction":"CJUE","date":"2005-06-16","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une institutrice italienne, poursuivie pour mauvais traitements sur des enfants, s'oppose à l'audition anticipée de mineurs comme témoins, prévue par une décision-cadre de l'Union.","procedure":"Question préjudicielle du juge des investigations préliminaires de Florence.","probleme":"L'obligation d'interprétation conforme s'étend-elle aux décisions-cadres de l'ancien troisième pilier ?","solution":"Oui : le juge national doit interpréter le droit national, autant que possible, à la lumière de la décision-cadre ; mais cette obligation est limitée par les principes généraux, notamment la légalité pénale et la non-rétroactivité.","portee":"Étend l'interprétation conforme à la coopération policière et judiciaire pénale.","tags":["interprétation conforme","décision-cadre","coopération pénale"],"id":"seed-jp-2005-06-16-pupino"},{"titre":"Mangold","juridiction":"CJUE","date":"2005-11-22","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un salarié de 56 ans est engagé en CDD, une loi allemande autorisant sans motif les CDD pour les travailleurs âgés de plus de 52 ans.","procedure":"Question préjudicielle du tribunal du travail de Munich.","probleme":"Le principe de non-discrimination en raison de l'âge est-il un principe général du droit de l'Union opposable avant l'expiration du délai de transposition ?","solution":"Oui : le principe de non-discrimination en fonction de l'âge est un principe général du droit communautaire ; le juge national doit laisser inappliquée toute disposition nationale contraire.","portee":"Admet l'effet des principes généraux entre particuliers ; suivi par Kücükdeveci (2010).","tags":["principes généraux","non-discrimination","âge"],"id":"seed-jp-2005-11-22-mangold"},{"titre":"International Transport Workers' Federation (Viking Line)","juridiction":"CJUE","date":"2007-12-11","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une compagnie de ferries finlandaise veut immatriculer un navire en Estonie pour réduire les coûts salariaux ; des syndicats annoncent une grève et menacent d'actions.","procedure":"Question préjudicielle de la Court of Appeal anglaise.","probleme":"Les actions collectives syndicales peuvent-elles entraver la liberté d'établissement ?","solution":"Oui, elles peuvent constituer une restriction à la liberté d'établissement, directement opposable aux syndicats ; l'action peut être justifiée par la protection des travailleurs si elle est proportionnée, ce qu'il revient au juge national d'apprécier.","portee":"Applique les libertés économiques à des acteurs privés (syndicats) ; critiquée comme une subordination du droit de grève.","tags":["action collective","liberté d'établissement","droit de grève"],"id":"seed-jp-2007-12-11-international-transport-workers-federati"},{"titre":"Laval un Partneri","juridiction":"CJUE","date":"2007-12-18","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une entreprise lettone détache des travailleurs en Suède ; des syndicats suédois bloquent son chantier pour obtenir la conclusion d'une convention collective.","procedure":"Question préjudicielle du tribunal du travail suédois.","probleme":"Une action collective syndicale peut-elle contraindre une entreprise étrangère à appliquer une convention collective du pays d'accueil ?","solution":"Le droit de mener une action collective est un droit fondamental, mais il peut être restreint par la libre prestation de services ; le blocage visant à imposer des conditions allant au-delà du noyau dur de la directive sur le détachement est une entrave injustifiée.","portee":"Précise l'équilibre entre droits sociaux fondamentaux et libertés économiques (v. aussi Viking, 2007) ; débat sur la révision de la directive sur le détachement.","tags":["détachement de travailleurs","grève","libre prestation de services"],"id":"seed-jp-2007-12-18-laval-un-partneri"},{"titre":"Kadi I","juridiction":"CJUE","date":"2008-09-03","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un résident saoudien figure sur une liste de personnes dont les avoirs sont gelés en application d'une résolution du Conseil de sécurité, sans avoir pu se défendre.","procedure":"Pourvoi devant la Cour de justice contre un arrêt du Tribunal.","probleme":"Un acte de l'Union transposant une résolution du Conseil de sécurité peut-il échapper au contrôle de la Cour au regard des droits fondamentaux ?","solution":"Non : le contrôle de la légalité de tous les actes de l'Union au regard des droits fondamentaux est l'expression d'une garantie constitutionnelle qui ne peut être écartée par un accord international ; le règlement est annulé pour violation des droits de la défense.","portee":"Affirme l'autonomie de l'ordre juridique de l'Union face à l'ordre onusien.","tags":["droits fondamentaux","Nations unies","sanctions ciblées"],"id":"seed-jp-2008-09-03-kadi-i"},{"titre":"Kücükdeveci","juridiction":"CJUE","date":"2010-01-19","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une salariée allemande licenciée voit ses années de service avant l'âge de 25 ans exclues du calcul du préavis, par une loi allemande contestée comme discriminatoire.","procedure":"Question préjudicielle d'un tribunal du travail de Düsseldorf.","probleme":"Le principe de non-discrimination en raison de l'âge peut-il être invoqué dans un litige entre particuliers pour écarter une loi nationale ?","solution":"Oui : l'interdiction de discrimination en raison de l'âge est un principe général du droit de l'Union, concrétisé par la directive 2000/78 ; le juge national doit laisser inappliquée une loi contraire, dans un litige entre particuliers.","portee":"Confirme Mangold ; permet un effet horizontal indirect à travers les principes généraux.","tags":["principe de non-discrimination","âge","effet horizontal"],"id":"seed-jp-2010-01-19-kucukdeveci"},{"titre":"Test-Achats","juridiction":"CJUE","date":"2011-03-01","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une association belge de consommateurs conteste une dérogation permettant de tenir compte du sexe dans le calcul des primes et prestations d'assurance.","procedure":"Question préjudicielle de la Cour constitutionnelle belge.","probleme":"La dérogation permanente à l'égalité de traitement entre les femmes et les hommes pour les primes d'assurance est-elle valide ?","solution":"Non : la disposition de la directive est invalide à compter du 21 décembre 2012 ; elle est contraire aux articles 21 et 23 de la Charte.","portee":"Illustre le contrôle de validité d'une directive au regard de la Charte.","tags":["discrimination","sexe","assurance","Charte"],"id":"seed-jp-2011-03-01-test-achats"},{"titre":"Ruiz Zambrano","juridiction":"CJUE","date":"2011-03-08","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un ressortissant colombien, père de deux enfants de nationalité belge, se voit refuser un titre de séjour et un permis de travail en Belgique.","procedure":"Question préjudicielle du tribunal du travail de Bruxelles.","probleme":"Un ressortissant d'un pays tiers, père d'enfants citoyens de l'Union, peut-il tirer un droit de séjour de la citoyenneté de ses enfants ?","solution":"Oui : l'article 20 TFUE s'oppose à des mesures nationales qui ont pour effet de priver les citoyens de l'Union de la jouissance effective de l'essentiel des droits conférés par leur statut ; le parent doit pouvoir séjourner et travailler.","portee":"Source de la jurisprudence sur la substance des droits attachés à la citoyenneté ; limitée par McCarthy et Dereci (2011).","tags":["citoyenneté","droit au séjour","effet utile"],"id":"seed-jp-2011-03-08-ruiz-zambrano"},{"titre":"Pierre Fabre Dermo-Cosmétique","juridiction":"CJUE","date":"2011-10-13","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un fabricant de produits dermo-cosmétiques interdit à ses distributeurs la vente en ligne, en exigeant la présence d'un diplômé en pharmacie.","procedure":"Question préjudicielle de la cour d'appel de Paris.","probleme":"Une interdiction générale et absolue de vente sur internet dans un contrat de distribution sélective est-elle une restriction par objet ?","solution":"Oui : l'interdiction de fait de toute vente en ligne constitue une restriction par objet, sauf justification objective (qui n'est pas établie pour des produits non médicamenteux) ; elle ne peut bénéficier de l'exemption par catégorie.","portee":"Fondement de la jurisprudence sur la vente en ligne ; confirmée par Coty Germany (2017) pour les marketplaces de luxe.","tags":["distribution sélective","vente en ligne","restriction par objet"],"id":"seed-jp-2011-10-13-pierre-fabre-dermo-cosmetique"},{"titre":"Pringle","juridiction":"CJUE","date":"2012-11-27","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un parlementaire irlandais conteste la décision modifiant l'article 136 TFUE et le traité instituant le mécanisme européen de stabilité (MES).","procedure":"Question préjudicielle de la Cour suprême d'Irlande.","probleme":"Le traité MES est-il compatible avec les traités et le principe de non-renflouement ?","solution":"Oui : la décision de révision simplifiée est valide, et le MES n'empiète pas sur la politique monétaire ni ne viole la clause de non-renflouement (art. 125 TFUE), car l'aide est strictement conditionnée à des programmes d'ajustement.","portee":"Valide l'architecture de gestion de crise ; la Cour confirme sa compétence sur les accords entre États membres.","tags":["mécanisme européen de stabilité","crise de la dette","traité"],"id":"seed-jp-2012-11-27-pringle"},{"titre":"Åkerberg Fransson","juridiction":"CJUE","date":"2013-02-26","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un pêcheur suédois est poursuivi pénalement pour fraude fiscale alors qu'il a déjà subi une sanction fiscale pour les mêmes faits.","procedure":"Question préjudicielle du tribunal de Haparanda.","probleme":"La Charte des droits fondamentaux s'applique-t-elle à une procédure nationale en matière de fraude fiscale impliquant la TVA ?","solution":"Oui : les droits fondamentaux garantis par la Charte doivent être respectés lorsqu'une réglementation nationale entre dans le champ d'application du droit de l'Union (« mise en oeuvre »).","portee":"Large interprétation de l'article 51 de la Charte ; le Conseil constitutionnel et le Conseil d'État la prennent en compte.","tags":["Charte","champ d'application","non bis in idem"],"id":"seed-jp-2013-02-26-akerberg-fransson"},{"titre":"Melloni","juridiction":"CJUE","date":"2013-02-26","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un condamné par défaut en Italie, arrêté en Espagne, s'oppose à sa remise en invoquant la protection des droits de la défense plus élevée de la Constitution espagnole.","procedure":"Question préjudicielle du Tribunal constitutionnel espagnol.","probleme":"Un État peut-il subordonner l'exécution d'un mandat d'arrêt européen à une garantie issue de sa Constitution, plus protectrice que le droit de l'Union ?","solution":"Non : l'application de standards nationaux plus élevés ne doit pas compromettre le niveau de protection de la Charte ni la primauté, l'unité et l'effectivité du droit de l'Union.","portee":"Affirme que l'article 53 de la Charte ne permet pas d'invoquer une protection nationale plus forte contre un acte d'harmonisation complète.","tags":["primauté","niveau de protection","mandat d'arrêt européen"],"id":"seed-jp-2013-02-26-melloni"},{"titre":"Digital Rights Ireland","juridiction":"CJUE","date":"2014-04-08","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Des associations contestent la directive sur la conservation de données de trafic et de localisation des communications électroniques.","procedure":"Questions préjudicielles de juridictions irlandaise et autrichienne.","probleme":"La directive 2006/24 sur la conservation généralisée des données est-elle valide au regard de la Charte ?","solution":"Non : la directive est invalide : elle comporte une ingérence d'une vaste ampleur et d'une gravité particulière dans les droits fondamentaux au respect de la vie privée et à la protection des données, sans limites suffisantes.","portee":"Premier arrêt invalidant une directive pour violation de la Charte ; il fonde la jurisprudence sur la conservation des données (Tele2, La Quadrature du Net).","tags":["données personnelles","conservation","proportionnalité"],"id":"seed-jp-2014-04-08-digital-rights-ireland"},{"titre":"Google Spain","juridiction":"CJUE","date":"2014-05-13","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un Espagnol demande à un moteur de recherche de supprimer des liens vers des annonces anciennes de vente aux enchères de sa maison saisie.","procedure":"Question préjudicielle de l'Audiencia Nacional espagnole.","probleme":"Un moteur de recherche est-il responsable du traitement de données personnelles et doit-il déréférencer des liens à la demande de la personne ?","solution":"Oui : l'exploitant d'un moteur de recherche est responsable du traitement ; il doit, à la demande de la personne concernée et sous conditions (données inadéquates, non pertinentes ou excessives), supprimer les liens des résultats associés à son nom, en pesant l'intérêt du public à l'information.","portee":"Consacre le droit au déréférencement, codifié à l'article 17 du RGPD (droit à l'effacement).","tags":["droit à l'oubli","déréférencement","données personnelles"],"id":"seed-jp-2014-05-13-google-spain"},{"titre":"Dano","juridiction":"CJUE","date":"2014-11-11","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une ressortissante roumaine, sans emploi, installée en Allemagne avec son fils, demande des prestations sociales de base.","procedure":"Question préjudicielle du tribunal social de Leipzig.","probleme":"Un citoyen de l'Union économiquement inactif peut-il réclamer, dans l'État d'accueil, une prestation sociale sur le fondement de l'égalité de traitement ?","solution":"Non : un citoyen de l'Union ne peut réclamer l'égalité de traitement que s'il remplit les conditions de séjour de la directive 2004/38, en particulier disposer de ressources suffisantes ; un État peut refuser des prestations à un citoyen qui n'a pas de droit de séjour.","portee":"Relativise Grzelczyk (2001) : l'accès aux prestations dépend du droit de séjour.","tags":["citoyenneté","prestations sociales","tourisme social"],"id":"seed-jp-2014-11-11-dano"},{"titre":"Avis 2/13","juridiction":"CJUE","date":"2014-12-18","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Le projet d'accord d'adhésion de l'Union à la Convention européenne des droits de l'homme est soumis à la Cour pour avis.","procedure":"Demande d'avis de la Commission sur la compatibilité du projet avec les traités.","probleme":"Le projet d'adhésion est-il compatible avec les traités et l'autonomie du droit de l'Union ?","solution":"Non : le projet porte atteinte aux caractéristiques spécifiques et à l'autonomie du droit de l'Union (rapports avec le protocole n° 16, mécanisme de coresponsabilité, contrôle de la PESC, etc.).","portee":"Bloque l'adhésion de l'Union à la CEDH ; dialogue entre les deux Cours.","tags":["adhésion à la CEDH","autonomie","avis"],"id":"seed-jp-2014-12-18-avis-2-13"},{"titre":"Schrems I","juridiction":"CJUE","date":"2015-10-06","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Un utilisateur autrichien de Facebook se plaint du transfert de ses données vers les États-Unis, où elles sont exposées à la surveillance de masse.","procedure":"Question préjudicielle de la Haute Cour d'Irlande.","probleme":"Une décision de la Commission constatant le caractère adéquat de la protection américaine lie-t-elle les autorités de contrôle, et est-elle valide ?","solution":"Les autorités nationales de contrôle peuvent examiner une plainte malgré la décision de la Commission ; mais seule la Cour peut invalider la décision : celle-ci est invalide car les États-Unis n'assurent pas un niveau de protection essentiellement équivalent.","portee":"Invalide le régime « Safe Harbor » ; suivi de Schrems II (16 juillet 2020) qui invalide le « Privacy Shield ».","tags":["données personnelles","transferts","Safe Harbor"],"id":"seed-jp-2015-10-06-schrems-i"},{"titre":"Tele2 Sverige et Watson","juridiction":"CJUE","date":"2016-12-21","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Des opérateurs suédois et des citoyens britanniques contestent des législations nationales imposant une conservation généralisée des données de connexion.","procedure":"Questions préjudicielles d'une cour suédoise et de la Court of Appeal.","probleme":"Une conservation généralisée et indifférenciée des données de trafic est-elle compatible avec la directive vie privée et la Charte ?","solution":"Non : la législation qui prévoit une conservation généralisée et indifférenciée de toutes les données de trafic et de localisation excède les limites du strict nécessaire ; seule une conservation ciblée, pour lutter contre la criminalité grave, est admise.","portee":"Prolonge Digital Rights Ireland ; repris par La Quadrature du Net (6 octobre 2020), et le Conseil d'État, French Data Network (21 avril 2021).","tags":["données personnelles","conservation générale","sécurité nationale"],"id":"seed-jp-2016-12-21-tele2-sverige-et-watson"},{"titre":"Achbita","juridiction":"CJUE","date":"2017-03-14","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Une réceptionniste belge est licenciée parce qu'elle refuse d'ôter son foulard islamique, alors que le règlement de l'entreprise interdit les signes religieux visibles.","procedure":"Question préjudicielle de la Cour de cassation belge.","probleme":"L'interdiction du foulard islamique, découlant d'une règle générale de neutralité, est-elle une discrimination directe ?","solution":"Non, si la règle interne interdit tout signe politique, philosophique ou religieux et s'applique indifféremment ; elle peut être justifiée par la politique de neutralité de l'employeur à l'égard des clients, si elle est appliquée de manière cohérente et systématique, et proportionnée.","portee":"Reprise en France par Cass. soc., 22 nov. 2017 (Micropole) et le Code du travail (art. L. 1321-2-1).","tags":["neutralité","foulard","discrimination religieuse","entreprise"],"id":"seed-jp-2017-03-14-achbita"},{"titre":"Schrems II (Facebook Ireland et Schrems)","juridiction":"CJUE","date":"2020-07-16","matiere":"Droit de l'Union européenne","niveau":"M2","faits":"Le même requérant conteste le transfert de ses données vers les États-Unis, après l'invalidation de Safe Harbor, sur la base des clauses contractuelles types.","procedure":"Question préjudicielle de la Haute Cour d'Irlande.","probleme":"Le « bouclier de protection des données » et les clauses contractuelles types assurent-ils un niveau de protection adéquat ?","solution":"Le Privacy Shield est invalide : les programmes de surveillance américains ne sont pas limités au strict nécessaire et les recours sont insuffisants ; les clauses types restent valables, mais l'exportateur doit vérifier le niveau de protection effectif dans le pays tiers.","portee":"Oblige les entreprises à des évaluations de transfert ; un nouveau cadre (Data Privacy Framework) est adopté en 2023.","tags":["données personnelles","transferts","Privacy Shield","clauses types"],"id":"seed-jp-2020-07-16-schrems-ii-facebook-ireland-et-schrems"},{"titre":"Minit France (1re civ.)","juridiction":"Cour de cassation","date":"1991-05-14","matiere":"Droit de la consommation","niveau":"L3","faits":"Un non-professionnel soutient qu'une clause d'un contrat d'adhésion, imposée par un professionnel, est abusive, alors qu'aucun décret n'en a encore prohibé l'usage.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Le juge peut-il déclarer une clause abusive en l'absence de décret la prohibant ?","solution":"Oui : le juge peut écarter une clause abusive sur le fondement de l'ancien article 35 de la loi du 10 janvier 1978, même sans décret d'application, en appréciant le déséquilibre créé au détriment du non-professionnel ou consommateur.","portee":"Consacre le pouvoir direct du juge en matière de clauses abusives ; la jurisprudence devient celle de l'article L. 212-1 du Code de la consommation.","tags":["clauses abusives","pouvoir du juge","législation sur les clauses abusives"],"id":"seed-jp-1991-05-14-minit-france-1re-civ"},{"titre":"Océano Grupo Editorial (CJCE)","juridiction":"CJUE","date":"2000-06-27","matiere":"Droit de la consommation","niveau":"M1","faits":"Des acheteurs d'une encyclopédie vendue à tempérament sont attaqués devant le tribunal de Barcelone en vertu d'une clause attributive de juridiction figurant dans les contrats-types du vendeur.","procedure":"Question préjudicielle du juzgado de primera instancia de Barcelone.","probleme":"Le juge peut-il relever d'office le caractère abusif d'une clause, sans que le consommateur l'invoque ?","solution":"Oui : la protection voulue par la directive 93/13 implique que le juge national puisse apprécier d'office le caractère abusif d'une clause qui relève de son champ d'application, car le consommateur est dans une situation d'infériorité.","portee":"Origine de l'office du juge en droit des clauses abusives ; étendu par Mostaza Claro (2006), Pannon (2009) et Banco Español de Crédito (2012).","tags":["clauses abusives","office du juge","clause attributive de juridiction"],"id":"seed-jp-2000-06-27-oceano-grupo-editorial-cjce"},{"titre":"Canavese — parasitisme (Com.)","juridiction":"Cour de cassation","date":"1999-01-26","matiere":"Droit des affaires","niveau":"L3-M1","faits":"Des sociétés qui commercialisent des bananes prêtes pour la mise en rayon dans des bacs en plastique reprochent à un concurrent d'avoir copié leur méthode de conditionnement.","procedure":"Pourvoi devant la chambre commerciale de la Cour de cassation.","probleme":"Qu'est-ce que le parasitisme économique, et peut-il être sanctionné ?","solution":"Le parasitisme est l'ensemble des comportements par lesquels un agent économique s'immisce dans le sillage d'un autre, afin de tirer profit, sans rien dépenser, de ses efforts et de son savoir-faire ; il est sanctionné sur le fondement de la responsabilité délictuelle (art. 1240 du Code civil).","portee":"Définition de référence du parasitisme ; elle protège des valeurs économiques non couvertes par un droit privatif.","tags":["parasitisme","concurrence déloyale","responsabilité délictuelle"],"id":"seed-jp-1999-01-26-canavese-parasitisme-com"},{"titre":"Société créée de fait entre concubins (Com.)","juridiction":"Cour de cassation","date":"2004-06-23","matiere":"Droit des affaires","niveau":"L2-L3","faits":"À la fin de leur concubinage, l'un des concubins invoque l'existence d'une société créée de fait avec l'autre, pour obtenir sa part dans les biens acquis ensemble.","procedure":"Pourvoi devant la chambre commerciale de la Cour de cassation.","probleme":"La vie commune et la collaboration à l'activité d'un partenaire suffisent-elles à caractériser une société créée de fait ?","solution":"Non : l'existence d'une société créée de fait suppose la réunion des éléments du contrat de société : des apports, la participation aux bénéfices et aux pertes, et l'affectio societatis, la volonté de collaborer ensemble sur un pied d'égalité à une oeuvre commune ; ces éléments doivent être établis séparément.","portee":"Jurisprudence constante sur les concubins ; la seule vie commune n'établit pas la volonté de s'associer.","tags":["société créée de fait","affectio societatis","concubinage"],"id":"seed-jp-2004-06-23-societe-creee-de-fait-entre-concubins-co"},{"titre":"Empiètement et démolition (3e civ.)","juridiction":"Cour de cassation","date":"1990-06-07","matiere":"Droit des biens","niveau":"L2","faits":"Un propriétaire constate qu'une canalisation d'eaux usées construite par son voisin empiète sur son fonds et en demande la suppression.","procedure":"Pourvoi devant la troisième chambre civile de la Cour de cassation contre un arrêt qui refusait la démolition, en raison de la faible importance de l'empiétement.","probleme":"Le propriétaire dont le fonds est envahi peut-il toujours obtenir la démolition de l'ouvrage, même si l'empiétement est minime ?","solution":"Oui : la défense du droit de propriété contre un empiétement ne saurait dégénérer en abus ; le propriétaire peut obtenir la suppression de l'ouvrage, sans que le juge apprécie la gravité de l'atteinte.","portee":"Confirmée par Cass. 3e civ., 10 novembre 2016 et 21 décembre 2017 : la démolition n'est pas soumise à un contrôle de proportionnalité.","tags":["propriété","empiètement","abus de droit"],"id":"seed-jp-1990-06-07-empietement-et-demolition-3e-civ"},{"titre":"Hôtel de Girancourt (Ass. plén.)","juridiction":"Cour de cassation","date":"2004-05-07","matiere":"Droit des biens","niveau":"L1-L2","faits":"Une photographie de la façade d'un hôtel particulier classé monument historique est reproduite dans des dépliants publicitaires pour une résidence, sans l'autorisation des propriétaires.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation.","probleme":"Le propriétaire peut-il s'opposer à la reproduction de l'image de son bien ?","solution":"Non, sauf à démontrer un trouble anormal : le propriétaire d'une chose ne dispose pas d'un droit exclusif sur l'image de celle-ci ; il peut seulement s'opposer à son utilisation par un tiers si elle lui cause un trouble anormal.","portee":"Revirement par rapport à Cass. 1re civ., 10 mars 1999 (Café Gondrée), qui avait reconnu au propriétaire un droit de jouissance sur l'image de son bien.","tags":["droit de propriété","image des biens","trouble"],"id":"seed-jp-2004-05-07-hotel-de-girancourt-ass-plen"},{"titre":"Empiètement — démolition de plein droit (3e civ.)","juridiction":"Cour de cassation","date":"2017-12-21","matiere":"Droit des biens","niveau":"L3-M1","faits":"Un propriétaire demande la démolition d'un ouvrage empiétant sur son fonds ; les juges du fond refusent en raison de la disproportion entre le trouble et la sanction.","procedure":"Pourvoi devant la troisième chambre civile de la Cour de cassation.","probleme":"Le juge peut-il refuser de condamner à la démolition d'un empiétement au nom de la proportionnalité ?","solution":"Non : tout propriétaire est en droit d'obtenir la démolition d'un ouvrage empiétant sur son fonds, sans que son action puisse donner lieu à faute ou à abus ; la sanction de l'empiétement n'est pas soumise à un contrôle de proportionnalité.","portee":"Position constante, régulièrement critiquée par la doctrine au nom du principe de proportionnalité (art. 1er du Protocole n° 1).","tags":["propriété","empiètement","proportionnalité"],"id":"seed-jp-2017-12-21-empietement-demolition-de-plein-droit-3e"},{"titre":"Canal de Craponne (Civ.)","juridiction":"Cour de cassation","date":"1876-03-06","matiere":"Droit des contrats","niveau":"L2","faits":"Des contrats du XVIe siècle fixent un prix très faible pour l'eau d'un canal d'irrigation ; au XIXe siècle, l'entretien du canal coûte beaucoup plus cher que les redevances.","procedure":"L'exploitant demande au juge de réviser le prix ; la cour d'appel accepte ; pourvoi devant la chambre civile.","probleme":"Le juge peut-il modifier un contrat dont l'équilibre a été bouleversé par un changement de circonstances ?","solution":"Non : dans aucun cas, il n'appartient aux tribunaux, quelque équitable que puisse leur paraître leur décision, de prendre en considération le temps et les circonstances pour modifier les conventions des parties et substituer des clauses nouvelles à celles qui ont été librement acceptées.","portee":"Refus de l'imprévision en droit privé ; depuis l'ordonnance du 10 février 2016, l'article 1195 du Code civil permet la renégociation puis la révision judiciaire.","tags":["imprévision","force obligatoire","contrat"],"id":"seed-jp-1876-03-06-canal-de-craponne-civ"},{"titre":"Compagnie générale transatlantique (Civ.)","juridiction":"Cour de cassation","date":"1911-11-21","matiere":"Droit des contrats","niveau":"L2","faits":"Un passager d'un navire est blessé durant le voyage ; il agit contre le transporteur sur le terrain contractuel.","procedure":"Pourvoi devant la chambre civile de la Cour de cassation.","probleme":"Le contrat de transport met-il à la charge du transporteur une obligation de sécurité ?","solution":"Oui : l'exécution du contrat de transport comporte l'obligation de conduire le voyageur sain et sauf à destination ; c'est une obligation de sécurité de résultat.","portee":"Fonde l'obligation de sécurité contractuelle, généralisée à d'autres contrats ; elle justifie l'action de la victime sur le fondement contractuel.","tags":["obligation de sécurité","transport","responsabilité contractuelle"],"id":"seed-jp-1911-11-21-compagnie-generale-transatlantique-civ"},{"titre":"Poussin (1re civ.)","juridiction":"Cour de cassation","date":"1978-02-22","matiere":"Droit des contrats","niveau":"L1-L2","faits":"Des vendeurs cèdent un tableau attribué à l'école des Carrache ; il s'avère être un Poussin authentique, de bien plus grande valeur.","procedure":"Les vendeurs agissent en nullité de la vente pour erreur sur la substance ; pourvoi devant la première chambre civile.","probleme":"L'erreur du vendeur sur l'authenticité de l'oeuvre qu'il vend est-elle une erreur sur la substance ?","solution":"Oui : l'erreur sur la substance s'apprécie par rapport aux qualités substantielles en considération desquelles les parties ont contracté ; l'authenticité de l'oeuvre en fait partie, même si l'erreur est à l'avantage de l'acquéreur ; la vente est annulée.","portee":"Consacre une conception subjective de la substance et reconnaît l'erreur du vendeur ; applicable à l'article 1132 actuel (erreur sur les qualités essentielles).","tags":["erreur sur la substance","authenticité","vices du consentement"],"id":"seed-jp-1978-02-22-poussin-1re-civ"},{"titre":"Lamborghini (1re civ.)","juridiction":"Cour de cassation","date":"1979-10-09","matiere":"Droit des contrats","niveau":"L3","faits":"Un acquéreur subit un vice de fabrication ; il agit directement contre le fabricant, avec lequel il n'a pas contracté.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Quelle est la nature de l'action de l'acquéreur contre le fabricant dans une chaîne translative de propriété ?","solution":"Contractuelle : l'action du sous-acquéreur contre le fabricant est nécessairement de nature contractuelle, car la garantie des vices constitue un accessoire de la chose qui se transmet avec elle.","portee":"Fait de l'action directe une action contractuelle ; l'assemblée plénière en précise le domaine dans l'arrêt Besse (1991).","tags":["chaîne de contrats","action directe","nature contractuelle"],"id":"seed-jp-1979-10-09-lamborghini-1re-civ"},{"titre":"Besse (Ass. plén.)","juridiction":"Cour de cassation","date":"1991-07-12","matiere":"Droit des contrats","niveau":"L3","faits":"Un maître de l'ouvrage constate des désordres affectant les travaux de plomberie confiés à un sous-traitant ; il l'assigne en réparation plus de dix ans après la réception.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation.","probleme":"Dans une chaîne de contrats non translative de propriété, comme la sous-traitance, la responsabilité du sous-traitant envers le maître de l'ouvrage est-elle contractuelle ou délictuelle ?","solution":"Délictuelle : le sous-traitant n'est pas contractuellement lié au maître de l'ouvrage ; l'action de ce dernier contre lui est de nature délictuelle (violation de l'article 1165 par la cour d'appel, qui avait appliqué la forclusion décennale).","portee":"Limite l'action directe contractuelle aux chaînes translatives de propriété ; la sous-traitance reste en dehors.","tags":["chaîne de contrats","sous-traitance","nature délictuelle"],"id":"seed-jp-1991-07-12-besse-ass-plen"},{"titre":"Huard (Com.)","juridiction":"Cour de cassation","date":"1992-11-03","matiere":"Droit des contrats","niveau":"L2-L3","faits":"Un distributeur de carburant, lié à un fournisseur, ne peut plus soutenir la concurrence, le fournisseur lui imposant des prix supérieurs à ceux pratiqués par d'autres.","procedure":"Le distributeur agit contre son fournisseur en réparation ; pourvoi devant la chambre commerciale.","probleme":"Le fournisseur doit-il maintenir l'équilibre du contrat en adaptant ses prix, au nom de la bonne foi ?","solution":"Oui : le fournisseur, tenu d'exécuter le contrat de bonne foi, a manqué à son obligation de permettre au distributeur de pratiquer des prix concurrentiels ; sa responsabilité contractuelle est engagée.","portee":"Application de la bonne foi (ancien art. 1134, al. 3) à l'exécution du contrat ; première pierre vers une obligation de renégociation.","tags":["bonne foi","exécution","renégociation"],"id":"seed-jp-1992-11-03-huard-com"},{"titre":"Consorts Cruz (3e civ.)","juridiction":"Cour de cassation","date":"1993-12-15","matiere":"Droit des contrats","niveau":"L2-L3","faits":"Un promettant vend à un tiers l'immeuble objet d'une promesse unilatérale avant la levée de l'option par le bénéficiaire.","procedure":"Le bénéficiaire demande l'exécution forcée de la vente ; pourvoi devant la troisième chambre civile.","probleme":"La rétractation du promettant avant la levée de l'option empêche-t-elle la formation de la vente ?","solution":"Oui : tant que les bénéficiaires n'ont pas déclaré acquérir, le promettant n'a pas consenti à la vente ; la rétractation exclut l'exécution forcée, qui n'est pas possible, et n'ouvre droit qu'à des dommages-intérêts.","portee":"Position abandonnée par l'ordonnance de 2016 : l'article 1124 du Code civil prive d'effet la révocation avant l'option et permet la vente forcée.","tags":["promesse unilatérale de vente","rétractation","exécution forcée"],"id":"seed-jp-1993-12-15-consorts-cruz-3e-civ"},{"titre":"Point Club Vidéo (1re civ.)","juridiction":"Cour de cassation","date":"1996-07-03","matiere":"Droit des contrats","niveau":"L2-L3","faits":"Des époux concluent avec une société un contrat de création d'un « point club vidéo » et de location de cassettes ; la commune où ils exploitent est si peu peuplée que l'objectif d'exploitation ne pourra jamais être atteint ; ils demandent l'annulation du contrat.","procedure":"La cour d'appel de Grenoble annule le contrat pour défaut de cause ; la société loueuse se pourvoit, soutenant que la cour a confondu cause et motif.","probleme":"Un contrat dont l'exécution, selon l'économie voulue par les parties, est impossible, est-il valable, ou son obligation est-elle sans contrepartie réelle ?","solution":"Non : le pourvoi est rejeté ; la cour d'appel a pu retenir que le contrat était dépourvu de cause, dès lors que son exécution selon l'économie voulue par les parties était impossible, ce qui révélait l'absence de contrepartie réelle à l'obligation du preneur.","portee":"Illustre le contrôle de la cause ; depuis 2016, la cause est remplacée par le contenu licite et certain (art. 1128) et le contrôle de la contrepartie illusoire (art. 1169).","tags":["cause","contrepartie","nullité"],"id":"seed-jp-1996-07-03-point-club-video-1re-civ"},{"titre":"Chronopost (Com.)","juridiction":"Cour de cassation","date":"1996-10-22","matiere":"Droit des contrats","niveau":"L3","faits":"Une société confie un pli à un transporteur express qui promet la livraison avant midi le lendemain ; le pli arrive trop tard, et le contrat limite l'indemnité au prix du transport.","procedure":"L'expéditeur agit en responsabilité ; pourvoi devant la chambre commerciale.","probleme":"Une clause limitative de responsabilité est-elle valable lorsqu'elle contredit l'obligation essentielle du contrat ?","solution":"Non : en contredisant la portée de l'engagement essentiel (délai de livraison), la clause limitative est réputée non écrite.","portee":"Fondement de la jurisprudence sur les clauses contredisant l'obligation essentielle ; ensuite l'arrêt Faurecia II (2010) la précise et l'article 1170 (2016) la consacre.","tags":["clause limitative de responsabilité","obligation essentielle"],"id":"seed-jp-1996-10-22-chronopost-com"},{"titre":"Résolution unilatérale — Tocqueville (1re civ.)","juridiction":"Cour de cassation","date":"1998-10-13","matiere":"Droit des contrats","niveau":"L3","faits":"Une clinique met fin au contrat qui assurait à un médecin anesthésiste l'exclusivité des actes de sa spécialité, en raison de son comportement professionnel, avec un préavis de six mois ; le médecin réclame des dommages-intérêts pour rupture abusive.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Une partie peut-elle rompre unilatéralement un contrat pour inexécution grave, sans saisir le juge ?","solution":"Oui : la gravité du comportement d'une partie à un contrat peut justifier que l'autre partie y mette fin de façon unilatérale, à ses risques et périls.","portee":"Fonde la résolution unilatérale, consacrée par l'article 1226 du Code civil (mise en demeure préalable, notification).","tags":["résolution unilatérale","gravité du comportement","contrat"],"id":"seed-jp-1998-10-13-resolution-unilaterale-tocqueville-1re-c"},{"titre":"Baldus (1re civ.)","juridiction":"Cour de cassation","date":"2000-05-03","matiere":"Droit des contrats","niveau":"L2","faits":"Un acquéreur achète à très bas prix des photographies d'un artiste célèbre, sans informer les vendeurs de leur valeur réelle.","procedure":"Les vendeurs agissent en nullité pour dol par réticence ; pourvoi devant la première chambre civile.","probleme":"L'acquéreur est-il tenu d'informer le vendeur de la valeur réelle du bien ?","solution":"Non : aucune obligation d'information ne pèse sur l'acquéreur quant au prix, car ce n'est pas un élément intrinsèque du bien ; il n'y a pas de dol par réticence.","portee":"Écarte le devoir d'information sur la valeur ; l'article 1137, alinéa 2 (2016) précise que l'estimation de la valeur de la prestation n'est pas un dol.","tags":["dol","réticence dolosive","obligation d'information"],"id":"seed-jp-2000-05-03-baldus-1re-civ"},{"titre":"Pacte de préférence (ch. mixte)","juridiction":"Cour de cassation","date":"2006-05-26","matiere":"Droit des contrats","niveau":"L3","faits":"Un pacte de préférence est conclu au bénéfice d'une personne ; le propriétaire vend à un tiers qui connaissait ce pacte et l'intention du bénéficiaire.","procedure":"Le bénéficiaire demande l'annulation de la vente et sa substitution ; pourvoi devant la chambre mixte.","probleme":"Le bénéficiaire d'un pacte de préférence violé peut-il obtenir l'annulation de la vente et la substitution à l'acquéreur ?","solution":"Oui, à condition de prouver que le tiers acquéreur avait connaissance, lors de la conclusion de la vente, de l'existence du pacte et de l'intention du bénéficiaire de s'en prévaloir ; il obtient alors la nullité et la substitution.","portee":"Repris par l'article 1123 du Code civil depuis 2016 (nullité ou substitution).","tags":["pacte de préférence","substitution","tiers complice"],"id":"seed-jp-2006-05-26-pacte-de-preference-ch-mixte"},{"titre":"Faurecia II (Com.)","juridiction":"Cour de cassation","date":"2010-06-29","matiere":"Droit des contrats","niveau":"L3-M1","faits":"Un équipementier subit des dommages du fait d'un fournisseur de logiciels ; le contrat contient une clause limitant la réparation.","procedure":"Renvoi après cassation devant la chambre commerciale de la Cour de cassation.","probleme":"Dans quels cas une clause limitative est-elle écartée ?","solution":"Seule est réputée non écrite la clause limitative de réparation qui contredit la portée de l'obligation essentielle ; elle reste valable si elle ne vide pas cette obligation de sa substance, faute lourde mise à part.","portee":"Recentre Chronopost sur le contrôle de la clause : elle ne s'applique que si elle prive d'effet l'obligation essentielle.","tags":["clause limitative","obligation essentielle","faute lourde"],"id":"seed-jp-2010-06-29-faurecia-ii-com"},{"titre":"Mère porteuse (Ass. plén.)","juridiction":"Cour de cassation","date":"1991-05-31","matiere":"Droit des personnes et de la famille","niveau":"L1-L2","faits":"Un couple convient avec une femme qu'elle portera et accouchera d'un enfant pour le leur remettre ; le père biologique reconnaît l'enfant et son épouse demande l'adoption.","procedure":"L'assemblée plénière est saisie d'un pourvoi du procureur général.","probleme":"Une convention de gestation pour le compte d'autrui est-elle valable, et l'adoption qui en résulte peut-elle être prononcée ?","solution":"Non : la convention est nulle car elle contrevient au principe d'ordre public de l'indisponibilité du corps humain et de l'état des personnes ; l'adoption est un détournement de l'institution.","portee":"Position reprise dans l'article 16-7 du Code civil (lois bioéthiques de 1994) ; la CEDH impose depuis de reconnaître la filiation (Mennesson c. France, 2014).","tags":["gestation pour autrui","indisponibilité du corps","filiation"],"id":"seed-jp-1991-05-31-mere-porteuse-ass-plen"},{"titre":"Transsexualisme — état civil (Ass. plén.)","juridiction":"Cour de cassation","date":"1992-12-11","matiere":"Droit des personnes et de la famille","niveau":"L1-L2","faits":"Une personne transsexuelle demande la modification de la mention de son sexe à l'état civil après un traitement médico-chirurgical.","procedure":"Pourvoi devant l'assemblée plénière, après la condamnation de la France par la CEDH (B. c. France, 25 mars 1992).","probleme":"Le droit au respect de la vie privée permet-il la modification de la mention du sexe à l'état civil ?","solution":"Oui : lorsque, à la suite d'un traitement médico-chirurgical, une personne présente l'apparence du sexe opposé auquel elle correspond désormais, le principe du respect dû à la vie privée justifie que son état civil indique le sexe dont elle a l'apparence.","portee":"Revirement de jurisprudence sous l'influence de la CEDH ; aujourd'hui, l'article 61-5 du Code civil (loi du 18 novembre 2016) a simplifié la procédure.","tags":["état civil","transsexualisme","vie privée"],"id":"seed-jp-1992-12-11-transsexualisme-etat-civil-ass-plen"},{"titre":"Relations de l'enfant avec ses grands-parents (1re civ.)","juridiction":"Cour de cassation","date":"2009-01-14","matiere":"Droit des personnes et de la famille","niveau":"L2","faits":"Des grands-parents demandent à entretenir des relations personnelles avec leur petit-enfant, que ses parents s'y opposent.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Les parents peuvent-ils s'opposer à des relations entre l'enfant et ses grands-parents ?","solution":"Seul l'intérêt de l'enfant peut faire obstacle à son droit d'entretenir des relations personnelles avec ses ascendants (art. 371-4 du Code civil) ; l'opposition des parents ne suffit pas.","portee":"Principe constant : l'intérêt de l'enfant est le critère unique des relations personnelles avec les ascendants.","tags":["autorité parentale","ascendants","intérêt de l'enfant"],"id":"seed-jp-2009-01-14-relations-de-l-enfant-avec-ses-grands-pa"},{"titre":"Gestation pour autrui — transcription (Ass. plén.)","juridiction":"Cour de cassation","date":"2015-07-03","matiere":"Droit des personnes et de la famille","niveau":"L2-L3","faits":"Des enfants nés à l'étranger d'une gestation pour autrui voient leur acte de naissance étranger transcrit à l'état civil français, avec pour père le père biologique.","procedure":"Pourvoi devant l'assemblée plénière à la suite de la condamnation de la France par la CEDH (Mennesson, 2014).","probleme":"Le recours à la gestation pour autrui à l'étranger fait-il obstacle à la transcription de l'acte de naissance ?","solution":"Non, au moins pour la filiation paternelle : la convention de gestation pour autrui ne fait pas obstacle à la transcription de l'acte de naissance étranger régulier à l'égard du père biologique.","portee":"Tire les conséquences des arrêts Mennesson et Labassée (CEDH, 26 juin 2014) ; la filiation à l'égard de la mère d'intention passe par l'adoption (avis de la Cour de cassation, 2019).","tags":["GPA","état civil","transcription"],"id":"seed-jp-2015-07-03-gestation-pour-autrui-transcription-ass-"},{"titre":"Mention du sexe à l'état civil — « sexe neutre » (1re civ.)","juridiction":"Cour de cassation","date":"2017-05-04","matiere":"Droit des personnes et de la famille","niveau":"L1-L2","faits":"Une personne née avec des attributs sexuels indéterminés demande que son acte de naissance mentionne « sexe neutre » ou « intersexe » plutôt que « masculin ».","procedure":"La cour d'appel d'Orléans rejette sa demande ; pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Le droit français permet-il de faire figurer dans l'état civil une mention de sexe autre que masculin ou féminin ?","solution":"Non : la loi française ne permet pas de faire figurer dans les actes de l'état civil l'indication d'un sexe autre que masculin ou féminin ; l'atteinte à la vie privée est justifiée par la nécessité de préserver l'organisation sociale et juridique fondée sur la binarité des sexes.","portee":"Distingue la modification de la mention du sexe (possible, art. 61-5 du Code civil) de la création d'une troisième catégorie, exclue ; la CEDH n'impose pas de la prévoir.","tags":["état civil","sexe","intersexuation"],"id":"seed-jp-2017-05-04-mention-du-sexe-a-l-etat-civil-sexe-neut"},{"titre":"Macron (Com.)","juridiction":"Cour de cassation","date":"1997-06-17","matiere":"Droit des sûretés","niveau":"L3-M1","faits":"Le dirigeant d'une société se porte avaliste de ses dettes à hauteur de 20 millions de francs, somme très supérieure à son patrimoine et à ses revenus.","procedure":"La caution agit contre la banque ; pourvoi devant la chambre commerciale de la Cour de cassation.","probleme":"Le créancier professionnel qui demande un cautionnement manifestement disproportionné commet-il une faute ?","solution":"Oui : le banquier qui sollicite un engagement manifestement disproportionné aux biens et revenus de la caution commet une faute, qui engage sa responsabilité ; le cautionnement n'est pas annulé, mais la dette de la caution se compense avec les dommages-intérêts.","portee":"Première jurisprudence sur la disproportion du cautionnement ; ensuite précisée par Nahoum (2002) et consacrée par la loi (art. L. 341-4 ancien, puis L. 332-1 du Code de la consommation, et 2300 du Code civil).","tags":["cautionnement","disproportion","responsabilité du banquier"],"id":"seed-jp-1997-06-17-macron-com"},{"titre":"Nahoum (Com.)","juridiction":"Cour de cassation","date":"2002-10-08","matiere":"Droit des sûretés","niveau":"L3-M1","faits":"Deux promoteurs, dirigeants de la société débitrice, se portent cautions envers une banque et invoquent ensuite la disproportion de leur engagement.","procedure":"Pourvoi devant la chambre commerciale de la Cour de cassation.","probleme":"La disproportion de l'engagement de la caution suffit-elle à engager la responsabilité du banquier ?","solution":"Non : la caution avertie, qui ne prétend ni ne démontre que la banque avait sur ses revenus, son patrimoine et ses facultés de remboursement des informations qu'elle ignorait elle-même, ne peut rechercher la responsabilité de la banque.","portee":"Restreint Macron : la disproportion ne suffit pas ; la jurisprudence distingue ensuite cautions averties et non averties (mise en garde).","tags":["cautionnement","devoir de mise en garde","dirigeant caution"],"id":"seed-jp-2002-10-08-nahoum-com"},{"titre":"Expovit (soc.)","juridiction":"Cour de cassation","date":"1992-02-25","matiere":"Droit du travail","niveau":"L3","faits":"Un salarié est licencié alors que l'employeur ne lui a pas assuré la formation nécessaire pour s'adapter à l'évolution de son emploi.","procedure":"Pourvoi devant la chambre sociale de la Cour de cassation.","probleme":"L'employeur doit-il veiller à l'adaptation du salarié à l'évolution de son emploi ?","solution":"Oui : l'employeur a l'obligation d'assurer l'adaptation des salariés à l'évolution de leur emploi ; le licenciement pour insuffisance professionnelle est sans cause réelle et sérieuse s'il n'a pas rempli cette obligation.","portee":"Obligation d'adaptation, aujourd'hui codifiée à l'article L. 6321-1 du Code du travail.","tags":["adaptation","formation","exécution de bonne foi"],"id":"seed-jp-1992-02-25-expovit-soc"},{"titre":"Labbane (soc.)","juridiction":"Cour de cassation","date":"2000-12-19","matiere":"Droit du travail","niveau":"L3","faits":"Une personne qui travaille pour une entreprise sous un statut d'indépendant réclame la reconnaissance d'un contrat de travail.","procedure":"Pourvoi devant la chambre sociale de la Cour de cassation.","probleme":"Comment se détermine l'existence d'un contrat de travail ?","solution":"L'existence d'une relation de travail ne dépend ni de la volonté exprimée par les parties ni de la dénomination qu'elles ont donnée à leur convention, mais des conditions de fait dans lesquelles est exercée l'activité des travailleurs.","portee":"Principe de primauté des faits sur les qualifications contractuelles ; il fonde les requalifications ultérieures (Take Eat Easy, Uber).","tags":["contrat de travail","qualification","lien de subordination"],"id":"seed-jp-2000-12-19-labbane-soc"},{"titre":"Nikon (soc.)","juridiction":"Cour de cassation","date":"2001-10-02","matiere":"Droit du travail","niveau":"L3","faits":"Un employeur consulte des fichiers personnels d'un salarié sur son ordinateur professionnel et le licencie pour avoir utilisé le matériel à des fins privées.","procedure":"Pourvoi devant la chambre sociale de la Cour de cassation.","probleme":"L'employeur peut-il lire les messages personnels du salarié sur l'ordinateur de l'entreprise ?","solution":"Non : le salarié a droit, même au temps et au lieu de travail, au respect de l'intimité de sa vie privée, qui implique le secret des correspondances ; l'employeur ne peut dès lors prendre connaissance des messages personnels émis ou reçus par le salarié grâce à un outil informatique mis à sa disposition, même s'il en a interdit l'usage non professionnel.","portee":"Fonde la protection de la vie privée du salarié ; précisée ensuite (fichiers non identifiés comme personnels présumés professionnels).","tags":["vie privée","correspondance","salarié","informatique"],"id":"seed-jp-2001-10-02-nikon-soc"},{"titre":"Clause de non-concurrence — contrepartie financière (soc.)","juridiction":"Cour de cassation","date":"2002-07-10","matiere":"Droit du travail","niveau":"L3-M1","faits":"Un salarié, lié par une clause lui interdisant de travailler pour un concurrent après la rupture de son contrat, conteste sa validité parce qu'elle ne prévoit aucune compensation financière.","procedure":"Pourvoi devant la chambre sociale de la Cour de cassation (plusieurs arrêts du même jour).","probleme":"À quelles conditions une clause de non-concurrence insérée dans un contrat de travail est-elle valable ?","solution":"La clause n'est licite que si elle est indispensable à la protection des intérêts légitimes de l'entreprise, limitée dans le temps et dans l'espace, tient compte des spécificités de l'emploi du salarié et comporte une contrepartie financière ; ces conditions sont cumulatives.","portee":"Ajoute l'exigence d'une contrepartie financière, qui devient la règle en droit du travail ; ces solutions sont constamment réaffirmées.","tags":["clause de non-concurrence","contrepartie","liberté du travail"],"id":"seed-jp-2002-07-10-clause-de-non-concurrence-contrepartie-f"},{"titre":"Baby Loup (Ass. plén.)","juridiction":"Cour de cassation","date":"2014-06-25","matiere":"Droit du travail","niveau":"L3-M1","faits":"Une salariée d'une crèche associative est licenciée pour avoir refusé de retirer son voile islamique, contrairement au règlement intérieur.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation, après une première cassation.","probleme":"Une association privée peut-elle imposer une obligation de neutralité à ses salariés, au contact des enfants ?","solution":"Oui : la restriction à la liberté de manifester sa religion, prévue par le règlement intérieur, est justifiée par la nature de la tâche à accomplir et proportionnée au but poursuivi, la protection de la liberté de conscience des enfants ; le licenciement est licite.","portee":"Précise les conditions des restrictions aux libertés dans l'entreprise (art. L. 1121-1 du Code du travail) ; loi du 8 août 2016 sur la neutralité.","tags":["liberté religieuse","neutralité","entreprise de conviction"],"id":"seed-jp-2014-06-25-baby-loup-ass-plen"},{"titre":"Take Eat Easy (soc.)","juridiction":"Cour de cassation","date":"2018-11-28","matiere":"Droit du travail","niveau":"M1","faits":"Un coursier à vélo, inscrit comme travailleur indépendant sur une plateforme de livraison, demande la requalification de sa relation en contrat de travail.","procedure":"Pourvoi devant la chambre sociale de la Cour de cassation.","probleme":"Le coursier peut-il bénéficier de la présomption de salariat malgré son statut d'indépendant ?","solution":"Oui : le lien de subordination est caractérisé par l'exécution d'un travail sous l'autorité d'un employeur qui a le pouvoir de donner des ordres, d'en contrôler l'exécution et de sanctionner les manquements ; la géolocalisation et le système de pénalités traduisent un pouvoir de contrôle et de sanction.","portee":"Première grande requalification d'un travailleur de plateforme.","tags":["plateformes","requalification","géolocalisation","subordination"],"id":"seed-jp-2018-11-28-take-eat-easy-soc"},{"titre":"Uber (soc.)","juridiction":"Cour de cassation","date":"2020-03-04","matiere":"Droit du travail","niveau":"M1","faits":"Un chauffeur inscrit sur une application de réservation de VTC demande la requalification de sa relation avec la plateforme en contrat de travail.","procedure":"Pourvoi devant la chambre sociale de la Cour de cassation.","probleme":"Le chauffeur de la plateforme est-il lié à elle par un contrat de travail ?","solution":"Oui : le chauffeur ne se constitue pas sa propre clientèle, ne fixe pas librement ses tarifs ni les conditions d'exercice de sa prestation de transport, dès lors le statut d'indépendant est fictif ; il existe un lien de subordination.","portee":"Confirme l'orientation de Take Eat Easy ; la directive (UE) 2024/2831 sur le travail de plateforme crée une présomption de salariat.","tags":["plateformes","requalification","indépendance fictive"],"id":"seed-jp-2020-03-04-uber-soc"},{"titre":"Barème d'indemnisation du licenciement injustifié (soc.)","juridiction":"Cour de cassation","date":"2022-05-11","matiere":"Droit du travail","niveau":"M1","faits":"Des salariés licenciés sans cause réelle et sérieuse contestent le plafonnement de leurs indemnités par l'article L. 1235-3 du Code du travail et réclament une réparation intégrale.","procedure":"Pourvois devant la chambre sociale de la Cour de cassation.","probleme":"Le barème d'indemnisation (« barème Macron ») est-il compatible avec l'article 10 de la convention n° 158 de l'OIT et l'article 24 de la Charte sociale européenne ?","solution":"Oui : le barème est compatible avec l'article 10 de la convention n° 158 de l'OIT, qui prévoit une indemnité « adéquate » ; l'article 24 de la Charte sociale européenne n'est pas d'effet direct en droit interne.","portee":"Confirme la validité du barème ; le juge ne peut écarter l'application du barème au cas par cas.","tags":["licenciement sans cause","barème Macron","conventionnalité"],"id":"seed-jp-2022-05-11-bareme-d-indemnisation-du-licenciement-i"},{"titre":"Congés payés et arrêt maladie (soc.)","juridiction":"Cour de cassation","date":"2023-09-13","matiere":"Droit du travail","niveau":"M1","faits":"Des salariés en arrêt maladie, non professionnelle, n'ont pas acquis de congés payés ; l'article L. 3141-5 du Code du travail ne l'autorise que pour certaines absences.","procedure":"Pourvois devant la chambre sociale de la Cour de cassation.","probleme":"Le Code du travail peut-il refuser l'acquisition de congés payés pendant les arrêts maladie, au regard du droit de l'Union ?","solution":"Non : l'article 31 § 2 de la Charte et la directive 2003/88 reconnaissent le droit aux congés payés, sans condition de travail effectif ; le juge écarte la règle française contraire, qui limite l'acquisition pendant la maladie non professionnelle.","portee":"Alignement sur la jurisprudence de la CJUE ; la loi du 22 avril 2024 en tire les conséquences.","tags":["congés payés","maladie","droit de l'Union","effet direct"],"id":"seed-jp-2023-09-13-conges-payes-et-arret-maladie-soc"},{"titre":"Princesse de Bauffremont (Civ.)","juridiction":"Cour de cassation","date":"1878-03-18","matiere":"Droit international privé","niveau":"L3","faits":"Une Française, séparée de corps de son mari, se fait naturaliser dans le duché de Saxe-Altenbourg pour divorcer et se remarier, ce que la loi française interdisait alors.","procedure":"Pourvoi devant la chambre civile de la Cour de cassation.","probleme":"Le changement de nationalité en vue d'échapper à la loi française est-il opposable en France ?","solution":"Non : la fraude à la loi fait obstacle à l'effet du changement de nationalité, dès lors qu'il a été acquis dans le but d'échapper aux dispositions impératives de la loi française ; il est inopposable.","portee":"Première application de la fraude à la loi en droit international privé.","tags":["fraude à la loi","divorce","nationalité"],"id":"seed-jp-1878-03-18-princesse-de-bauffremont-civ"},{"titre":"Forgo (Civ.)","juridiction":"Cour de cassation","date":"1878-06-24","matiere":"Droit international privé","niveau":"L3","faits":"Un enfant naturel bavarois, installé en France depuis son enfance, y décède sans testament ; la loi bavaroise applique la loi du domicile de fait (française), contrairement à la règle française qui retient la loi bavaroise.","procedure":"Pourvoi devant la chambre civile de la Cour de cassation.","probleme":"Faut-il appliquer la loi désignée par la règle de conflit de lois française en tenant compte des règles de conflit de l'État étranger (renvoi) ?","solution":"Oui : en acceptant le renvoi, la Cour applique la loi française, désignée par la règle de conflit bavaroise ; la succession mobilière est régie par la loi du dernier domicile de fait.","portee":"Premier arrêt accueillant le renvoi en droit international privé ; il sert de point de départ à une longue jurisprudence sur le renvoi.","tags":["renvoi","conflit de lois","succession"],"id":"seed-jp-1878-06-24-forgo-civ"},{"titre":"American Trading Company (Civ.)","juridiction":"Cour de cassation","date":"1910-12-05","matiere":"Droit international privé","niveau":"L3","faits":"Un contrat d'affrètement maritime comporte une clause de choix de loi ; l'une des parties conteste sa validité devant les juridictions françaises.","procedure":"Pourvoi devant la chambre civile de la Cour de cassation.","probleme":"Quelle loi gouverne un contrat international : la loi choisie par les parties ou la loi désignée par la règle de conflit ?","solution":"La loi applicable aux contrats, soit pour leur formation, soit pour leurs effets et conditions, est celle que les parties ont adoptée ; l'autonomie de la volonté est consacrée.","portee":"Fonde le principe d'autonomie de la volonté en matière contractuelle ; aujourd'hui repris par le règlement Rome I (art. 3).","tags":["contrats internationaux","autonomie de la volonté","loi applicable"],"id":"seed-jp-1910-12-05-american-trading-company-civ"},{"titre":"Bisbal (1re civ.)","juridiction":"Cour de cassation","date":"1959-05-12","matiere":"Droit international privé","niveau":"L3","faits":"Des époux de nationalité espagnole, en procès devant le juge français, n'invoquent pas la règle de conflit qui désigne leur loi nationale ; le juge applique la loi française.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Le juge français doit-il appliquer d'office la règle de conflit de lois ?","solution":"Non : les règles françaises de conflit de lois, en tant qu'elles prescrivent l'application d'une loi étrangère, n'ont pas un caractère d'ordre public ; il appartient aux parties d'en réclamer l'application, le juge n'étant pas tenu de la soulever d'office.","portee":"Position remplacée par les arrêts Rebouh (11 oct. 1988) et Schule Mazetti (1991), puis Mutuelle du Mans (26 mai 1999) : le juge doit appliquer la règle de conflit s'il s'agit de droits indisponibles.","tags":["office du juge","règle de conflit","droit étranger"],"id":"seed-jp-1959-05-12-bisbal-1re-civ"},{"titre":"Munzer (1re civ.)","juridiction":"Cour de cassation","date":"1964-01-07","matiere":"Droit international privé","niveau":"L3-M1","faits":"Un jugement américain de séparation de corps, qui fixe une pension alimentaire, est invoqué en France et son exequatur est demandé.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation, qui soutient que la cour d'appel ne pouvait réviser la décision étrangère.","probleme":"À quelles conditions un jugement étranger peut-il être rendu exécutoire en France ?","solution":"Le juge français doit vérifier cinq conditions : la compétence du tribunal étranger, la régularité de la procédure, l'application de la loi compétente selon les règles françaises de conflit, la conformité à l'ordre public international et l'absence de fraude ; il ne procède pas à une révision au fond.","portee":"Source de la liste des conditions de régularité, simplifiée par l'arrêt Cornelissen (2007), qui supprime le contrôle de la loi appliquée.","tags":["exequatur","jugement étranger","conditions","révision au fond"],"id":"seed-jp-1964-01-07-munzer-1re-civ"},{"titre":"Bier c. Mines de potasse d'Alsace","juridiction":"CJUE","date":"1976-11-30","matiere":"Droit international privé","niveau":"L3-M1","faits":"Un horticulteur néerlandais est victime de la pollution du Rhin, causée par des déversements de sel d'une mine française.","procedure":"Question préjudicielle du Gerechtshof de La Haye sur l'interprétation de la convention de Bruxelles.","probleme":"Où se trouve le « lieu où le fait dommageable s'est produit » (art. 5 § 3) lorsque le fait générateur et le dommage se situent dans deux États ?","solution":"Les deux : le demandeur peut choisir de saisir le tribunal du lieu du fait générateur ou celui du lieu de la matérialisation du dommage.","portee":"Option de compétence dans les délits complexes ; reprise à l'article 7, point 2, du règlement Bruxelles I bis.","tags":["compétence","délit complexe","lieu du fait dommageable"],"id":"seed-jp-1976-11-30-bier-c-mines-de-potasse-d-alsace"},{"titre":"Compagnie de Signaux et d'équipements électroniques (1re civ.)","juridiction":"Cour de cassation","date":"1985-12-17","matiere":"Droit international privé","niveau":"L3","faits":"Un contrat international comporte une clause attribuant compétence à des juridictions étrangères ; l'une des parties saisit pourtant les juridictions françaises.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"Une clause attributive de juridiction est-elle valable dans un contrat international ?","solution":"Oui : une clause attributive de juridiction est licite dans un contrat international, sauf si elle contrevient à une compétence exclusive des tribunaux français et en l'absence de fraude.","portee":"Conditionne la validité des clauses attributives (règle matérielle) ; consacrée aujourd'hui par le règlement Bruxelles I bis (art. 25).","tags":["clause attributive de juridiction","contrats internationaux","validité"],"id":"seed-jp-1985-12-17-compagnie-de-signaux-et-d-equipements-el"},{"titre":"Ingmar GB","juridiction":"CJUE","date":"2000-11-09","matiere":"Droit international privé","niveau":"M1-M2","faits":"Un agent commercial britannique d'un fabricant californien réclame l'indemnité de fin de contrat prévue par une directive, alors que le contrat est soumis au droit californien.","procedure":"Question préjudicielle de la Court of Appeal.","probleme":"Les dispositions protectrices de la directive sur les agents commerciaux s'appliquent-elles malgré un choix de loi d'un pays tiers ?","solution":"Oui : le régime de protection de l'agent est impératif dans l'ordre juridique de l'Union ; il doit être appliqué lorsque l'agent exerce son activité dans un État membre, même si le contrat choisit la loi d'un État tiers.","portee":"Première affirmation d'une loi de police européenne ; suivi d'Unamar (2013).","tags":["lois de police","agent commercial","loi choisie"],"id":"seed-jp-2000-11-09-ingmar-gb"},{"titre":"Gasser","juridiction":"CJUE","date":"2003-12-09","matiere":"Droit international privé","niveau":"M1","faits":"Un fournisseur italien saisit d'abord un tribunal italien pour faire constater qu'il n'est pas tenu à l'exécution d'un contrat ; son cocontractant autrichien saisit ensuite le tribunal autrichien, désigné par la clause attributive.","procedure":"Question préjudicielle de l'Oberlandesgericht d'Innsbruck.","probleme":"Le tribunal désigné par une clause attributive peut-il passer outre la litispendance lorsque le tribunal premier saisi est lent ?","solution":"Non : le tribunal saisi en second doit surseoir à statuer jusqu'à ce que le tribunal premier saisi se déclare incompétent, quelle que soit la durée des procédures.","portee":"Faille du système Bruxelles I (« torpilles italiennes ») corrigée par le règlement Bruxelles I bis (art. 31, § 2).","tags":["litispendance","clause attributive","tribunal premier saisi"],"id":"seed-jp-2003-12-09-gasser"},{"titre":"Owusu","juridiction":"CJUE","date":"2005-03-01","matiere":"Droit international privé","niveau":"M1","faits":"Un Britannique, blessé en Jamaïque lors de vacances, assigne devant les juridictions britanniques le propriétaire anglais de la villa ; ce dernier invoque le forum non conveniens.","procedure":"Question préjudicielle de la Court of Appeal.","probleme":"Un juge compétent selon la convention de Bruxelles peut-il décliner sa compétence en faveur d'un État tiers au nom du forum non conveniens ?","solution":"Non : la doctrine du forum non conveniens est incompatible avec la convention de Bruxelles, qui est d'application obligatoire et vise la prévisibilité des règles.","portee":"Exclut le forum non conveniens du champ du droit européen de la compétence judiciaire.","tags":["forum non conveniens","compétence","convention de Bruxelles"],"id":"seed-jp-2005-03-01-owusu"},{"titre":"Cornelissen (1re civ.)","juridiction":"Cour de cassation","date":"2007-02-20","matiere":"Droit international privé","niveau":"L3-M1","faits":"Un tribunal fédéral américain condamne un ressortissant colombien à des dommages-intérêts triples (treble damages) pour manquement à des obligations fiduciaires ; l'exequatur du jugement est demandé en France et contesté.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"À quelles conditions un jugement étranger peut-il être reconnu et exécuté en France ?","solution":"Trois conditions : la compétence indirecte du juge étranger (rattachement caractérisé du litige à cet État et absence de fraude), la conformité à l'ordre public international (de fond et de procédure) et l'absence de fraude à la loi ; le contrôle de la loi appliquée n'est plus exigé.","portee":"Simplifie le contrôle de la régularité internationale des jugements étrangers (suppression du contrôle de la loi appliquée).","tags":["exequatur","jugement étranger","conditions de régularité"],"id":"seed-jp-2007-02-20-cornelissen-1re-civ"},{"titre":"Réserve héréditaire et ordre public international (1re civ.)","juridiction":"Cour de cassation","date":"2017-09-27","matiere":"Droit international privé","niveau":"M1","faits":"Un Français installé en Californie y décède, laissant un testament qui exclut ses enfants ; sa succession est soumise à la loi californienne, qui ignore la réserve héréditaire.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"La loi étrangère qui ne connaît pas la réserve héréditaire est-elle contraire à l'ordre public international français ?","solution":"Non : une loi étrangère qui ignore la réserve héréditaire n'est pas, en soi, contraire à l'ordre public international ; il faudrait établir que son application porte une atteinte excessive aux héritiers (précarité, besoin).","portee":"Précisé par Cass. 1re civ., 4 déc. 2019 ; limite la portée de la loi du 7 juillet 2024 sur l'ordre public successoral.","tags":["succession","réserve héréditaire","ordre public"],"id":"seed-jp-2017-09-27-reserve-hereditaire-et-ordre-public-inte"},{"titre":"Lotus (CPJI)","juridiction":"CIJ","date":"1927-09-07","matiere":"Droit international public","niveau":"L3-M1","faits":"Un navire français (le Lotus) heurte et coule un navire turc en haute mer ; à l'arrivée à Constantinople, l'officier français est poursuivi par la Turquie.","procedure":"La Cour permanente de Justice internationale est saisie par compromis entre la France et la Turquie.","probleme":"Un État peut-il exercer sa compétence pénale à l'égard d'un fait commis en haute mer ?","solution":"Oui : le droit international n'interdit pas à un État d'étendre sa compétence au-delà de son territoire, sauf règle prohibitive contraire ; l'État est libre de prendre des mesures qui ne sont pas explicitement interdites.","portee":"Arrêt fondateur du principe de liberté des États (« tout ce qui n'est pas interdit est permis »), nuancé depuis par la convention de Montego Bay (1982).","tags":["souveraineté","compétence pénale","abordage en haute mer"],"id":"seed-jp-1927-09-07-lotus-cpji"},{"titre":"Île de Palmas (CPA)","juridiction":"Autre","date":"1928-04-04","matiere":"Droit international public","niveau":"L3-M1","faits":"Les États-Unis et les Pays-Bas se disputent la souveraineté sur une île de l'archipel des Philippines.","procedure":"Sentence arbitrale de Max Huber, rendue par la Cour permanente d'arbitrage.","probleme":"Comment s'acquiert et se conserve la souveraineté territoriale, entre une découverte ancienne et un exercice paisible ?","solution":"La souveraineté implique l'exercice du pouvoir de l'État de manière continue et paisible ; le titre de la découverte ne vaut que s'il est suivi d'une occupation effective.","portee":"Pose la définition de la souveraineté territoriale (« le droit d'exercer, à l'exclusion de tout autre État, les fonctions étatiques »).","tags":["territoire","effectivité","souveraineté"],"id":"seed-jp-1928-04-04-ile-de-palmas-cpa"},{"titre":"Usine de Chorzów (fond)","juridiction":"CIJ","date":"1928-09-13","matiere":"Droit international public","niveau":"L3-M1","faits":"L'État polonais exproprie une usine de nitrate appartenant à une société allemande, en violation de la convention de Genève de 1922.","procedure":"La Cour permanente de Justice internationale est saisie par l'Allemagne.","probleme":"Quelle réparation est due à raison d'un acte illicite international ?","solution":"Tout manquement à un engagement comporte l'obligation de réparer ; la réparation doit, autant que possible, effacer toutes les conséquences de l'acte illicite et rétablir l'état qui aurait vraisemblablement existé (restitutio in integrum), sinon l'indemnité.","portee":"Principe fondamental du droit de la responsabilité internationale ; repris à l'article 31 du projet de la CDI de 2001.","tags":["responsabilité internationale","réparation","restitutio in integrum"],"id":"seed-jp-1928-09-13-usine-de-chorzow-fond"},{"titre":"Trail Smelter (arbitrage)","juridiction":"Autre","date":"1941-03-11","matiere":"Droit international public","niveau":"M1","faits":"Une fonderie canadienne rejette dans l'atmosphère des fumées sulfureuses qui endommagent des terres agricoles américaines de l'État de Washington.","procedure":"Tribunal arbitral mixte créé par une convention entre les États-Unis et le Canada.","probleme":"Un État est-il responsable d'une pollution venant de son territoire qui cause un dommage sur le territoire voisin ?","solution":"Oui : aucun État n'a le droit d'user de son territoire ou de permettre qu'il en soit fait usage de manière à causer un préjudice grave par des fumées sur le territoire d'un autre État, si les conséquences sont graves et prouvées.","portee":"Origine du principe de prévention du dommage transfrontière, repris dans la déclaration de Rio (principe 2).","tags":["pollution transfrontière","responsabilité","environnement"],"id":"seed-jp-1941-03-11-trail-smelter-arbitrage"},{"titre":"Détroit de Corfou (CIJ)","juridiction":"CIJ","date":"1949-04-09","matiere":"Droit international public","niveau":"M1","faits":"Deux destroyers britanniques heurtent des mines dans le détroit de Corfou, dans les eaux albanaises ; des marins sont tués.","procedure":"Le Royaume-Uni saisit la Cour internationale de Justice.","probleme":"L'Albanie est-elle responsable des explosions pour avoir omis d'avertir de la présence des mines ?","solution":"Oui : tout État a l'obligation de ne pas laisser utiliser son territoire aux fins d'actes contraires aux droits d'autres États ; le droit de passage inoffensif dans les détroits existe, et l'intervention britannique ultérieure (opération de déminage) viole la souveraineté albanaise.","portee":"Première affaire de la CIJ ; fonde le devoir de vigilance et l'obligation d'avertir.","tags":["responsabilité","mines","droit de passage"],"id":"seed-jp-1949-04-09-detroit-de-corfou-cij"},{"titre":"Réparation des dommages subis au service des Nations Unies (avis)","juridiction":"CIJ","date":"1949-04-11","matiere":"Droit international public","niveau":"M1","faits":"Après l'assassinat du comte Bernadotte, médiateur de l'ONU en Palestine, l'Assemblée générale demande à la Cour si l'Organisation peut présenter une réclamation internationale.","procedure":"Avis consultatif de la Cour internationale de Justice.","probleme":"L'ONU a-t-elle la personnalité juridique internationale et peut-elle agir pour réparer un dommage subi par un de ses agents ?","solution":"Oui : l'Organisation est un sujet de droit international, capable d'être titulaire de droits et de devoirs et de présenter une réclamation internationale ; elle peut exercer la protection fonctionnelle de ses agents.","portee":"Reconnaissance de la personnalité juridique objective de l'ONU et de la théorie des compétences implicites.","tags":["personnalité juridique","organisations internationales","protection fonctionnelle"],"id":"seed-jp-1949-04-11-reparation-des-dommages-subis-au-service"},{"titre":"Pêcheries anglo-norvégiennes (CIJ)","juridiction":"CIJ","date":"1951-12-18","matiere":"Droit international public","niveau":"M1","faits":"La Norvège fixe les lignes de base de sa mer territoriale en reliant des points extrêmes de sa côte découpée ; le Royaume-Uni s'y oppose.","procedure":"Le Royaume-Uni saisit la Cour internationale de Justice.","probleme":"La méthode des lignes de base droites utilisée par la Norvège est-elle conforme au droit international ?","solution":"Oui : la méthode des lignes droites, adaptée à la configuration de la côte et appliquée de manière constante et sans protestation, est conforme au droit international ; la délimitation, acte unilatéral, doit toutefois respecter le droit international.","portee":"Fonde la méthode des lignes de base droites (art. 7 de la convention de Montego Bay).","tags":["mer territoriale","lignes de base","droit de la mer"],"id":"seed-jp-1951-12-18-pecheries-anglo-norvegiennes-cij"},{"titre":"Lac Lanoux (arbitrage)","juridiction":"Autre","date":"1957-11-16","matiere":"Droit international public","niveau":"M1","faits":"La France projette de dériver des eaux du lac Lanoux, en les restituant ; l'Espagne s'y oppose.","procedure":"Tribunal arbitral franco-espagnol.","probleme":"Un État peut-il réaliser un projet sur un cours d'eau partagé sans l'accord de l'État voisin ?","solution":"Oui, si l'État amont respecte l'obligation de négocier de bonne foi et tient compte des intérêts de l'État aval ; il n'y a pas de droit de veto de l'État aval.","portee":"Principe du « droit de consultation » et de la bonne foi dans les litiges sur les cours d'eau internationaux.","tags":["cours d'eau","droits d'État amont","obligation de négocier"],"id":"seed-jp-1957-11-16-lac-lanoux-arbitrage"},{"titre":"Plateau continental de la mer du Nord (CIJ)","juridiction":"CIJ","date":"1969-02-20","matiere":"Droit international public","niveau":"M1-M2","faits":"Le Danemark et les Pays-Bas contestent à l'Allemagne la délimitation de leur plateau continental selon la règle de l'équidistance.","procedure":"Affaires jointes devant la Cour internationale de Justice.","probleme":"La règle d'équidistance de la convention de Genève de 1958 s'impose-t-elle à un État non partie comme règle coutumière ?","solution":"Non : elle n'est pas devenue coutumière ; la délimitation doit se faire par accord, selon des principes équitables et en tenant compte de toutes les circonstances pertinentes.","portee":"Critères de formation de la coutume (pratique et opinio juris) ; important pour les sources du droit international.","tags":["coutume","délimitation","équité"],"id":"seed-jp-1969-02-20-plateau-continental-de-la-mer-du-nord-ci"},{"titre":"Barcelona Traction (CIJ)","juridiction":"CIJ","date":"1970-02-05","matiere":"Droit international public","niveau":"M2","faits":"La Belgique réclame à l'Espagne réparation pour les dommages subis par des actionnaires belges d'une société de droit canadien.","procedure":"La Belgique saisit la Cour internationale de Justice.","probleme":"Un État peut-il exercer la protection diplomatique en faveur des actionnaires d'une société étrangère ?","solution":"Non : seul l'État national de la société (le Canada) peut exercer la protection diplomatique ; la Cour distingue les obligations erga omnes, dues à l'ensemble de la communauté internationale, des autres obligations.","portee":"Établit la distinction des obligations envers tous (erga omnes) ; critère de la nationalité des sociétés pour la protection diplomatique.","tags":["protection diplomatique","obligations erga omnes","société"],"id":"seed-jp-1970-02-05-barcelona-traction-cij"},{"titre":"Essais nucléaires (Australie c. France)","juridiction":"CIJ","date":"1974-12-20","matiere":"Droit international public","niveau":"M2","faits":"L'Australie et la Nouvelle-Zélande demandent à la Cour d'ordonner la cessation des essais nucléaires français dans le Pacifique.","procedure":"Requêtes devant la Cour internationale de Justice.","probleme":"Un État est-il lié par des déclarations unilatérales de ses autorités sur l'arrêt des essais ?","solution":"Oui : les déclarations publiques du Président de la République et de ministres, faites avec l'intention de s'engager, ont créé une obligation juridique ; l'objet du différend a disparu et la Cour n'a plus à statuer.","portee":"Fonde la théorie des actes unilatéraux créateurs d'obligations (principe de bonne foi).","tags":["actes unilatéraux","engagement","essais nucléaires"],"id":"seed-jp-1974-12-20-essais-nucleaires-australie-c-france"},{"titre":"Activités militaires au Nicaragua (fond)","juridiction":"CIJ","date":"1986-06-27","matiere":"Droit international public","niveau":"M2","faits":"Le Nicaragua accuse les États-Unis d'avoir soutenu les Contras et miné ses ports ; les États-Unis invoquent la légitime défense collective.","procedure":"Requête du Nicaragua devant la Cour internationale de Justice ; les États-Unis ne participent plus à l'instance après l'arrêt sur la compétence.","probleme":"Les États-Unis ont-ils violé l'interdiction de l'usage de la force et le principe de non-intervention ?","solution":"Oui : l'appui apporté aux Contras et les actes directs (minage des ports) violent l'interdiction du recours à la force et la non-intervention ; la légitime défense collective suppose une agression armée et une demande de l'État victime.","portee":"Précise les conditions de la légitime défense, le contrôle effectif et la coutume des principes de la Charte.","tags":["usage de la force","légitime défense","non-intervention"],"id":"seed-jp-1986-06-27-activites-militaires-au-nicaragua-fond"},{"titre":"Tadić (appel sur la compétence)","juridiction":"Autre","date":"1995-10-02","matiere":"Droit international public","niveau":"M2","faits":"Dusko Tadić, accusé de crimes en Bosnie, conteste la légalité de la création du Tribunal pénal international pour l'ex-Yougoslavie.","procedure":"Appel devant la Chambre d'appel du TPIY sur la compétence.","probleme":"Le TPIY a-t-il été légalement créé, et son statut s'applique-t-il aux conflits armés internes ?","solution":"Oui : la création du Tribunal par le Conseil de sécurité est légale (chapitre VII) ; les crimes de guerre, au sens du droit coutumier, peuvent être jugés même en cas de conflit armé non international.","portee":"Étend le droit pénal international aux conflits internes ; arrêt fondateur du droit international pénal contemporain.","tags":["droit international pénal","conflits armés","TPIY"],"id":"seed-jp-1995-10-02-tadic-appel-sur-la-competence"},{"titre":"Licéité de la menace ou de l'emploi d'armes nucléaires (avis)","juridiction":"CIJ","date":"1996-07-08","matiere":"Droit international public","niveau":"M2","faits":"L'Assemblée générale de l'ONU demande à la Cour s'il est permis de recourir aux armes nucléaires.","procedure":"Avis consultatif de la Cour internationale de Justice.","probleme":"La menace ou l'emploi d'armes nucléaires est-il licite au regard du droit international ?","solution":"Ni autorisation ni interdiction universelle : une menace ou un emploi contraire à l'article 2 § 4 est illicite ; l'emploi serait en général contraire au droit des conflits armés ; la Cour ne peut conclure à la licéité ou l'illicéité dans une circonstance extrême de légitime défense où la survie de l'État est en cause.","portee":"Rappelle l'obligation de négocier le désarmement nucléaire (art. VI du TNP).","tags":["armes nucléaires","droit humanitaire","avis consultatif"],"id":"seed-jp-1996-07-08-liceite-de-la-menace-ou-de-l-emploi-d-ar"},{"titre":"Gabčíkovo-Nagymaros (CIJ)","juridiction":"CIJ","date":"1997-09-25","matiere":"Droit international public","niveau":"M2","faits":"La Hongrie suspend, puis abandonne, la construction d'ouvrages sur le Danube prévus par un traité de 1977 avec la Tchécoslovaquie, pour des raisons écologiques.","procedure":"Affaire portée devant la Cour internationale de Justice par compromis.","probleme":"Un État peut-il invoquer l'état de nécessité écologique pour suspendre l'exécution d'un traité ?","solution":"Non, ici : l'état de nécessité ne peut justifier l'abandon du traité, car le péril n'était ni grave ni imminent ; mais le traité reste en vigueur et les parties doivent négocier de bonne foi ; la Slovaquie a aussi violé le droit en détournant le Danube.","portee":"Confirme la règle de continuité des traités et reconnaît le développement durable.","tags":["état de nécessité","droit des traités","environnement"],"id":"seed-jp-1997-09-25-gabcikovo-nagymaros-cij"},{"titre":"Akayesu (TPIR)","juridiction":"Autre","date":"1998-09-02","matiere":"Droit international public","niveau":"M2","faits":"Jean-Paul Akayesu, bourgmestre d'une commune rwandaise, est accusé d'avoir incité et participé au génocide des Tutsis en 1994.","procedure":"Jugement du Tribunal pénal international pour le Rwanda.","probleme":"Quelle est la définition du génocide, et le viol peut-il être un acte de génocide ?","solution":"Akayesu est reconnu coupable de génocide et de crimes contre l'humanité ; le viol et les violences sexuelles constituent un acte de génocide lorsqu'ils sont commis avec l'intention de détruire un groupe.","portee":"Premier jugement international pour génocide ; reconnaît le viol comme instrument de génocide.","tags":["génocide","viol","crimes contre l'humanité"],"id":"seed-jp-1998-09-02-akayesu-tpir"},{"titre":"LaGrand (CIJ)","juridiction":"CIJ","date":"2001-06-27","matiere":"Droit international public","niveau":"M2","faits":"Deux ressortissants allemands sont condamnés à mort aux États-Unis sans avoir été informés de leur droit à l'assistance consulaire ; l'un d'eux est exécuté malgré une ordonnance de la Cour.","procedure":"L'Allemagne saisit la Cour internationale de Justice.","probleme":"Les mesures conservatoires de la Cour sont-elles obligatoires, et la violation de la convention de Vienne sur les relations consulaires engage-t-elle des droits individuels ?","solution":"Oui : les mesures conservatoires indiquées par la Cour ont un caractère obligatoire ; l'article 36 de la convention de Vienne confère des droits individuels aux détenus ; les États-Unis ont violé leurs obligations.","portee":"Reconnaît la force obligatoire des mesures conservatoires et les droits individuels issus du droit consulaire ; prolongé par Avena (2004).","tags":["droit consulaire","mesures conservatoires","peine de mort"],"id":"seed-jp-2001-06-27-lagrand-cij"},{"titre":"Mandat d'arrêt du 11 avril 2000 (RDC c. Belgique)","juridiction":"CIJ","date":"2002-02-14","matiere":"Droit international public","niveau":"M2","faits":"La Belgique lance un mandat d'arrêt international contre le ministre congolais des Affaires étrangères, accusé de crimes de guerre, sur le fondement de la compétence universelle.","procedure":"La RDC saisit la Cour internationale de Justice.","probleme":"Un ministre des Affaires étrangères en exercice bénéficie-t-il d'une immunité pénale devant les juridictions étrangères ?","solution":"Oui : les ministres des Affaires étrangères jouissent d'une immunité de juridiction pénale et d'une inviolabilité complètes, même pour des crimes graves, tant qu'ils sont en fonction ; elle ne vaut pas devant une juridiction pénale internationale compétente.","portee":"Distingue immunité personnelle (en fonction) et immunité fonctionnelle ; la compétence universelle ne lève pas l'immunité.","tags":["immunités","ministre des Affaires étrangères","compétence universelle"],"id":"seed-jp-2002-02-14-mandat-d-arret-du-11-avril-2000-rdc-c-be"},{"titre":"Avena (CIJ)","juridiction":"CIJ","date":"2004-03-31","matiere":"Droit international public","niveau":"M2","faits":"Le Mexique soutient que cinquante-quatre de ses ressortissants condamnés à mort aux États-Unis n'ont pas été informés de leur droit à l'assistance consulaire.","procedure":"Requête du Mexique devant la Cour internationale de Justice.","probleme":"Quelles sont les conséquences du manquement à l'article 36 de la convention de Vienne sur les relations consulaires ?","solution":"Les États-Unis ont violé leurs obligations ; ils doivent assurer un réexamen et une révision effective des condamnations et des peines, en tenant compte de la violation, par le moyen de leur choix.","portee":"Précise les modalités de réparation ; la Cour refuse d'étendre l'effet de la violation à une exclusion automatique de la preuve.","tags":["droit consulaire","peine de mort","réparation"],"id":"seed-jp-2004-03-31-avena-cij"},{"titre":"Conséquences juridiques de l'édification d'un mur (avis)","juridiction":"CIJ","date":"2004-07-09","matiere":"Droit international public","niveau":"M2","faits":"Israël édifie un mur de séparation en territoire palestinien occupé, y compris à Jérusalem-Est.","procedure":"Avis consultatif demandé par l'Assemblée générale à la Cour internationale de Justice.","probleme":"L'édification du mur dans le territoire palestinien occupé est-elle conforme au droit international ?","solution":"Non : elle contrevient au droit international humanitaire et aux droits de l'homme, et à l'autodétermination du peuple palestinien ; la Cour rejette l'invocation de la légitime défense ; Israël doit cesser les travaux et réparer.","portee":"Rappelle l'applicabilité des droits de l'homme en territoire occupé ; la Cour affirme que le mur est contraire à des obligations erga omnes.","tags":["territoire occupé","droit humanitaire","autodétermination"],"id":"seed-jp-2004-07-09-consequences-juridiques-de-l-edification"},{"titre":"Application de la convention pour la prévention et la répression du crime de génocide (Bosnie-Herzégovine c. Serbie-et-Monténégro)","juridiction":"CIJ","date":"2007-02-26","matiere":"Droit international public","niveau":"M2","faits":"La Bosnie-Herzégovine reproche à la Serbie des actes de génocide commis pendant la guerre, notamment à Srebrenica en 1995.","procedure":"Requête devant la Cour internationale de Justice.","probleme":"La Serbie est-elle responsable de génocide ou de manquement à son obligation de prévenir et réprimer ?","solution":"La Serbie n'a pas commis ni été complice du génocide (critère du contrôle effectif non rempli) ; mais elle a violé l'obligation de prévenir le génocide de Srebrenica et celle de coopérer avec le TPIY.","portee":"Précise le critère d'attribution (contrôle effectif) et le devoir de prévenir, qui s'impose à tout État.","tags":["génocide","attribution","responsabilité de l'État"],"id":"seed-jp-2007-02-26-application-de-la-convention-pour-la-pre"},{"titre":"Usines de pâte à papier sur le fleuve Uruguay (CIJ)","juridiction":"CIJ","date":"2010-04-20","matiere":"Droit international public","niveau":"M2","faits":"L'Argentine reproche à l'Uruguay d'avoir autorisé la construction d'usines de pâte à papier sur le fleuve Uruguay sans respecter la procédure de consultation du statut de 1975.","procedure":"Requête devant la Cour internationale de Justice.","probleme":"L'Uruguay a-t-il violé ses obligations de procédure et de fond relatives à la protection du fleuve ?","solution":"L'Uruguay a violé les obligations de procédure (information, notification, négociation) mais non les obligations de fond ; l'étude d'impact sur l'environnement est une exigence du droit international général pour les activités à risque transfrontière.","portee":"Consacre la diligence requise et l'étude d'impact environnemental comme obligations coutumières.","tags":["environnement","étude d'impact","obligation de prévention"],"id":"seed-jp-2010-04-20-usines-de-pate-a-papier-sur-le-fleuve-ur"},{"titre":"Conformité au droit international de la déclaration d'indépendance du Kosovo (avis)","juridiction":"CIJ","date":"2010-07-22","matiere":"Droit international public","niveau":"M2","faits":"L'Assemblée du Kosovo proclame unilatéralement l'indépendance de la province de Serbie en 2008.","procedure":"Avis consultatif demandé par l'Assemblée générale à la Cour internationale de Justice.","probleme":"La déclaration unilatérale d'indépendance du Kosovo est-elle conforme au droit international ?","solution":"Oui : le droit international général ne contient aucune interdiction des déclarations d'indépendance ; la résolution 1244 du Conseil de sécurité ne l'interdit pas non plus ; la Cour ne se prononce pas sur le droit à la sécession.","portee":"Avis étroitement limité ; il laisse ouverte la question d'un droit à la sécession remédiatrice.","tags":["autodétermination","sécession","indépendance"],"id":"seed-jp-2010-07-22-conformite-au-droit-international-de-la-"},{"titre":"Immunités juridictionnelles de l'État (Allemagne c. Italie)","juridiction":"CIJ","date":"2012-02-03","matiere":"Droit international public","niveau":"M2","faits":"Des victimes italiennes de crimes nazis obtiennent des juges italiens la condamnation de l'Allemagne à les indemniser ; l'Allemagne saisit la Cour.","procedure":"Requête de l'Allemagne devant la Cour internationale de Justice.","probleme":"L'immunité de juridiction de l'État est-elle écartée en cas de violation grave de normes impératives (jus cogens) ?","solution":"Non : l'immunité de l'État relève des règles de procédure et ne dépend pas de la gravité de la violation ; elle reste applicable aux actes jure imperii, même en cas de violation du droit des conflits armés.","portee":"Confirme l'immunité de l'État devant les juridictions étrangères ; débat sur le conflit entre jus cogens et immunité.","tags":["immunité de l'État","jus cogens","acta jure imperii"],"id":"seed-jp-2012-02-03-immunites-juridictionnelles-de-l-etat-al"},{"titre":"Ménard (tribunal de Château-Thierry)","juridiction":"Autre","date":"1898-03-04","matiere":"Droit pénal","niveau":"L2","faits":"Une mère de famille sans travail ni ressources, dont l'enfant est affamé, vole un pain chez un boulanger.","procedure":"Poursuivie pour vol devant le tribunal correctionnel de Château-Thierry, présidé par le « bon juge » Magnaud.","probleme":"Un vol commis par nécessité pour nourrir son enfant est-il punissable ?","solution":"Non : le tribunal relaxe la prévenue, estimant que la faim est une cause de justification : le délit a été commis par une personne qui n'avait aucun autre moyen de nourrir son enfant ; il y a absence d'intention coupable.","portee":"Origine du fait justificatif d'état de nécessité, aujourd'hui consacré par l'article 122-7 du Code pénal.","tags":["état de nécessité","vol","faits justificatifs"],"id":"seed-jp-1898-03-04-menard-tribunal-de-chateau-thierry"},{"titre":"Lacour (Crim.)","juridiction":"Cour de cassation","date":"1962-10-25","matiere":"Droit pénal","niveau":"L2-L3","faits":"Un médecin projette de faire tuer son beau-fils et charge un hôtelier de l'exécution ; celui-ci, résolu dès le début à ne rien faire, feint d'accepter.","procedure":"Pourvoi de la partie civile devant la chambre criminelle de la Cour de cassation, après un arrêt qui écartait toute infraction.","probleme":"Le commanditaire d'un crime qui n'est pas exécuté peut-il être puni pour tentative ou comme complice ?","solution":"Non : fournir des renseignements sur la victime n'est qu'un acte préparatoire, non un commencement d'exécution (acte tendant directement et immédiatement au crime) ; faute de fait principal punissable, la complicité est écartée.","portee":"La lacune est comblée par la loi du 9 mars 2004, qui a créé l'article 221-5-1 du Code pénal (provocation non suivie d'effet à commettre un crime).","tags":["tentative","commencement d'exécution","complicité"],"id":"seed-jp-1962-10-25-lacour-crim"},{"titre":"Rozenblum (Crim.)","juridiction":"Cour de cassation","date":"1985-02-04","matiere":"Droit pénal","niveau":"L3-M1","faits":"Le dirigeant d'une société effectue des transferts de fonds au profit d'autres sociétés du même groupe, et est poursuivi pour abus de biens sociaux.","procedure":"Pourvoi devant la chambre criminelle de la Cour de cassation.","probleme":"Les concours financiers entre sociétés d'un même groupe constituent-ils un abus de biens sociaux ?","solution":"Non, à trois conditions : l'existence d'une structure de groupe, un intérêt économique, social ou financier commun apprécié au regard d'une politique élaborée pour l'ensemble du groupe, et un concours équilibré, sans rupture de l'équilibre des engagements respectifs, sans excéder les possibilités financières de la société qui le supporte.","portee":"Reconnaît un « fait justificatif » propre aux groupes de sociétés ; critères constamment repris par la chambre criminelle.","tags":["abus de biens sociaux","groupe de sociétés","intérêt de groupe"],"id":"seed-jp-1985-02-04-rozenblum-crim"},{"titre":"Homicide involontaire du fœtus (Ass. plén.)","juridiction":"Cour de cassation","date":"2001-06-29","matiere":"Droit pénal","niveau":"L2-L3","faits":"À la suite d'une erreur médicale, une femme enceinte de plusieurs mois perd son enfant à naître.","procedure":"Le médecin est poursuivi pour homicide involontaire ; pourvoi devant l'assemblée plénière après la cassation de la chambre criminelle.","probleme":"L'article 221-6 du Code pénal, qui réprime l'homicide involontaire d'autrui, s'applique-t-il à l'enfant à naître ?","solution":"Non : le principe de la légalité des délits et des peines, qui impose une interprétation stricte de la loi pénale, s'oppose à ce que l'incrimination d'homicide involontaire soit étendue au cas de l'enfant à naître.","portee":"Écarte la qualification d'homicide pour le fœtus ; la CEDH approuve (Vo c. France, 2004).","tags":["légalité","homicide involontaire","fœtus"],"attendu":"Le principe de la légalité des délits et des peines, qui impose une interprétation stricte de la loi pénale, s'oppose à ce que l'incrimination prévue par l'article 221-6 du Code pénal, réprimant l'homicide involontaire d'autrui, soit étendue au cas de l'enfant à naître dont le régime juridique relève de textes particuliers sur l'embryon ou le foetus.","id":"seed-jp-2001-06-29-homicide-involontaire-du-ftus-ass-plen"},{"titre":"Delcourt c. Belgique","juridiction":"CEDH","date":"1970-01-17","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un requérant se plaint de la présence du procureur général et de l'avocat général au délibéré de la Cour de cassation belge.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"L'article 6 s'applique-t-il aux procédures devant une cour de cassation et la présence du ministère public au délibéré est-elle conforme ?","solution":"Oui, l'article 6 s'applique devant la Cour de cassation ; la présence du ministère public au délibéré ne viole pas la Convention, en l'espèce.","portee":"Cet arrêt est à rapprocher des théories de l'apparence (Borgers c. Belgique, 1991) et de Kress.","tags":["procès équitable","Cour de cassation","procureur général"],"id":"seed-jp-1970-01-17-delcourt-c-belgique"},{"titre":"Golder c. Royaume-Uni","juridiction":"CEDH","date":"1975-02-21","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un détenu se voit refuser par le ministre l'autorisation de consulter un avocat en vue d'engager une action en diffamation contre un surveillant.","procedure":"Requête devant la Commission puis la Cour européenne des droits de l'homme.","probleme":"Le droit à un procès équitable (art. 6 § 1) inclut-il le droit d'accéder à un tribunal ?","solution":"Oui : l'article 6 § 1 garantit à chacun le droit de saisir un tribunal ; ce droit d'accès est un élément inhérent au droit à un procès équitable. Le refus d'autoriser la consultation d'un avocat y porte atteinte.","portee":"Arrêt fondateur du droit d'accès à un tribunal ; la Cour y recourt aux principes d'interprétation du droit des traités.","tags":["procès équitable","accès au juge","article 6"],"id":"seed-jp-1975-02-21-golder-c-royaume-uni"},{"titre":"Engel c. Pays-Bas","juridiction":"CEDH","date":"1976-06-08","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Des militaires néerlandais subissent des sanctions disciplinaires (arrêts) prononcées sans les garanties d'un procès pénal.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une sanction disciplinaire relève-t-elle de la « matière pénale » au sens de l'article 6 ?","solution":"Oui, selon trois critères : la qualification en droit interne, la nature de l'infraction et le degré de sévérité de la sanction. Une sanction privative de liberté est en principe pénale.","portee":"Critères « Engel » de la matière pénale, appliqués aux sanctions administratives (v. aussi Öztürk, 1984) et fiscales.","tags":["matière pénale","sanctions disciplinaires","article 6"],"id":"seed-jp-1976-06-08-engel-c-pays-bas"},{"titre":"Handyside c. Royaume-Uni","juridiction":"CEDH","date":"1976-12-07","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un éditeur est condamné pour avoir publié un manuel scolaire sur la sexualité jugé obscène.","procedure":"Requête devant la Cour européenne des droits de l'homme, qui dégage la notion de marge nationale d'appréciation.","probleme":"La condamnation pour obscénité d'un livre portant sur la sexualité est-elle compatible avec la liberté d'expression ?","solution":"Oui : les autorités nationales, mieux placées pour apprécier les exigences de la morale, disposent d'une marge d'appréciation ; la liberté d'expression vaut aussi pour les idées qui heurtent, choquent ou inquiètent, mais l'ingérence est ici nécessaire dans une société démocratique (art. 10 § 2).","portee":"Pose la formule sur « les idées qui heurtent, choquent ou inquiètent » et la marge d'appréciation, thèmes constants de l'article 10.","tags":["liberté d'expression","marge d'appréciation","morale"],"id":"seed-jp-1976-12-07-handyside-c-royaume-uni"},{"titre":"Tyrer c. Royaume-Uni","juridiction":"CEDH","date":"1978-04-25","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un adolescent est condamné à des coups de verge dans l'île de Man.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une peine corporelle judiciaire est-elle un traitement dégradant ?","solution":"Oui : les châtiments corporels sont un traitement dégradant (art. 3) ; la Convention est un instrument vivant, à interpréter à la lumière des conditions de vie actuelles.","portee":"Fonde l'interprétation évolutive de la Convention.","tags":["article 3","peines corporelles","instrument vivant"],"id":"seed-jp-1978-04-25-tyrer-c-royaume-uni"},{"titre":"Sunday Times c. Royaume-Uni","juridiction":"CEDH","date":"1979-04-26","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un journal est empêché de publier des articles sur des médicaments à l'origine de malformations, au nom de l'autorité de la justice.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"À quelles conditions une ingérence dans la liberté d'expression est-elle justifiée ?","solution":"Elle doit être prévue par la loi (norme accessible et prévisible), poursuivre un but légitime et être nécessaire dans une société démocratique ; ici l'interdiction ne répond pas à un besoin social impérieux.","portee":"Définit les trois critères du contrôle des restrictions aux droits (légalité, but légitime, proportionnalité).","tags":["liberté d'expression","légalité","ingérence"],"id":"seed-jp-1979-04-26-sunday-times-c-royaume-uni"},{"titre":"Marckx c. Belgique","juridiction":"CEDH","date":"1979-06-13","matiere":"Libertés fondamentales et CEDH","niveau":"L2-L3","faits":"Une mère célibataire et sa fille se plaignent des règles belges qui limitent les droits successoraux et la reconnaissance juridique de la filiation maternelle hors mariage.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Les discriminations successorales et familiales à l'égard des enfants nés hors mariage sont-elles compatibles avec la Convention ?","solution":"Non : la distinction entre enfants légitimes et naturels, en matière de filiation et de succession, viole l'article 8 combiné avec l'article 14 ; l'article 8 impose des obligations positives de protéger la vie familiale.","portee":"Fonde l'égalité des filiations ; il a inspiré les réformes françaises (loi du 3 janvier 1972, puis l'ordonnance de 2005).","tags":["filiation","enfant naturel","vie familiale"],"id":"seed-jp-1979-06-13-marckx-c-belgique"},{"titre":"Airey c. Irlande","juridiction":"CEDH","date":"1979-10-09","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Une femme sans ressources veut obtenir une séparation de corps mais ne peut pas se faire assister d'un avocat, faute d'aide judiciaire en Irlande.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"L'État doit-il assurer une aide judiciaire quand l'accès effectif au juge l'exige ?","solution":"Oui : la Convention vise à protéger des droits non pas théoriques ou illusoires, mais concrets et effectifs ; l'absence d'assistance d'un avocat a privé la requérante d'un accès effectif au juge (art. 6 § 1).","portee":"Consacre la notion de droits « concrets et effectifs » et des obligations positives de l'État.","tags":["accès au juge","aide juridictionnelle","droits effectifs"],"id":"seed-jp-1979-10-09-airey-c-irlande"},{"titre":"Dudgeon c. Royaume-Uni","juridiction":"CEDH","date":"1981-10-22","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un homme se plaint de la pénalisation des actes homosexuels entre adultes consentants en Irlande du Nord.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"La pénalisation de l'homosexualité entre adultes consentants viole-t-elle le droit au respect de la vie privée ?","solution":"Oui : la législation est disproportionnée au regard du but poursuivi ; la pénalisation de comportements privés relève du domaine le plus intime de la vie privée.","portee":"Fonde la dépénalisation en Europe ; base de la jurisprudence sur l'orientation sexuelle.","tags":["homosexualité","vie privée","article 8"],"id":"seed-jp-1981-10-22-dudgeon-c-royaume-uni"},{"titre":"Sporrong et Lönnroth c. Suède","juridiction":"CEDH","date":"1982-09-23","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Des propriétaires voient leurs terrains grevés pendant plus de vingt ans par des permis d'exproprier à Stockholm, sans pouvoir en disposer.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"À quelles conditions une ingérence dans le droit de propriété est-elle conforme à la Convention ?","solution":"L'ingérence doit ménager un juste équilibre entre l'intérêt général et les droits fondamentaux de l'individu ; en l'espèce, les requérants ont supporté une charge spéciale et exorbitante.","portee":"Pose les trois normes de l'article 1er du Protocole n° 1 (principe, privation, réglementation) et le test du juste équilibre.","tags":["propriété","juste équilibre","expropriation"],"id":"seed-jp-1982-09-23-sporrong-et-lonnroth-c-suede"},{"titre":"Piersack c. Belgique","juridiction":"CEDH","date":"1982-10-01","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un magistrat qui avait dirigé le parquet dans une affaire préside ensuite la cour d'assises qui juge l'accusé.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"L'impartialité d'un tribunal s'apprécie-t-elle seulement subjectivement ?","solution":"Non : l'impartialité s'apprécie de façon subjective (conviction personnelle du juge) et objective (garanties suffisantes pour exclure tout doute légitime) ; l'apparence compte (« justice must be seen to be done »).","portee":"Théorie des apparences ; voir De Cubber c. Belgique (1984) pour le cumul de fonctions d'instruction et de jugement.","tags":["impartialité","théorie des apparences","tribunal"],"id":"seed-jp-1982-10-01-piersack-c-belgique"},{"titre":"Öztürk c. Allemagne","juridiction":"CEDH","date":"1984-02-21","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un conducteur turc condamné pour une infraction routière réclame le remboursement des frais d'interprète, mettant en cause la nature de l'infraction.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une infraction « dépénalisée » en droit interne relève-t-elle de l'accusation en matière pénale de l'article 6 ?","solution":"Oui : les critères Engel s'appliquent ; la nature générale de la règle et le but de la sanction (dissuasif et répressif) donnent à l'infraction un caractère pénal, malgré sa qualification administrative.","portee":"Étend la notion de matière pénale aux contraventions et sanctions administratives (voir Bendenoun c. France, 1994).","tags":["matière pénale","contraventions","interprète"],"id":"seed-jp-1984-02-21-ozturk-c-allemagne"},{"titre":"De Cubber c. Belgique","juridiction":"CEDH","date":"1984-10-26","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un juge d'instruction siège ensuite dans la formation de jugement qui connaît de la même affaire.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Le juge d'instruction peut-il ensuite juger la même affaire ?","solution":"Non : le cumul des fonctions d'instruction et de jugement fait naître un doute objectivement justifié sur l'impartialité du tribunal ; violation de l'article 6 § 1.","portee":"Impose des règles d'incompatibilité entre instruction et jugement en procédure pénale.","tags":["impartialité","juge d'instruction","apparence"],"id":"seed-jp-1984-10-26-de-cubber-c-belgique"},{"titre":"James et autres c. Royaume-Uni","juridiction":"CEDH","date":"1986-02-21","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Les administrateurs (trustees) du patrimoine du duc de Westminster contestent la loi de 1967 qui permet aux locataires de longue durée d'acquérir obligatoirement leur logement, à un prix fixé par la loi.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une privation de propriété au profit d'un particulier, pour réaliser une politique sociale, peut-elle être d'utilité publique ?","solution":"Oui : une privation de propriété peut répondre à l'intérêt général même si elle bénéficie à des particuliers ; le législateur dispose d'une ample marge d'appréciation ; le juste équilibre n'est pas rompu.","portee":"Admet la privation de propriété au profit d'intérêts privés, dès lors qu'une politique sociale la justifie.","tags":["propriété","utilité publique","réforme sociale"],"id":"seed-jp-1986-02-21-james-et-autres-c-royaume-uni"},{"titre":"Salabiaku c. France","juridiction":"CEDH","date":"1988-10-07","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Un homme est condamné pour contrebande de stupéfiants sur le fondement d'une présomption légale de responsabilité du détenteur de marchandises prohibées.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Les présomptions de fait ou de droit en droit pénal sont-elles compatibles avec la présomption d'innocence ?","solution":"Oui, à condition de rester dans des limites raisonnables, qui prennent en compte la gravité de l'enjeu et préservent les droits de la défense ; en l'espèce, le juge a préservé la possibilité de prouver l'absence de faute.","portee":"Admet les présomptions légales en droit pénal sous un contrôle de proportionnalité (confirmé par Janosevic c. Suède, 2002).","tags":["présomption de culpabilité","douane","article 6 § 2"],"id":"seed-jp-1988-10-07-salabiaku-c-france"},{"titre":"Soering c. Royaume-Uni","juridiction":"CEDH","date":"1989-07-07","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Un ressortissant allemand, accusé de meurtre aux États-Unis, risque une condamnation à mort et d'attendre plusieurs années dans le « couloir de la mort » s'il est extradé depuis le Royaume-Uni.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Un État peut-il extrader une personne vers un pays où elle risque des traitements contraires à l'article 3 ?","solution":"Non : la responsabilité d'un État peut être engagée lorsqu'il extrade une personne qui court un risque réel de subir des traitements inhumains ou dégradants ; le syndrome du couloir de la mort relève de l'article 3.","portee":"Fonde la protection par ricochet contre l'éloignement (extradition, expulsion) ; reprise pour le refoulement (Hirsi Jamaa).","tags":["extradition","article 3","peine de mort"],"id":"seed-jp-1989-07-07-soering-c-royaume-uni"},{"titre":"Kruslin et Huvig c. France","juridiction":"CEDH","date":"1990-04-24","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Des conversations téléphoniques sont interceptées sur commission rogatoire dans des procédures pénales, sans loi précise encadrant l'écoute.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une ingérence dans la vie privée fondée sur la jurisprudence de droit interne est-elle « prévue par la loi » ?","solution":"La « loi » s'entend de la loi au sens matériel, y compris la jurisprudence, mais elle doit être accessible et prévisible et définir avec précision les garanties ; le droit français ne le faisait pas : violation de l'article 8.","portee":"A conduit à la loi du 10 juillet 1991 sur les interceptions de communications.","tags":["écoutes téléphoniques","légalité","vie privée"],"id":"seed-jp-1990-04-24-kruslin-et-huvig-c-france"},{"titre":"Borgers c. Belgique","juridiction":"CEDH","date":"1991-10-30","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un justiciable se plaint de ce que le procureur général près la Cour de cassation belge ait présenté des conclusions sans qu'il puisse y répondre, et soit présent au délibéré.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"L'intervention du ministère public devant la Cour de cassation est-elle conforme à l'égalité des armes ?","solution":"Non : la non-communication des conclusions du parquet à la défense, et la présence du ministère public au délibéré, portent atteinte au procès équitable ; les apparences comptent.","portee":"Revirement par rapport à Delcourt (1970) ; inspire le droit français (avocats généraux, rapporteur public).","tags":["égalité des armes","ministère public","apparences"],"id":"seed-jp-1991-10-30-borgers-c-belgique"},{"titre":"Funke c. France","juridiction":"CEDH","date":"1993-02-25","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Une personne est condamnée pour avoir refusé de remettre aux douanes des relevés bancaires étrangers dont elles réclamaient la production.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Peut-on contraindre quelqu'un à produire des documents qui permettraient de l'incriminer ?","solution":"Non : le droit de tout accusé, au sens autonome de l'article 6, de se taire et de ne pas contribuer à sa propre incrimination est méconnu par la condamnation pour refus de fournir des preuves contre soi.","portee":"Première reconnaissance du droit de ne pas s'auto-incriminer ; développé par Saunders c. Royaume-Uni (1996).","tags":["droit de se taire","auto-incrimination","douane"],"id":"seed-jp-1993-02-25-funke-c-france"},{"titre":"Kokkinakis c. Grèce","juridiction":"CEDH","date":"1993-05-25","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un témoin de Jéhovah est condamné pour prosélytisme pour avoir tenté de convertir l'épouse d'un chantre orthodoxe.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"La condamnation pour prosélytisme est-elle compatible avec l'article 9 ?","solution":"Non, car la condamnation ne repose pas sur un besoin social impérieux : le prosélytisme abusif se distingue du témoignage chrétien ; la liberté de manifester sa religion inclut le droit d'essayer de convaincre autrui.","portee":"Première condamnation d'un État pour violation de l'article 9.","tags":["liberté de religion","prosélytisme","légalité pénale"],"id":"seed-jp-1993-05-25-kokkinakis-c-grece"},{"titre":"Bendenoun c. France","juridiction":"CEDH","date":"1994-02-24","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un commerçant est condamné à des majorations fiscales importantes pour fraude ; il invoque l'absence de garanties pénales.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Les pénalités fiscales sont-elles des sanctions de nature pénale au sens de l'article 6 ?","solution":"Oui : en raison du caractère général de la loi fiscale, du but dissuasif et répressif des majorations et de leur importance, les pénalités fiscales relèvent de la matière pénale.","portee":"Soumet les sanctions fiscales aux garanties de l'article 6 ; étend le non bis in idem fiscal-pénal.","tags":["sanctions fiscales","matière pénale","article 6"],"id":"seed-jp-1994-02-24-bendenoun-c-france"},{"titre":"Hentrich c. France","juridiction":"CEDH","date":"1994-09-22","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"L'administration fiscale exerce son droit de préemption, au prix déclaré, sur un terrain que la requérante venait d'acquérir.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"L'exercice du droit de préemption de l'administration, sélectif, est-il proportionné ?","solution":"Non : le droit de préemption, appliqué de façon arbitraire et sélective et sans contrôle juridictionnel effectif, a fait peser sur la requérante une charge excessive ; violation de l'article 1er du Protocole n° 1.","portee":"Contribue à rendre plus rigoureux le contrôle de la proportionnalité en matière de propriété.","tags":["préemption","propriété","arbitraire"],"id":"seed-jp-1994-09-22-hentrich-c-france"},{"titre":"Stran Greek Refineries c. Grèce","juridiction":"CEDH","date":"1994-12-09","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Une société qui détenait une sentence arbitrale contre l'État grec voit son droit annulé par une loi adoptée en cours de procédure.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une loi peut-elle annuler une créance reconnue par une sentence arbitrale en faveur d'une société ?","solution":"Non : l'intervention du législateur, qui annule rétroactivement la créance de la société, viole l'article 6 § 1 et le droit au respect des biens (art. 1er du Protocole n° 1).","portee":"Premier arrêt majeur sur les validations législatives rétroactives.","tags":["validation législative","propriété","procès équitable"],"id":"seed-jp-1994-12-09-stran-greek-refineries-c-grece"},{"titre":"López Ostra c. Espagne","juridiction":"CEDH","date":"1994-12-09","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Une habitante de Lorca subit les émanations d'une station d'épuration de tanneries construite près de chez elle ; les autorités n'agissent pas.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une atteinte grave à l'environnement peut-elle violer le droit au respect du domicile et de la vie privée ?","solution":"Oui : des atteintes graves à l'environnement peuvent affecter le bien-être d'une personne et la priver de la jouissance de son domicile, sans pour autant mettre sa santé en danger ; l'article 8 est violé.","portee":"Première affaire environnementale devant la Cour ; ouvre la jurisprudence environnementale de l'article 8.","tags":["environnement","article 8","pollution"],"id":"seed-jp-1994-12-09-lopez-ostra-c-espagne"},{"titre":"Allenet de Ribemont c. France","juridiction":"CEDH","date":"1995-02-10","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Lors d'une conférence de presse, le ministre de l'Intérieur et des policiers désignent publiquement une personne comme instigatrice d'un assassinat, avant toute décision judiciaire.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"La présomption d'innocence peut-elle être violée par les déclarations d'autorités publiques ?","solution":"Oui : la présomption d'innocence peut être violée non seulement par un magistrat ou un tribunal, mais aussi par d'autres autorités publiques ; la présentation publique comme coupable, avant jugement, y porte atteinte.","portee":"Étend la protection de la présomption d'innocence à l'ensemble des autorités publiques ; Cour de cassation et loi du 15 juin 2000.","tags":["présomption d'innocence","déclarations de ministre","article 6 § 2"],"id":"seed-jp-1995-02-10-allenet-de-ribemont-c-france"},{"titre":"Loizidou c. Turquie (exceptions préliminaires)","juridiction":"CEDH","date":"1995-03-23","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Une Chypriote grecque se plaint de ne pouvoir accéder à ses biens dans le nord de Chypre, occupé par la Turquie.","procedure":"Requête devant la Cour européenne des droits de l'homme ; la Turquie soulève des exceptions préliminaires.","probleme":"Un État est-il responsable des violations commises dans une zone qu'il contrôle effectivement hors de son territoire ?","solution":"Oui : la responsabilité d'un État peut être engagée à raison d'actes de ses autorités accomplis ou produisant des effets en dehors de son territoire, lorsqu'il exerce un contrôle effectif sur une zone ; la Cour rejette les réserves territoriales.","portee":"Fondement du critère du contrôle effectif ; précisé par Al-Skeini c. Royaume-Uni (2011).","tags":["juridiction extraterritoriale","contrôle effectif","Chypre"],"id":"seed-jp-1995-03-23-loizidou-c-turquie-exceptions-preliminai"},{"titre":"Saunders c. Royaume-Uni (GC)","juridiction":"CEDH","date":"1996-12-17","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un dirigeant est contraint de répondre aux enquêteurs du ministère du Commerce ; ses déclarations sont ensuite utilisées contre lui au pénal.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Des déclarations obtenues sous la contrainte légale peuvent-elles être utilisées dans le procès pénal ?","solution":"Non : le droit de ne pas s'incriminer soi-même suppose que l'accusation ne puisse fonder sa preuve sur des éléments obtenus par contrainte au mépris de la volonté de l'accusé ; l'utilisation des déclarations viole l'article 6.","portee":"Précise le champ du droit de se taire : il vise l'utilisation des déclarations au procès, pas leur obtention.","tags":["auto-incrimination","procédure d'enquête","utilisation des déclarations"],"id":"seed-jp-1996-12-17-saunders-c-royaume-uni-gc"},{"titre":"Hornsby c. Grèce","juridiction":"CEDH","date":"1997-03-19","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un couple de ressortissants britanniques, qui veut ouvrir une école de langue anglaise à Rhodes, obtient de la justice grecque l'annulation du refus d'autorisation mais ne parvient pas à faire exécuter les décisions par l'administration.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"L'exécution d'une décision de justice fait-elle partie du procès au sens de l'article 6 ?","solution":"Oui : le droit à un tribunal serait illusoire si l'ordre juridique interne permettait qu'une décision judiciaire définitive et obligatoire reste inopérante au détriment d'une partie ; l'exécution fait partie intégrante du procès.","portee":"Le droit à l'exécution des jugements est une composante du droit au juge ; il inspire la loi du 8 février 1995 sur les injonctions.","tags":["exécution des décisions de justice","droit au juge"],"id":"seed-jp-1997-03-19-hornsby-c-grece"},{"titre":"Teixeira de Castro c. Portugal","juridiction":"CEDH","date":"1998-06-09","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Des policiers poussent un individu à vendre de l'héroïne pour le faire arrêter, alors qu'il n'avait aucun antécédent.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"La provocation policière viole-t-elle le droit à un procès équitable ?","solution":"Oui : l'intervention des agents a dépassé celle d'agents infiltrés ; ils ont incité à commettre l'infraction, et les preuves recueillies ne peuvent fonder la condamnation sans priver l'accusé d'un procès équitable.","portee":"Fondement de la loyauté de la preuve pénale ; voir Cass. crim., 27 févr. 1996, Schuller-Maréchal.","tags":["provocation policière","loyauté de la preuve","article 6"],"id":"seed-jp-1998-06-09-teixeira-de-castro-c-portugal"},{"titre":"Matthews c. Royaume-Uni (GC)","juridiction":"CEDH","date":"1999-02-18","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Une habitante de Gibraltar ne peut pas voter aux élections du Parlement européen, le droit communautaire ayant exclu Gibraltar.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Un État peut-il échapper à sa responsabilité en transférant des compétences à l'Union ?","solution":"Non : les États restent responsables au titre de la Convention des conséquences des traités qu'ils concluent ; le Royaume-Uni a violé l'article 3 du Protocole n° 1 en privant la requérante du droit de vote.","portee":"Établit la responsabilité des États pour les actes d'organisations internationales qu'ils ont souscrits.","tags":["droit de vote","Parlement européen","Gibraltar"],"id":"seed-jp-1999-02-18-matthews-c-royaume-uni-gc"},{"titre":"Chassagnou c. France (GC)","juridiction":"CEDH","date":"1999-04-29","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Des propriétaires, opposés à la chasse, sont contraints par la loi Verdeille d'adhérer à une association communale de chasse et d'y apporter leurs terrains.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'obligation d'apporter ses terrains à une association de chasse et d'y adhérer est-elle conforme à la Convention ?","solution":"Non : elle est contraire à la liberté d'association (art. 11) et au droit de propriété (art. 1er du Protocole n° 1) ; le droit de ne pas s'associer est la face négative de la liberté d'association.","portee":"Condamne la loi Verdeille ; consacre la liberté d'association négative.","tags":["chasse","association forcée","propriété"],"id":"seed-jp-1999-04-29-chassagnou-c-france-gc"},{"titre":"Selmouni c. France","juridiction":"CEDH","date":"1999-07-28","matiere":"Libertés fondamentales et CEDH","niveau":"L3","faits":"Un homme interpellé dans le cadre d'une enquête sur un trafic de stupéfiants subit des violences graves durant sa garde à vue.","procedure":"Requête devant la Cour européenne des droits de l'homme, Grande chambre.","probleme":"Les mauvais traitements infligés lors d'une garde à vue peuvent-ils être qualifiés de torture ?","solution":"Oui : l'intensité et la gravité des violences atteignent le seuil de la torture ; ce qui n'était qualifié que de traitement inhumain l'est désormais de torture, en raison de l'élévation des exigences de protection des droits de l'homme.","portee":"Condamne la France pour torture ; montre l'évolution des standards de l'article 3.","tags":["torture","garde à vue","article 3"],"id":"seed-jp-1999-07-28-selmouni-c-france"},{"titre":"Zielinski, Pradal et Gonzalez c. France (GC)","juridiction":"CEDH","date":"1999-10-28","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Une loi de validation rétroactive intervient pendant un litige opposant des salariés à un organisme de sécurité sociale, pour régler le contentieux en faveur de l'employeur.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le législateur peut-il intervenir dans une procédure en cours pour en régler l'issue ?","solution":"Non, sauf motifs impérieux d'intérêt général : l'ingérence du pouvoir législatif dans l'administration de la justice, pour influer sur l'issue d'un litige, viole le principe du procès équitable (art. 6 § 1).","portee":"Encadre les lois de validation ; v. aussi Stran Greek Refineries (1994) et Draon (2005).","tags":["validation législative","procès équitable","article 6"],"id":"seed-jp-1999-10-28-zielinski-pradal-et-gonzalez-c-france-gc"},{"titre":"Pellegrin c. France (GC)","juridiction":"CEDH","date":"1999-12-08","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un ressortissant français, recruté par le ministère de la Coopération comme conseiller technique auprès d'un ministre de Guinée équatoriale, conteste la fin de son contrat et la procédure qui a suivi.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Les litiges de fonction publique relèvent-ils de l'article 6 ?","solution":"Non, en principe : la Cour retient un critère fonctionnel : sont exclus les litiges relatifs aux agents qui exercent des prérogatives de puissance publique et assurent la sauvegarde des intérêts généraux de l'État.","portee":"Critère fonctionnel abandonné par Vilho Eskelinen c. Finlande (GC, 19 avril 2007), qui rend l'article 6 applicable sauf exclusion expresse justifiée.","tags":["fonction publique","article 6","critère fonctionnel"],"id":"seed-jp-1999-12-08-pellegrin-c-france-gc"},{"titre":"Mazurek c. France","juridiction":"CEDH","date":"2000-02-01","matiere":"Libertés fondamentales et CEDH","niveau":"L2-L3","faits":"Un enfant adultérin, appelé à la succession de sa mère en concours avec un enfant légitime, ne reçoit que la moitié de la part qui lui serait revenue s'il avait été légitime.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Une différence de traitement successorale selon l'origine de la naissance viole-t-elle la Convention ?","solution":"Oui : la différence de traitement entre enfants adultérins et enfants légitimes dans le partage successoral est une discrimination (art. 14 combiné à l'article 1er du Protocole n° 1) car seul le comportement des parents en est la cause.","portee":"A conduit la loi du 3 décembre 2001 à supprimer toute discrimination successorale selon la naissance.","tags":["filiation","succession","enfant adultérin"],"id":"seed-jp-2000-02-01-mazurek-c-france"},{"titre":"Maaouia c. France (GC)","juridiction":"CEDH","date":"2000-10-05","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un étranger demande le relèvement de l'interdiction du territoire, estimant la procédure trop longue.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'article 6 s'applique-t-il aux procédures d'éloignement des étrangers ?","solution":"Non : les décisions relatives à l'entrée, au séjour et à l'éloignement des étrangers ne portent pas sur des droits ou obligations de caractère civil ni sur une accusation pénale.","portee":"Écarte l'article 6 pour le contentieux des étrangers ; l'article 13 et l'article 3 restent applicables.","tags":["étrangers","expulsion","article 6","matière civile"],"id":"seed-jp-2000-10-05-maaouia-c-france-gc"},{"titre":"Kudla c. Pologne (GC)","juridiction":"CEDH","date":"2000-10-26","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un détenu se plaint de la durée de sa détention provisoire et de l'absence de recours pour s'en prévaloir.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'article 13 garantit-il un recours interne effectif en cas de violation du délai raisonnable ?","solution":"Oui : l'article 13 impose un recours effectif contre la violation du droit à être jugé dans un délai raisonnable ; il y a violation si l'État n'en offre pas.","portee":"A conduit les États, dont la France (loi du 30 juin 2000 puis jurisprudence Magiera), à créer des recours indemnitaires pour durée excessive.","tags":["recours effectif","article 13","durée de la procédure"],"id":"seed-jp-2000-10-26-kudla-c-pologne-gc"},{"titre":"Kress c. France (GC)","juridiction":"CEDH","date":"2001-06-07","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Une requérante conteste, devant le Conseil d'État, la présence du commissaire du gouvernement lors du délibéré et l'absence de communication préalable de ses conclusions.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le rôle du commissaire du gouvernement dans la procédure administrative est-il compatible avec le procès équitable ?","solution":"La présence du commissaire du gouvernement au délibéré porte atteinte à l'exigence d'un procès équitable (apparence d'impartialité et égalité des armes) ; il n'y a pas de violation pour l'absence de communication préalable des conclusions.","portee":"A provoqué la réforme du décret du 1er août 2006 : le commissaire du gouvernement devient le rapporteur public, qui n'assiste plus au délibéré.","tags":["commissaire du gouvernement","égalité des armes","procès équitable"],"id":"seed-jp-2001-06-07-kress-c-france-gc"},{"titre":"Ferrazzini c. Italie (GC)","juridiction":"CEDH","date":"2001-07-12","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un contribuable se plaint de la durée d'une procédure fiscale devant la justice italienne.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Les litiges fiscaux relèvent-ils du champ de l'article 6 (droits et obligations de caractère civil) ?","solution":"Non : le contentieux fiscal échappe au domaine des droits et obligations de caractère civil, car les relations entre l'individu et l'État y conservent un caractère prépondérant de droit public ; l'article 6 ne s'applique que s'il y a accusation pénale.","portee":"Écarte l'article 6 pour le contentieux fiscal pur ; l'accusation pénale reste le critère (Bendenoun).","tags":["contentieux fiscal","article 6","droits civils"],"id":"seed-jp-2001-07-12-ferrazzini-c-italie-gc"},{"titre":"Pretty c. Royaume-Uni","juridiction":"CEDH","date":"2002-04-29","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une femme atteinte d'une maladie dégénérative incurable demande l'assurance que son mari ne sera pas poursuivi s'il l'aide à mourir.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Le droit à la vie implique-t-il un droit de mourir et un droit au suicide assisté ?","solution":"Non : l'article 2 ne confère pas de droit à mourir ; l'interdiction du suicide assisté constitue une ingérence dans la vie privée (art. 8) mais elle est justifiée.","portee":"Rejette un droit à l'euthanasie ; la marge d'appréciation des États est large sur ces questions (Lambert, 2015).","tags":["fin de vie","suicide assisté","article 2"],"id":"seed-jp-2002-04-29-pretty-c-royaume-uni"},{"titre":"Goodwin c. Royaume-Uni (GC)","juridiction":"CEDH","date":"2002-07-11","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une personne transsexuelle ne peut pas faire modifier son état civil ni se marier avec une personne de son sexe d'origine au Royaume-Uni.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le refus de reconnaître juridiquement le nouveau sexe viole-t-il l'article 8 et le droit de se marier ?","solution":"Oui : l'État ne peut plus invoquer sa marge d'appréciation face au consensus qui se dégage en faveur de la reconnaissance juridique du sexe ; violation des articles 8 et 12.","portee":"Renverse la jurisprudence Cossey et Rees ; aligne le droit britannique.","tags":["transsexualisme","état civil","mariage"],"id":"seed-jp-2002-07-11-goodwin-c-royaume-uni-gc"},{"titre":"Odièvre c. France (GC)","juridiction":"CEDH","date":"2003-02-13","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une femme née sous X, adoptée, ne peut pas obtenir l'identité de sa mère biologique.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le secret de l'accouchement sous X porte-t-il atteinte au droit de connaître ses origines ?","solution":"Non : l'État dispose d'une marge d'appréciation ; la loi du 22 janvier 2002 (CNAOP) ménage un juste équilibre entre l'intérêt de l'enfant et celui de la mère, tenue à l'anonymat ; l'article 8 n'est pas violé.","portee":"Valide l'accouchement sous X ; l'évolution du droit à connaître ses origines se poursuit (loi de bioéthique de 2021).","tags":["accouchement sous X","origines","vie privée"],"id":"seed-jp-2003-02-13-odievre-c-france-gc"},{"titre":"Hatton c. Royaume-Uni (GC)","juridiction":"CEDH","date":"2003-07-08","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Des riverains de l'aéroport d'Heathrow se plaignent des nuisances sonores dues à l'augmentation des vols de nuit.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Les nuisances environnementales peuvent-elles violer l'article 8 ?","solution":"L'article 8 peut être invoqué pour des nuisances graves ; mais l'État dispose d'une marge d'appréciation et a ménagé un juste équilibre entre les intérêts économiques du pays et ceux des riverains : pas de violation de l'article 8 (la chambre en avait jugé autrement en 2001). La Grande chambre constate toutefois une violation de l'article 13, le contrôle juridictionnel étant trop limité.","portee":"Reconnaît un droit à un environnement sain par ricochet, après López Ostra c. Espagne (1994).","tags":["nuisances sonores","environnement","vie privée"],"id":"seed-jp-2003-07-08-hatton-c-royaume-uni-gc"},{"titre":"Von Hannover c. Allemagne (n° 1)","juridiction":"CEDH","date":"2004-06-24","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"La princesse Caroline de Monaco se plaint de la publication de photographies de sa vie quotidienne par la presse à sensation.","procedure":"Requête devant la Cour européenne des droits de l'homme, après le rejet des juridictions allemandes.","probleme":"Comment concilier la liberté de la presse et la protection de la vie privée des personnes publiques ?","solution":"La publication de photographies relevant de la vie privée sans contribution à un débat d'intérêt général viole l'article 8 ; la protection de la vie privée de la personne publique l'emporte lorsque les images ne servent pas l'intérêt général.","portee":"Pose les critères de mise en balance entre articles 8 et 10 (contribution à un débat d'intérêt général, notoriété, comportement antérieur).","tags":["vie privée","presse","figures publiques"],"id":"seed-jp-2004-06-24-von-hannover-c-allemagne-n-1"},{"titre":"Vo c. France (GC)","juridiction":"CEDH","date":"2004-07-08","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une femme enceinte de six mois perd son enfant à la suite d'une erreur médicale et ne peut obtenir la condamnation du médecin pour homicide involontaire.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le droit à la vie (art. 2) protège-t-il l'enfant à naître, au point d'exiger une sanction pénale ?","solution":"Non : la question du début de la vie relève de la marge d'appréciation des États ; il n'y a pas de violation de l'article 2 puisque des voies de recours (faute médicale, responsabilité) existaient.","portee":"Évite de qualifier le fœtus de « personne » au sens de l'article 2 ; corrèle avec Cass. ass. plén., 29 juin 2001.","tags":["droit à la vie","embryon","homicide involontaire"],"id":"seed-jp-2004-07-08-vo-c-france-gc"},{"titre":"Mamatkulov et Askarov c. Turquie (GC)","juridiction":"CEDH","date":"2005-02-04","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Deux ressortissants ouzbeks sont extradés vers l'Ouzbékistan malgré l'indication de mesures provisoires par la Cour.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Les mesures provisoires indiquées par la Cour sont-elles obligatoires ?","solution":"Oui : l'inobservation de mesures provisoires par un État partie, qui empêche la Cour d'examiner efficacement la requête, constitue une violation de l'article 34 (droit de recours individuel).","portee":"Revirement par rapport à Cruz Varas (1991) : la Cour reconnaît le caractère obligatoire des mesures provisoires.","tags":["mesures provisoires","force obligatoire","recours individuel"],"id":"seed-jp-2005-02-04-mamatkulov-et-askarov-c-turquie-gc"},{"titre":"Bosphorus c. Irlande (GC)","juridiction":"CEDH","date":"2005-06-30","matiere":"Libertés fondamentales et CEDH","niveau":"M1-M2","faits":"Un avion d'une compagnie turque est saisi en Irlande en application d'un règlement européen d'embargo contre la Yougoslavie.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Un État est-il responsable devant la Cour d'un acte qui applique une obligation du droit de l'Union ?","solution":"Oui, mais avec une présomption : un État est présumé respecter la Convention lorsqu'il met en oeuvre le droit de l'Union, tant que l'Union protège les droits fondamentaux de manière équivalente ; la présomption est réfutable en cas de dysfonctionnement manifeste.","portee":"Pose la présomption de protection équivalente ; elle est relativisée par Avotiņš c. Lettonie (2016) et Michaud c. France (2012).","tags":["présomption de protection équivalente","droit de l'Union"],"id":"seed-jp-2005-06-30-bosphorus-c-irlande-gc"},{"titre":"Hirst c. Royaume-Uni (n° 2) (GC)","juridiction":"CEDH","date":"2005-10-06","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un détenu condamné pour homicide se voit priver de droit de vote par une loi interdisant le vote de tous les condamnés détenus.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Une interdiction générale et automatique du droit de vote des détenus est-elle compatible avec l'article 3 du Protocole n° 1 ?","solution":"Non : une restriction générale, automatique et indifférenciée du droit de vote des détenus n'est pas proportionnée ; elle ne tient pas compte de la gravité de l'infraction.","portee":"Illustre le contrôle de proportionnalité sur les restrictions au droit de vote (voir Frodl c. Autriche, 2010).","tags":["droit de vote","détenus","proportionnalité"],"id":"seed-jp-2005-10-06-hirst-c-royaume-uni-n-2-gc"},{"titre":"Maurice et Draon c. France (GC)","juridiction":"CEDH","date":"2005-10-06","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Des parents d'enfants nés handicapés après une erreur médicale se voient privés, par la loi du 4 mars 2002, d'une créance de réparation que la jurisprudence Perruche leur reconnaissait.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"La loi qui prive de créances en cours d'action en justice est-elle compatible avec le droit au respect des biens ?","solution":"Non : l'application rétroactive de la loi du 4 mars 2002 aux instances en cours viole l'article 1er du Protocole n° 1 : les requérants avaient une espérance légitime et ont supporté une charge disproportionnée.","portee":"Restreint les lois rétroactives ; le législateur a dû adapter l'effet de la loi en 2005.","tags":["loi anti-Perruche","validation législative","biens"],"id":"seed-jp-2005-10-06-maurice-et-draon-c-france-gc"},{"titre":"Leyla Sahin c. Turquie (GC)","juridiction":"CEDH","date":"2005-11-10","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une étudiante en médecine à l'université d'Istanbul est exclue pour avoir porté le foulard islamique contrairement au règlement.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'interdiction du port du foulard à l'université est-elle contraire à la liberté de religion ?","solution":"Non : l'ingérence, prévue par la loi, vise la laïcité et l'égalité des sexes, buts légitimes ; elle est justifiée dans le contexte turc, au titre de la marge d'appréciation.","portee":"Illustre le contrôle de la proportionnalité en matière de signes religieux.","tags":["voile","université","laïcité"],"id":"seed-jp-2005-11-10-leyla-sahin-c-turquie-gc"},{"titre":"Jussila c. Finlande (GC)","juridiction":"CEDH","date":"2006-11-23","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Un contribuable se voit infliger une majoration d'impôt et ne bénéficie pas d'une audience orale devant la juridiction administrative.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Les garanties de l'article 6 s'appliquent-elles avec la même rigueur à toutes les infractions de nature pénale ?","solution":"Les majorations fiscales relèvent de la matière pénale mais pas du « noyau dur » : les garanties de l'article 6 peuvent s'y appliquer avec moins de rigueur ; l'absence d'audience orale n'a pas ici violé l'article 6.","portee":"Distingue le noyau dur du droit pénal et les infractions « pénales » plus légères.","tags":["sanctions fiscales","matière pénale","noyau dur"],"id":"seed-jp-2006-11-23-jussila-c-finlande-gc"},{"titre":"Evans c. Royaume-Uni (GC)","juridiction":"CEDH","date":"2007-04-10","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Une femme demande l'implantation d'embryons congelés créés avec son ex-compagnon, qui retire son consentement.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"La loi qui permet au géniteur de retirer son consentement jusqu'à l'implantation viole-t-elle l'article 8 ?","solution":"Non : l'exigence du consentement des deux parties à toutes les étapes ménage un juste équilibre ; la femme ne peut imposer l'implantation.","portee":"Illustre la marge d'appréciation en bioéthique.","tags":["embryons","consentement","vie privée"],"id":"seed-jp-2007-04-10-evans-c-royaume-uni-gc"},{"titre":"Saadi c. Italie (GC)","juridiction":"CEDH","date":"2008-02-28","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un ressortissant tunisien condamné en Italie pour terrorisme est menacé d'expulsion vers la Tunisie, où il risque d'être torturé ; l'Italie invoque la menace qu'il représente.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'État peut-il, au nom de la sécurité nationale, expulser un étranger vers un pays où il risque la torture ?","solution":"Non : la protection de l'article 3 est absolue ; la dangerosité de la personne ne peut être mise en balance avec le risque de mauvais traitements ; l'expulsion est contraire à la Convention.","portee":"Réaffirme que l'interdiction de la torture ne souffre aucune exception, même dans la lutte contre le terrorisme.","tags":["article 3","terrorisme","expulsion","caractère absolu"],"id":"seed-jp-2008-02-28-saadi-c-italie-gc"},{"titre":"Salduz c. Turquie (GC)","juridiction":"CEDH","date":"2008-11-27","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Un mineur est interrogé sans avocat pendant sa garde à vue, et ses aveux servent de base à sa condamnation.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"La personne gardée à vue peut-elle être interrogée sans avocat ?","solution":"Non : l'accès à un avocat doit en principe être consenti dès le premier interrogatoire de police, sauf raisons impérieuses ; les aveux obtenus en l'absence d'avocat ne doivent pas fonder une condamnation.","portee":"A imposé la réforme de la garde à vue en France (QPC 2010-14/22, loi du 14 avril 2011) ; v. Brusco c. France.","tags":["garde à vue","assistance de l'avocat","procès équitable"],"id":"seed-jp-2008-11-27-salduz-c-turquie-gc"},{"titre":"Scoppola c. Italie (n° 2) (GC)","juridiction":"CEDH","date":"2009-09-17","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un condamné se voit appliquer une peine de réclusion à perpétuité, alors qu'une loi plus douce était entrée en vigueur avant le jugement.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'article 7 de la Convention garantit-il la rétroactivité de la loi pénale plus douce ?","solution":"Oui : l'article 7 § 1 consacre non seulement le principe de non-rétroactivité de la loi pénale plus sévère, mais aussi, implicitement, celui de la rétroactivité de la loi pénale plus douce.","portee":"Revirement par rapport à X c. Royaume-Uni ; aligne la Convention sur la jurisprudence française (art. 112-1 du Code pénal).","tags":["rétroactivité de la loi pénale plus douce","article 7"],"id":"seed-jp-2009-09-17-scoppola-c-italie-n-2-gc"},{"titre":"Medvedyev et autres c. France (GC)","juridiction":"CEDH","date":"2010-03-29","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Un navire est arraisonné en haute mer par la marine française ; l'équipage est maintenu privé de liberté pendant plusieurs jours avant d'être présenté à un juge.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le procureur de la République est-il une « autorité judiciaire » au sens de l'article 5 § 3 ?","solution":"Non : le procureur n'offre pas les garanties d'indépendance requises vis-à-vis de l'exécutif et des parties ; l'article 5 § 3 est violé. La privation de liberté en mer a été jugée non fondée sur une base légale suffisante.","portee":"Prolongée par Moulin c. France (2010) ; elle alimente le débat sur le statut du parquet.","tags":["privation de liberté","autorité judiciaire","article 5"],"id":"seed-jp-2010-03-29-medvedyev-et-autres-c-france-gc"},{"titre":"Schalk et Kopf c. Autriche","juridiction":"CEDH","date":"2010-06-24","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Deux hommes vivant en couple se voient refuser le mariage en Autriche ; la loi sur le partenariat enregistré n'était pas encore en vigueur.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"La Convention impose-t-elle d'ouvrir le mariage aux couples de même sexe ?","solution":"Non : l'article 12 ne l'impose pas ; les États disposent d'une marge d'appréciation ; mais la relation du couple relève de la « vie familiale » au sens de l'article 8.","portee":"Fait de la vie de couple homosexuel une « vie familiale » ; la Cour impose ensuite une forme de reconnaissance juridique (Oliari c. Italie, 2015).","tags":["mariage homosexuel","vie familiale","article 12"],"id":"seed-jp-2010-06-24-schalk-et-kopf-c-autriche"},{"titre":"Brusco c. France","juridiction":"CEDH","date":"2010-10-14","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une personne est placée en garde à vue et interrogée sans avoir été informée de son droit de se taire ni assistée d'un avocat.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Le droit français de la garde à vue de 2010 satisfait-il aux exigences de l'article 6 ?","solution":"Non : l'absence d'assistance d'un avocat et de notification du droit de garder le silence a porté atteinte au droit de ne pas contribuer à sa propre incrimination.","portee":"Premier arrêt contre la France sur la garde à vue ; appelle la réforme de 2011.","tags":["garde à vue","droit de se taire","avocat"],"id":"seed-jp-2010-10-14-brusco-c-france"},{"titre":"Moulin c. France","juridiction":"CEDH","date":"2010-11-23","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une avocate est placée en garde à vue puis présentée à un procureur, non à un juge, avant d'être mise en détention.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"Les magistrats du parquet français peuvent-ils exercer le contrôle de la détention exigé par l'article 5 § 3 ?","solution":"Non : le procureur de la République n'est pas un magistrat habilité à exercer des fonctions judiciaires, car il est partie poursuivante et placé sous l'autorité du garde des Sceaux.","portee":"Consacre la distinction entre magistrats du siège et du parquet ; le Conseil constitutionnel maintient l'autorité judiciaire de l'article 66 pour les deux.","tags":["parquet","autorité judiciaire","article 5 § 3"],"id":"seed-jp-2010-11-23-moulin-c-france"},{"titre":"M.S.S. c. Belgique et Grèce (GC)","juridiction":"CEDH","date":"2011-01-21","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Un demandeur d'asile afghan est renvoyé de Belgique vers la Grèce en application du règlement Dublin, où il subit des conditions de vie dégradantes.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Un État peut-il transférer un demandeur d'asile vers un autre État membre en présence de défaillances systémiques ?","solution":"Non : la Belgique a violé l'article 3 en exposant le requérant aux déficiences du système d'asile grec ; la Grèce a violé l'article 3 par ses conditions de détention et de vie.","portee":"A conduit la CJUE à juger (N.S., 21 décembre 2011) qu'un transfert Dublin est exclu en cas de défaillances systémiques.","tags":["asile","Dublin","traitements inhumains"],"id":"seed-jp-2011-01-21-m-s-s-c-belgique-et-grece-gc"},{"titre":"Lautsi c. Italie (GC)","juridiction":"CEDH","date":"2011-03-18","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une mère demande le retrait des crucifix des salles de classe de l'école publique de ses enfants.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"La présence de crucifix dans les salles de classe viole-t-elle le droit à l'instruction et la liberté de religion ?","solution":"Non : la décision d'accrocher ou non des crucifix relève de la marge d'appréciation de l'État ; le crucifix est un symbole essentiellement passif, sans effet d'endoctrinement avéré.","portee":"Renverse l'arrêt de chambre de 2009 ; confirme la marge d'appréciation en matière religieuse.","tags":["crucifix","école","neutralité"],"id":"seed-jp-2011-03-18-lautsi-c-italie-gc"},{"titre":"Al-Skeini et autres c. Royaume-Uni (GC)","juridiction":"CEDH","date":"2011-07-07","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Des civils irakiens sont tués par des soldats britanniques à Bassora en 2003 ; leurs proches se plaignent de l'absence d'enquête effective.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Les victimes d'opérations militaires à l'étranger relèvent-elles de la juridiction de l'État au sens de l'article 1er ?","solution":"Oui : lorsqu'un État exerce un contrôle et une autorité sur une personne par l'usage de la force, y compris en dehors de son territoire, il a l'obligation de garantir les droits de la Convention ; le Royaume-Uni a violé l'article 2, faute d'enquête indépendante.","portee":"Étend la juridiction extraterritoriale de la Convention, sur le fondement de l'autorité exercée sur la personne.","tags":["juridiction extraterritoriale","Irak","enquête"],"id":"seed-jp-2011-07-07-al-skeini-et-autres-c-royaume-uni-gc"},{"titre":"Axel Springer AG c. Allemagne (GC)","juridiction":"CEDH","date":"2012-02-07","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un journal est condamné à ne plus publier des informations sur l'interpellation d'un acteur célèbre pour détention de drogue.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Quels critères gouvernent la mise en balance entre la liberté d'expression et le droit au respect de la vie privée ?","solution":"La Cour énonce six critères : contribution à un débat d'intérêt général, notoriété de la personne, comportement antérieur, mode d'obtention et véracité de l'information, contenu et forme, gravité de la sanction ; l'interdiction viole l'article 10.","portee":"Reprise systématique de ces critères par les juges nationaux (Cour de cassation, Conseil d'État).","tags":["liberté de la presse","vie privée","critères"],"id":"seed-jp-2012-02-07-axel-springer-ag-c-allemagne-gc"},{"titre":"Hirsi Jamaa et autres c. Italie (GC)","juridiction":"CEDH","date":"2012-02-23","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Des migrants interceptés en haute mer par des navires italiens sont reconduits en Libye sans examen individuel de leur situation.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Un État peut-il renvoyer des migrants interceptés en mer vers un pays où ils risquent des mauvais traitements ?","solution":"Non : les personnes interceptées en haute mer relèvent de la juridiction de l'État dont les navires les ont interceptées ; le refoulement sans examen viole l'article 3 et l'article 4 du Protocole n° 4 (interdiction des expulsions collectives).","portee":"Étend l'application extraterritoriale de la Convention aux opérations en mer.","tags":["refoulement en mer","interdiction des expulsions collectives","article 3"],"id":"seed-jp-2012-02-23-hirsi-jamaa-et-autres-c-italie-gc"},{"titre":"El-Masri c. Macédoine (GC)","juridiction":"CEDH","date":"2012-12-13","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Un citoyen allemand est arrêté en Macédoine, remis à la CIA et transféré en Afghanistan, où il est maltraité.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"La Macédoine est-elle responsable des traitements infligés à la personne, qu'elle a remise à des agents étrangers ?","solution":"Oui : l'État est responsable des actes commis sur son territoire avec son concours et du transfert vers un lieu où le risque de mauvais traitements était connu ; violations des articles 3, 5, 8 et 13.","portee":"Condamnation majeure des « restitutions extraordinaires » ; elle consacre le droit à la vérité des victimes.","tags":["restitutions extraordinaires","torture","responsabilité des États"],"id":"seed-jp-2012-12-13-el-masri-c-macedoine-gc"},{"titre":"Del Río Prada c. Espagne (GC)","juridiction":"CEDH","date":"2013-10-21","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Une condamnée pour terrorisme voit sa libération repoussée de neuf ans par un revirement de jurisprudence sur le calcul des remises de peine.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'application rétroactive d'une jurisprudence modifiant la portée d'une peine viole-t-elle l'article 7 ?","solution":"Oui : la mesure ne concerne pas la seule exécution de la peine mais sa portée même, qui n'était pas prévisible lors des faits ; violation des articles 7 et 5.","portee":"Étend la prévisibilité de la loi pénale à la durée effective de la peine.","tags":["légalité pénale","peine","exécution","rétroactivité"],"id":"seed-jp-2013-10-21-del-rio-prada-c-espagne-gc"},{"titre":"Mennesson c. France","juridiction":"CEDH","date":"2014-06-26","matiere":"Libertés fondamentales et CEDH","niveau":"L2-L3","faits":"Des enfants nés d'une gestation pour autrui aux États-Unis n'obtiennent pas la transcription de leur acte de naissance étranger à l'état civil français.","procedure":"Requête devant la Cour européenne des droits de l'homme, qui statue le même jour dans l'affaire Labassée c. France.","probleme":"Le refus de reconnaître la filiation établie à l'étranger entre les enfants et leur père biologique est-il compatible avec l'article 8 ?","solution":"Non : le refus de transcrire la filiation à l'égard du père biologique porte atteinte à l'identité des enfants, protégée par le respect de la vie privée ; l'intérêt supérieur de l'enfant doit primer. Pas de violation s'agissant de la vie familiale des parents.","portee":"Conduit aux arrêts du 3 juillet 2015 de l'assemblée plénière et à l'avis de la CEDH du 10 avril 2019 (premier avis consultatif, protocole n° 16).","tags":["gestation pour autrui","filiation","intérêt de l'enfant"],"id":"seed-jp-2014-06-26-mennesson-c-france"},{"titre":"S.A.S. c. France (GC)","juridiction":"CEDH","date":"2014-07-01","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"Une femme de confession musulmane conteste la loi du 11 octobre 2010 interdisant la dissimulation du visage dans l'espace public.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'interdiction du voile intégral dans l'espace public est-elle compatible avec la liberté de religion et la vie privée ?","solution":"Oui, au titre d'un but légitime : les « exigences minimales de la vie en société », le « vivre ensemble » ; l'ingérence est proportionnée, dans la marge d'appréciation de l'État.","portee":"Consacre le « vivre ensemble » comme but légitime ; très critiquée par la doctrine.","tags":["voile intégral","laïcité","vivre ensemble"],"id":"seed-jp-2014-07-01-s-a-s-c-france-gc"},{"titre":"Tarakhel c. Suisse (GC)","juridiction":"CEDH","date":"2014-11-04","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Une famille afghane avec six enfants doit être renvoyée vers l'Italie, où l'accueil des familles de demandeurs d'asile est insuffisant.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le transfert Dublin d'une famille avec enfants est-il licite sans garanties individuelles sur l'accueil ?","solution":"Non : le transfert vers l'Italie sans assurance que la famille soit prise en charge dans des conditions adaptées à l'âge des enfants violerait l'article 3.","portee":"Précise les obligations de l'État requérant avant un transfert Dublin.","tags":["asile","Dublin","enfants","garanties"],"id":"seed-jp-2014-11-04-tarakhel-c-suisse-gc"},{"titre":"Lambert et autres c. France (GC)","juridiction":"CEDH","date":"2015-06-05","matiere":"Libertés fondamentales et CEDH","niveau":"L3-M1","faits":"La famille d'un patient en état végétatif conteste la décision médicale d'arrêter l'alimentation et l'hydratation artificielles.","procedure":"Requête devant la Grande chambre, après un arrêt du Conseil d'État, Ass., 24 juin 2014.","probleme":"L'arrêt de l'alimentation et de l'hydratation artificielles viole-t-il l'article 2 ?","solution":"Non : le cadre législatif français (loi Leonetti) et la procédure suivie sont conformes à l'article 2 ; la marge d'appréciation est large en l'absence de consensus européen.","portee":"Valide le dispositif français de la fin de vie ; la décision médicale collégiale est contrôlée par le juge.","tags":["fin de vie","arrêt des soins","article 2"],"id":"seed-jp-2015-06-05-lambert-et-autres-c-france-gc"},{"titre":"Oliari et autres c. Italie","juridiction":"CEDH","date":"2015-07-21","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Des couples de même sexe se plaignent de l'absence de toute reconnaissance juridique de leur union en Italie.","procedure":"Requête devant la Cour européenne des droits de l'homme.","probleme":"L'absence de reconnaissance légale de toute forme d'union pour les couples de même sexe viole-t-elle l'article 8 ?","solution":"Oui : l'article 8 impose à l'État une obligation positive de prévoir un cadre juridique permettant aux couples de même sexe d'obtenir la reconnaissance de leur union ; l'Italie a dépassé sa marge d'appréciation.","portee":"Impose aux États une forme d'union civile ; décision de principe sur les obligations positives.","tags":["union civile","couples de même sexe","obligation positive"],"id":"seed-jp-2015-07-21-oliari-et-autres-c-italie"},{"titre":"Perinçek c. Suisse (GC)","juridiction":"CEDH","date":"2015-10-15","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Un homme politique turc est condamné en Suisse pour avoir nié la qualification de génocide du massacre des Arméniens.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"La condamnation pénale pour négation d'un génocide autre que la Shoah viole-t-elle la liberté d'expression ?","solution":"Oui : la condamnation n'était pas nécessaire dans une société démocratique ; les propos ne comportaient pas d'appel à la haine ; il n'existe pas de consensus judiciaire comparable à celui de la Shoah qui justifierait cette ingérence.","portee":"Illustre la protection de l'expression sur des sujets historiques controversés ; différence avec Garaudy c. France (décision, 2003).","tags":["liberté d'expression","négationnisme","génocide arménien"],"id":"seed-jp-2015-10-15-perincek-c-suisse-gc"},{"titre":"Paradiso et Campanelli c. Italie (GC)","juridiction":"CEDH","date":"2017-01-24","matiere":"Libertés fondamentales et CEDH","niveau":"M1","faits":"Un couple italien, qui avait eu recours à une mère porteuse en Russie, se voit retirer l'enfant, aucun lien biologique n'étant établi avec lui.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"Le retrait de l'enfant à un couple qui a recouru à la gestation pour autrui sans lien biologique viole-t-il l'article 8 ?","solution":"Non : la durée de la vie commune était trop courte pour constituer une vie familiale ; l'intérêt de l'enfant et la lutte contre les pratiques illégales justifient l'éloignement ; la Cour laisse une large marge d'appréciation.","portee":"Nuance Mennesson : l'absence de lien biologique ne donne pas lieu à protection au titre de la vie familiale.","tags":["gestation pour autrui","vie familiale","ordre public"],"id":"seed-jp-2017-01-24-paradiso-et-campanelli-c-italie-gc"},{"titre":"N.D. et N.T. c. Espagne (GC)","juridiction":"CEDH","date":"2020-02-13","matiere":"Libertés fondamentales et CEDH","niveau":"M2","faits":"Deux migrants franchissent la clôture de Melilla ; ils sont immédiatement refoulés au Maroc par la Garde civile, sans procédure individuelle.","procedure":"Requête devant la Grande chambre de la Cour européenne des droits de l'homme.","probleme":"L'interdiction des expulsions collectives s'oppose-t-elle à des refoulements immédiats à la frontière ?","solution":"Non, dans les circonstances : l'absence de procédure individuelle est imputable au comportement des requérants, qui ont tenté de passer en force sans recourir aux voies légales d'accès existantes ; pas de violation de l'article 4 du Protocole n° 4.","portee":"Arrêt très discuté, qui limite la protection des migrants à la frontière.","tags":["expulsions collectives","frontière","refoulement immédiat"],"id":"seed-jp-2020-02-13-n-d-et-n-t-c-espagne-gc"},{"titre":"Cesareo (Ass. plén.)","juridiction":"Cour de cassation","date":"2006-07-07","matiere":"Procédure civile","niveau":"L3","faits":"Après avoir été débouté d'une première demande, un justiciable présente une nouvelle demande fondée sur un moyen qu'il aurait pu invoquer lors de la première instance.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation.","probleme":"Le demandeur peut-il, dans une seconde instance, invoquer un fondement juridique qu'il n'avait pas soulevé dans la première ?","solution":"Non : il incombe au demandeur de présenter dès l'instance relative à la première demande l'ensemble des moyens qu'il estime de nature à fonder celle-ci ; il ne peut invoquer dans une instance postérieure un fondement juridique qu'il s'était abstenu de soulever.","portee":"Principe de concentration des moyens ; il renforce l'autorité de la chose jugée au sens de l'article 1355 du Code civil.","tags":["concentration des moyens","autorité de la chose jugée"],"id":"seed-jp-2006-07-07-cesareo-ass-plen"},{"titre":"Preuve déloyale — enregistrement (Ass. plén.)","juridiction":"Cour de cassation","date":"2011-01-07","matiere":"Procédure civile","niveau":"L3-M1","faits":"Un justiciable produit en justice l'enregistrement d'une conversation téléphonique à l'insu de son interlocuteur.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation.","probleme":"La production d'un enregistrement réalisé à l'insu de son auteur est-elle admissible en justice ?","solution":"Non : l'enregistrement d'une conversation téléphonique privée, effectué et conservé à l'insu de l'auteur des propos invoqués, est un procédé déloyal rendant irrecevable sa production à titre de preuve.","portee":"Principe d'irrecevabilité de la preuve déloyale en matière civile ; atténué par l'arrêt de l'assemblée plénière du 22 décembre 2023.","tags":["preuve","loyauté","enregistrement téléphonique"],"id":"seed-jp-2011-01-07-preuve-deloyale-enregistrement-ass-plen"},{"titre":"Preuve déloyale — nouvelle règle (Ass. plén.)","juridiction":"Cour de cassation","date":"2023-12-22","matiere":"Procédure civile","niveau":"M1-M2","faits":"Dans deux affaires, des parties invoquent des preuves obtenues de manière déloyale (enregistrement, procédé caché) pour établir un fait.","procedure":"Pourvois devant l'assemblée plénière de la Cour de cassation.","probleme":"Une preuve obtenue de façon déloyale doit-elle toujours être écartée ?","solution":"Non : le juge doit apprécier si l'utilisation de la preuve déloyale porte une atteinte au caractère équitable de la procédure, en mettant en balance le droit à la preuve et les droits antinomiques en présence ; la preuve est admissible si elle est indispensable à l'exercice du droit à la preuve et si l'atteinte aux droits adverses est strictement proportionnée.","portee":"Revirement : abandon de l'irrecevabilité automatique des preuves déloyales, au profit d'un contrôle de proportionnalité.","tags":["preuve","loyauté","droit à la preuve","proportionnalité"],"id":"seed-jp-2023-12-22-preuve-deloyale-nouvelle-regle-ass-plen"},{"titre":"Schuller-Maréchal (Crim.)","juridiction":"Cour de cassation","date":"1996-02-27","matiere":"Procédure pénale","niveau":"L3-M1","faits":"Des policiers incitent une personne à participer à une opération illicite, pour recueillir la preuve d'une infraction.","procedure":"Pourvoi devant la chambre criminelle de la Cour de cassation.","probleme":"La preuve recueillie par un stratagème de la police est-elle recevable ?","solution":"Non, si le stratagème porte atteinte à la loyauté de la preuve : si la provocation policière a déterminé la commission de l'infraction, elle vicie la procédure ; la preuve ainsi obtenue ne peut fonder la condamnation.","portee":"Fixe la frontière entre infiltration (licite) et provocation (illicite) ; alignement sur Teixeira de Castro (CEDH, 1998).","tags":["loyauté de la preuve","provocation policière","stratagème"],"id":"seed-jp-1996-02-27-schuller-marechal-crim"},{"titre":"Garde à vue — assistance de l'avocat (Ass. plén.)","juridiction":"Cour de cassation","date":"2011-04-15","matiere":"Procédure pénale","niveau":"L3-M1","faits":"Des personnes sont placées en garde à vue et interrogées sans avoir pu être assistées d'un avocat.","procedure":"Quatre pourvois devant l'assemblée plénière de la Cour de cassation, à la suite de la décision du Conseil constitutionnel de juillet 2010.","probleme":"Les règles françaises de la garde à vue, qui n'assuraient pas l'assistance effective d'un avocat, sont-elles conformes à l'article 6 de la Convention ?","solution":"Non : les États adhérents à la Convention sont tenus de respecter les décisions de la Cour européenne sans attendre une modification de leur législation ; pour que le procès soit équitable, la personne gardée à vue doit pouvoir être assistée d'un avocat dès le début de la mesure et durant ses interrogatoires.","portee":"Rend effectif en droit interne le droit à l'avocat en garde à vue ; la loi du 14 avril 2011 en a tiré les conséquences.","tags":["garde à vue","avocat","procès équitable"],"id":"seed-jp-2011-04-15-garde-a-vue-assistance-de-l-avocat-ass-p"},{"titre":"Teffaine (Civ.)","juridiction":"Cour de cassation","date":"1896-06-16","matiere":"Responsabilité civile","niveau":"L2","faits":"Un remorqueur à vapeur explose et tue un ouvrier ; l'explosion est due à un vice de construction de la machine, sans faute prouvée du propriétaire.","procedure":"Pourvoi devant la chambre civile de la Cour de cassation.","probleme":"L'article 1384, alinéa 1er, du Code civil (aujourd'hui art. 1242) pose-t-il un principe de responsabilité du fait des choses, ou n'est-il qu'une simple annonce des articles suivants ?","solution":"Il pose un principe général de responsabilité du fait des choses que l'on a sous sa garde : le gardien est responsable de plein droit du dommage causé par la chose, sans avoir à prouver une faute.","portee":"Naissance du principe général de responsabilité du fait des choses ; la loi du 9 avril 1898 sur les accidents du travail avait entre-temps pris le relais pour les ouvriers.","tags":["fait des choses","grand arrêt","art. 1384"],"id":"seed-jp-1896-06-16-teffaine-civ"},{"titre":"Clément-Bayard (Req.)","juridiction":"Cour de cassation","date":"1915-08-03","matiere":"Responsabilité civile","niveau":"L1-L2","faits":"Un propriétaire dresse sur son terrain de hautes tiges de fer pointues, uniquement pour gêner les dirigeables d'un voisin constructeur ; elles ne lui servent à rien.","procedure":"Pourvoi devant la chambre des requêtes de la Cour de cassation.","probleme":"Le propriétaire peut-il invoquer son droit de propriété pour faire ce qui nuit à autrui sans intérêt légitime ?","solution":"Non : le droit de propriété n'est pas absolu ; son exercice dans l'unique intention de nuire constitue un abus de droit qui engage la responsabilité de son auteur ; les installations doivent être supprimées.","portee":"Arrêt fondateur de la théorie de l'abus de droit, appliquée à la propriété ; critère de l'intention de nuire.","tags":["abus de droit","propriété","voisinage"],"id":"seed-jp-1915-08-03-clement-bayard-req"},{"titre":"Jand'heur (Ch. réun.)","juridiction":"Cour de cassation","date":"1930-02-13","matiere":"Responsabilité civile","niveau":"L2","faits":"Une enfant est renversée et blessée par un camion automobile ; la cause exacte de l'accident reste inconnue.","procedure":"Les chambres réunies de la Cour de cassation, saisies après une cassation avec renvoi, statuent sur le principe.","probleme":"La présomption de l'article 1384, alinéa 1er, vaut-elle pour toutes les choses, y compris les automobiles, et comment s'en exonérer ?","solution":"Oui : la présomption de responsabilité à l'encontre du gardien de la chose qui a causé un dommage s'applique à toutes les choses, mobiles ou immobiles, dangereuses ou non. Elle ne se détruit que par la preuve d'un cas fortuit, d'une force majeure ou d'une cause étrangère non imputable au gardien ; il ne suffit pas de prouver l'absence de faute ou que la cause du dommage est demeurée inconnue.","portee":"Consacre définitivement la responsabilité générale du fait des choses, devenue un régime de responsabilité de plein droit ; régime fondateur de la loi du 5 juillet 1985 sur les accidents de la circulation.","tags":["fait des choses","présomption de responsabilité","grand arrêt"],"attendu":"La présomption de responsabilité établie par l'article 1384, alinéa 1er, à l'encontre de celui qui a sous sa garde la chose inanimée qui a causé un dommage à autrui ne peut être détruite que par la preuve d'un cas fortuit ou de force majeure ou d'une cause étrangère qui ne lui soit pas imputable ; il ne suffit pas de prouver qu'il n'a commis aucune faute ou que la cause du fait dommageable est demeurée inconnue.","id":"seed-jp-1930-02-13-jand-heur-ch-reun"},{"titre":"Franck (Ch. réun.)","juridiction":"Cour de cassation","date":"1941-12-02","matiere":"Responsabilité civile","niveau":"L2","faits":"Une voiture est volée ; le voleur cause un accident et la victime assigne le propriétaire de la voiture, gardien juridique, en réparation.","procedure":"Pourvoi devant les chambres réunies de la Cour de cassation.","probleme":"Qui est le gardien de la chose, au sens de l'article 1384, alinéa 1er : le propriétaire dépossédé par un vol ou celui qui a pris la chose ?","solution":"Le gardien est celui qui a l'usage, la direction et le contrôle de la chose ; le propriétaire dépossédé par un vol ne l'est plus ; il n'est plus responsable de l'accident causé par le voleur.","portee":"Définit la garde par un critère matériel (usage, direction, contrôle), distinct de la propriété ; critère toujours utilisé en matière de responsabilité du fait des choses.","tags":["garde","usage direction contrôle","vol"],"id":"seed-jp-1941-12-02-franck-ch-reun"},{"titre":"Oxygène liquide (2e civ.)","juridiction":"Cour de cassation","date":"1956-01-05","matiere":"Responsabilité civile","niveau":"L2","faits":"Un récipient contenant de l'oxygène liquide explose et cause des dommages ; la question se pose de savoir qui en avait la garde.","procedure":"Pourvoi devant la deuxième chambre civile de la Cour de cassation.","probleme":"Quand la chose est dangereuse par sa structure, qui en est le gardien : celui qui l'utilise ou celui qui l'a fabriquée ou remplie ?","solution":"La garde se divise : le fabricant ou le propriétaire reste gardien de la structure quand le dommage tient à un vice interne de la chose, tandis que l'utilisateur est gardien du comportement ; seul le gardien de la structure répond d'un dommage dû à la structure.","portee":"Théorie de la garde de la structure et de la garde du comportement (Goldman) ; elle précise Franck (1941), mais est discutée en doctrine.","tags":["garde de la structure","garde du comportement","fait des choses"],"id":"seed-jp-1956-01-05-oxygene-liquide-2e-civ"},{"titre":"Desmares (2e civ.)","juridiction":"Cour de cassation","date":"1982-07-21","matiere":"Responsabilité civile","niveau":"L2","faits":"Un automobiliste renverse un piéton qui a commis une imprudence en traversant la chaussée ; le dommage résulte à la fois de l'accident et de la faute de la victime.","procedure":"Pourvoi devant la deuxième chambre civile de la Cour de cassation.","probleme":"La faute de la victime exonère-t-elle partiellement le gardien de la chose quand elle n'a pas présenté les caractères de la force majeure ?","solution":"Non : seule la force majeure permet au gardien de s'exonérer totalement ; la faute de la victime, quand elle n'a pas les caractères de la force majeure, n'exonère pas le gardien, même en partie.","portee":"Cet arrêt, très sévère pour le gardien, est abandonné par l'arrêt Bertrand (1997) puis a conduit à la loi du 5 juillet 1985 ; il est aujourd'hui dépassé par l'exonération partielle admise en droit commun.","tags":["fait de la victime","exonération","responsabilité du fait des choses"],"id":"seed-jp-1982-07-21-desmares-2e-civ"},{"titre":"Derguini (Ass. plén.)","juridiction":"Cour de cassation","date":"1984-05-09","matiere":"Responsabilité civile","niveau":"L2","faits":"Une fillette de cinq ans s'élance sur la chaussée et est mortellement renversée par une voiture.","procedure":"L'assemblée plénière de la Cour de cassation examine si la faute de la victime peut être retenue contre une enfant dépourvue de discernement.","probleme":"La faute de la victime, qui peut exonérer partiellement l'auteur du dommage, suppose-t-elle que la victime ait eu le discernement ?","solution":"Non : un enfant, même en bas âge, peut commettre une faute de nature à limiter son droit à réparation, sans que soit exigée la capacité de discerner la portée de son acte.","portee":"Détache la faute civile de l'imputabilité morale ; étendue par la loi du 5 juillet 1985 qui protège cependant certaines victimes (enfants de moins de 16 ans).","tags":["faute de la victime","discernement","enfant"],"id":"seed-jp-1984-05-09-derguini-ass-plen"},{"titre":"Troubles anormaux de voisinage (2e civ.)","juridiction":"Cour de cassation","date":"1986-11-19","matiere":"Responsabilité civile","niveau":"L2","faits":"Des voisins subissent des nuisances causées par des travaux voisins ; ils demandent réparation sans prouver de faute.","procedure":"Pourvoi devant la deuxième chambre civile de la Cour de cassation.","probleme":"La victime d'un trouble de voisinage doit-elle prouver une faute de son voisin pour obtenir réparation ?","solution":"Non : nul ne doit causer à autrui un trouble anormal de voisinage ; la responsabilité est engagée sans faute dès lors que le trouble dépasse les inconvénients normaux du voisinage.","portee":"Principe autonome de responsabilité sans faute pour troubles anormaux de voisinage, souvent rattaché à l'article 544 du Code civil et consacré par l'article 1253 du Code civil depuis 2024.","tags":["voisinage","trouble anormal","responsabilité sans faute"],"id":"seed-jp-1986-11-19-troubles-anormaux-de-voisinage-2e-civ"},{"titre":"Blieck (Ass. plén.)","juridiction":"Cour de cassation","date":"1991-03-29","matiere":"Responsabilité civile","niveau":"L2-L3","faits":"Un handicapé mental accueilli dans un centre d'aide par le travail met le feu à une forêt voisine, causant de lourds dégâts.","procedure":"L'assureur du propriétaire demande réparation à l'association qui gère le centre ; la cour d'appel la condamne ; pourvoi devant l'assemblée plénière.","probleme":"Existe-t-il, en dehors des cas listés par le Code civil, un principe général de responsabilité du fait d'autrui ?","solution":"Oui : l'association qui accepte la charge d'organiser, de diriger et de contrôler à titre permanent le mode de vie d'un handicapé doit répondre de ce dernier au sens de l'article 1384, alinéa 1er ; elle est responsable de plein droit des dommages qu'il cause.","portee":"Découverte d'un principe général de responsabilité du fait d'autrui ; étendu ensuite aux associations sportives (Cass. 2e civ., 22 mai 1995) et à l'organisation permanente d'activités à risque.","tags":["fait d'autrui","art. 1384 al. 1","grand arrêt"],"id":"seed-jp-1991-03-29-blieck-ass-plen"},{"titre":"Bertrand (2e civ.)","juridiction":"Cour de cassation","date":"1997-02-19","matiere":"Responsabilité civile","niveau":"L2","faits":"Un enfant de douze ans, à bicyclette, heurte une motocyclette ; la victime réclame réparation à son père, qui invoque l'absence de faute de surveillance ou d'éducation.","procedure":"Pourvoi devant la deuxième chambre civile de la Cour de cassation.","probleme":"La responsabilité des parents du fait de leur enfant mineur suppose-t-elle une faute de surveillance ou d'éducation ?","solution":"Non : la responsabilité de plein droit des père et mère n'est pas subordonnée à la preuve d'une faute ; les parents ne peuvent s'exonérer qu'en prouvant la force majeure ou la faute de la victime.","portee":"Mène à un régime objectif de responsabilité des parents (art. 1242, al. 4) ; la preuve d'une bonne éducation n'exonère plus.","tags":["responsabilité des parents","fait du mineur","plein droit"],"id":"seed-jp-1997-02-19-bertrand-2e-civ"},{"titre":"Hédreul (1re civ.)","juridiction":"Cour de cassation","date":"1997-02-25","matiere":"Responsabilité civile","niveau":"L2-L3","faits":"Un patient subit une coloscopie avec ablation d'un polype, au cours de laquelle survient une perforation intestinale ; il reproche au médecin de ne pas l'avoir informé de ce risque.","procedure":"Pourvoi devant la première chambre civile de la Cour de cassation.","probleme":"À qui incombe la preuve de l'exécution de l'obligation d'information du médecin ?","solution":"Au médecin : celui qui est légalement ou contractuellement tenu d'une obligation particulière d'information doit rapporter la preuve de son exécution ; il peut le faire par tout moyen.","portee":"Renverse la charge de la preuve de l'information médicale ; repris à l'article L. 1111-2 du Code de la santé publique (loi du 4 mars 2002).","tags":["information du patient","preuve","médecin"],"attendu":"Celui qui est légalement ou contractuellement tenu d'une obligation particulière d'information doit rapporter la preuve de l'exécution de cette obligation.","id":"seed-jp-1997-02-25-hedreul-1re-civ"},{"titre":"Castagnet (1re civ.)","juridiction":"Cour de cassation","date":"1998-10-07","matiere":"Responsabilité civile","niveau":"L2-L3","faits":"Une patiente subit une intervention chirurgicale à la suite de laquelle survient une complication grave ; elle reproche au chirurgien de ne pas l'avoir informée de ce risque très rare.","procedure":"La cour d'appel de Lyon l'avait déboutée, au motif que le chirurgien n'était tenu d'informer que des risques normalement prévisibles ; pourvoi devant la première chambre civile.","probleme":"Le médecin est-il dispensé d'informer le patient d'un risque grave lorsque ce risque ne se réalise qu'exceptionnellement ?","solution":"Non : sauf urgence, impossibilité ou refus du patient d'être informé, le médecin doit donner une information loyale, claire et appropriée sur les risques graves de l'investigation ou du soin proposé ; la rareté du risque ne l'en dispense pas.","portee":"Étend l'obligation d'information aux risques graves, même exceptionnels ; fonde la protection de l'autonomie du patient.","tags":["information du patient","risque exceptionnel","médecin"],"attendu":"Hormis les cas d'urgence, d'impossibilité ou de refus du patient d'être informé, un médecin est tenu de lui donner une information loyale, claire et appropriée sur les risques graves afférents aux investigations et soins proposés et il n'est pas dispensé de cette obligation par le seul fait que ces risques ne se réalisent qu'exceptionnellement.","id":"seed-jp-1998-10-07-castagnet-1re-civ"},{"titre":"Costedoat (Ass. plén.)","juridiction":"Cour de cassation","date":"2000-02-25","matiere":"Responsabilité civile","niveau":"L2-L3","faits":"Un pilote d'hélicoptère, salarié d'une société, épand des herbicides dans des rizières de Camargue ; le vent porte les produits sur une propriété voisine dont les végétaux sont endommagés.","procedure":"La cour d'appel d'Aix-en-Provence retient la responsabilité personnelle du pilote ; pourvoi devant l'assemblée plénière.","probleme":"Le préposé peut-il être personnellement tenu envers la victime lorsqu'il agit dans le cadre de sa mission ?","solution":"Non : le préposé qui agit sans excéder les limites de la mission qui lui a été impartie par son commettant n'engage pas sa responsabilité à l'égard des tiers ; seul le commettant est responsable.","portee":"Immunité du préposé, limitée par l'arrêt Cousin (2001) pour les infractions intentionnelles.","tags":["préposé","commettant","immunité"],"attendu":"N'engage pas sa responsabilité à l'égard des tiers le préposé qui agit sans excéder les limites de la mission qui lui a été impartie par son commettant.","id":"seed-jp-2000-02-25-costedoat-ass-plen"},{"titre":"Perruche (Ass. plén.)","juridiction":"Cour de cassation","date":"2000-11-17","matiere":"Responsabilité civile","niveau":"L2-L3","faits":"Une femme enceinte, atteinte de la rubéole, n'est pas informée à cause d'erreurs médicales ; l'enfant naît gravement handicapé.","procedure":"Les parents agissent en leur nom et au nom de l'enfant contre le médecin et le laboratoire ; pourvoi devant l'assemblée plénière.","probleme":"L'enfant né handicapé peut-il demander réparation du préjudice résultant de son handicap, causé par une faute médicale ayant empêché sa mère d'interrompre sa grossesse ?","solution":"Oui : l'enfant peut demander la réparation du préjudice résultant de son handicap, lorsque les fautes commises par le médecin et le laboratoire ont empêché sa mère d'exercer son choix d'interrompre sa grossesse.","portee":"Arrêt très controversé, suivi par la loi du 4 mars 2002 (art. L. 114-5 du Code de l'action sociale et des familles) : « nul ne peut se prévaloir d'un préjudice du seul fait de sa naissance ».","tags":["préjudice de l'enfant","erreur de diagnostic","grand arrêt"],"id":"seed-jp-2000-11-17-perruche-ass-plen"},{"titre":"Cousin (Ass. plén.)","juridiction":"Cour de cassation","date":"2001-12-14","matiere":"Responsabilité civile","niveau":"L2-L3","faits":"Un comptable, salarié d'une société, obtient pour elle des subventions destinées à financer de faux contrats de qualification ; il est condamné pénalement pour faux, usage de faux et escroquerie.","procedure":"La cour d'appel de Paris le condamne à réparer le préjudice des tiers ; il invoque l'immunité de Costedoat, car il a agi sur ordre de son employeur ; pourvoi devant l'assemblée plénière.","probleme":"Le préposé condamné pour une infraction intentionnelle peut-il bénéficier de l'immunité de Costedoat ?","solution":"Non : le préposé condamné pénalement pour avoir intentionnellement commis, fût-ce sur l'ordre du commettant, une infraction ayant porté préjudice à un tiers, engage sa responsabilité civile à l'égard de celui-ci.","portee":"Exclut l'immunité du préposé en cas d'infraction intentionnelle ; la jurisprudence ultérieure parle d'une « faute pénale intentionnelle ».","tags":["préposé","infraction intentionnelle","commettant"],"id":"seed-jp-2001-12-14-cousin-ass-plen"},{"titre":"Préjudice d'anxiété — amiante (soc.)","juridiction":"Cour de cassation","date":"2010-05-11","matiere":"Responsabilité civile","niveau":"M1","faits":"Des salariés exposés à l'amiante dans leur entreprise, sans maladie déclarée, demandent réparation de leur angoisse de contracter une maladie grave.","procedure":"Pourvoi devant la chambre sociale de la Cour de cassation.","probleme":"Un salarié exposé à l'amiante peut-il demander réparation de l'anxiété résultant du risque de développer une maladie ?","solution":"Oui : les salariés, exposés à l'amiante et de ce fait placés dans une situation d'inquiétude permanente, subissent un préjudice d'anxiété indemnisable lorsque l'entreprise figure sur la liste ouvrant droit à l'allocation de cessation anticipée d'activité.","portee":"Premier arrêt sur le préjudice d'anxiété, étendu ensuite à d'autres substances nocives (Ass. plén., 5 avril 2019).","tags":["préjudice d'anxiété","amiante","travail"],"id":"seed-jp-2010-05-11-prejudice-d-anxiete-amiante-soc"},{"titre":"Erika (Crim.)","juridiction":"Cour de cassation","date":"2012-09-25","matiere":"Responsabilité civile","niveau":"M1","faits":"Le pétrolier Erika se brise au large de la Bretagne en 1999 et provoque une marée noire ; des collectivités et associations demandent réparation.","procedure":"Pourvoi devant la chambre criminelle de la Cour de cassation contre l'arrêt de la cour d'appel de Paris.","probleme":"Le préjudice écologique pur peut-il être réparé, et les sociétés mises en cause peuvent-elles être déclarées pénalement responsables ?","solution":"Oui : la Cour confirme la réparation du préjudice écologique, atteinte directe ou indirecte à l'environnement, et retient la responsabilité pénale de la société Total SA, malgré l'application de la convention internationale sur la limitation de responsabilité.","portee":"Consécration du préjudice écologique, devenu en 2016 l'article 1246 du Code civil (loi du 8 août 2016).","tags":["préjudice écologique","pollution","responsabilité pénale"],"id":"seed-jp-2012-09-25-erika-crim"},{"titre":"Préjudice d'anxiété — substances nocives (Ass. plén.)","juridiction":"Cour de cassation","date":"2019-04-05","matiere":"Responsabilité civile","niveau":"M1-M2","faits":"Des salariés exposés à des substances nocives ou toxiques dans leur entreprise, hors du dispositif amiante, réclament l'indemnisation de leur anxiété.","procedure":"Pourvoi devant l'assemblée plénière de la Cour de cassation.","probleme":"Le préjudice d'anxiété est-il limité aux salariés de l'amiante ?","solution":"Non : le salarié qui justifie d'une exposition à une substance nocive ou toxique générant un risque élevé de développer une pathologie grave et d'un préjudice d'anxiété personnellement subi, résultant d'une telle exposition, peut agir contre l'employeur sur le fondement du droit commun de l'obligation de sécurité.","portee":"Élargit le préjudice d'anxiété, mais le subordonne à la preuve d'un manquement de l'employeur à son obligation de sécurité.","tags":["préjudice d'anxiété","santé au travail","obligation de sécurité"],"id":"seed-jp-2019-04-05-prejudice-d-anxiete-substances-nocives-a"}];
